t.guides["forever/class/paladin/tyrs-watch"] = (function() return {
		["Back to the keep"] = "回到要塞",
		["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep."] = "回到{area:16602}。{npc:246378}会给你{item:6866}；{npc:257655}在要塞楼下等候。",
		["Back to {area:16602}: Billmuth takes the plans, {npc:246378} teaches you {spell:7328}."] = "回到{area:16602}：比尔穆斯收下计划，{npc:246378}教你{spell:7328}。",
		["Tarnished Drudges"] = "{npc:259434}",
		["Tarnished Zealots"] = "{npc:259433}",
		["The Scarlet Crusaders camped around {area:812} carry the attack plans."] = "在{area:812}周围扎营的{npc:239036}身上带着进攻计划。",
		["The Scarlet attack plans"] = "血色十字军的进攻计划",
		["The Vile Fin murlocs lurk on the bluffs along the road east of the keep and in the camps around the lake to the west."] = "邪鳍鱼人潜伏在要塞东边道路沿线的悬崖上，以及西边湖泊周围的营地里。",
		["The {item:6866}"] = "{item:6866}",
		["Tyr's Watch and {spell:7328}"] = "Tyr's Watch与{spell:7328}",
		["Vile Fin Attackers"] = "{npc:250283}",
		["Vile Fin Seers"] = "{npc:250282}",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "从{area:159}向南走到{area:153}，再下到{zone:1458}。{npc:10181}在{object:36126}接见臣民；{npc:257648}在{object:36078}乞讨。",
		["{area:16602} stands on the bluffs north-west of the {area:156}. {npc:246349} waits at the gate."] = "{area:16602}位于{area:156}西北的悬崖上。{npc:246349}在大门口等候。",
		["{area:812} is at the far east end of the glades. Use the {item:6866} on {npc:257663}, then speak to him. If you lose the symbol, {npc:246378} gives you another."] = "{area:812}位于林地的最东端。对{npc:257663}使用{item:6866}，然后与他交谈。如果弄丢了圣物，{npc:246378}会再给你一个。",
		["{npc:246152}, who trains Paladins in {area:159}, sends you to the order's keep on the west coast."] = "在{area:159}训练圣骑士的{npc:246152}会让你去西海岸的修会要塞。",
		["{npc:246378} leads the order from inside the keep; {npc:246393} stands beside it."] = "{npc:246378}在要塞内领导修会；{npc:246393}站在一旁。",
		["{npc:246378} offers the first Lesson in Divinity at level 12."] = "{npc:246378}在12级时提供第一堂神圣课程。",
		["{npc:257648} needs 10 {item:2589}. Scarlet Zealots and Scarlet Friars drop it about three times in ten; bring it along if you already carry some."] = "{npc:257648}需要10块{item:2589}。{npc:1537}和{npc:1538}大约十次掉落三次；如果你身上已经有一些，带上即可。",
		["{object:554626}, in the root cellar"] = "{object:554626}，在地窖里",
		["{quest:91317} hold the ruined village of {area:16881} in the {area:16616}, south-west of the keep. The {item:246213} is piled in the root cellar of one of its houses; Commander {npc:259431} walks among his Tarnished."] = "{quest:91317}占据着要塞西南方{area:16616}中的废弃村庄{area:16881}。{item:246213}堆放在其中一座房屋的地窖里；{npc:259431}指挥官在他的部下之间走动。",
		["{spell:7328} to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin."] = "{spell:7328}可复活倒下的盟友，另有一把武器和一面盾牌，给新的被遗忘者圣骑士。",
} end)()
t.guides["forever/class/paladin/verigans-fist"] = (function() return {
		["At 20 {npc:6179} in the {object:32362} gives you the {item:6776}; it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the tram from {zone:1455} to {zone:1453}."] = "20级时，{object:32362}的{npc:6179}会给你{item:6776}；它会让你去找{zone:1453}光明大教堂的{npc:6171}。从{zone:1455}乘地铁前往{zone:1453}。",
		["Back to {npc:3649} in {area:442}: he purifies the gem."] = "回到{area:442}找{npc:3649}：他会净化宝石。",
		["Back to {npc:6241}"] = "回到{npc:6241}处",
		["Bring the four parts to {npc:6181} outside {zone:1455}."] = "把四个部件交给{zone:1455}外的{npc:6181}。",
		["Goblin Woodcarvers, inside"] = "地精木匠，在副本内",
		["Protect {npc:6182}"] = "保护{npc:6182}",
		["The Alliance paladin's rare two-handed mace for the 20s, with a shield on the way."] = "联盟圣骑士20多级的稀有双手锤，途中还能拿到一面盾牌。",
		["The Blackfathom naga by the entrance of {area:2797} on {zone:1440}'s north-west coast drop the {item:6995}. They are elite: grouping up is advised."] = "{zone:1440}西北海岸{area:2797}入口附近的黑暗深渊纳迦掉落{item:6995}。它们是精英：建议组队。",
		["The ore crate lies by the trees in the middle of the Mo'grosh ogre camp in north-east {zone:1432}. The Mo'grosh ogres are elite: grouping up is advised."] = "矿石箱放在{zone:1432}东北部莫格罗什食人魔营地中央的树旁。莫格罗什食人魔是精英：建议组队。",
		["The {item:6995}"] = "{item:6995}",
		["The {item:7083}"] = "{item:7083}",
		["from the {item:6776}"] = "来自{item:6776}",
		["{area:1581} is a group of five under {area:20}; the instance portal is inside the {area:20} mine. The Goblin Woodcarvers in the Mast Room, with Sneed, drop the lumber."] = "{area:1581}是{area:20}地下的五人副本；副本传送门在{area:20}的矿洞里。桅杆室里与斯尼德一起的地精木匠掉落木材。",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}，在{area:20}的矿洞里",
		["{area:236} is a level 20-30 dungeon in southern {zone:1421}. The hammer lies on a box inside the stables, at the far end of the courtyard before the ramp up."] = "{area:236}是{zone:1421}南部的20-30级地下城。铁锤放在马厩里的一个箱子上，在庭院尽头、上坡之前。",
		["{npc:3649} is in {area:442}."] = "{npc:3649}在{area:442}。",
		["{npc:6171} stands in the Cathedral of Light. Right-click the {item:6776} to start its quest."] = "{npc:6171}站在光明大教堂里。右键点击{item:6776}开始它的任务。",
		["{npc:6181} stands outside the gates of {zone:1455}. He gives you {item:6996}, which list the four parts."] = "{npc:6181}站在{zone:1455}大门外。他会给你{item:6996}，上面列出了四个部件。",
		["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}. Waves of Defias attack it during her quest: keep her alive, and heal her if she needs it."] = "{npc:6182}的农舍位于{zone:1436}西南海岸。她的任务期间迪菲亚兄弟会会一波波来袭：保护她存活，需要时为她治疗。",
		["{npc:6241} is in {area:144}."] = "{npc:6241}在{area:144}。",
		["{npc:6241} turns the ore into {item:6993}."] = "{npc:6241}会把矿石变成{item:6993}。",
		["{object:91138}, inside"] = "{object:91138}，在副本内",
		["{object:92420} crate"] = "{object:92420}箱子",
} end)()
t.guides["forever/class/priest/benediction"] = (function() return {
		["Equip {item:18646} to see {npc:14494}, a ghost on the mountainside in the north-west of the {zone:1423}. Come with full mana, Major Mana Potions and {item:8956}: if you fail, the event takes about two hours to return."] = "装备{item:18646}后才能看到{npc:14494}，一个位于{zone:1423}西北山坡上的鬼魂。带满法力、{item:13444}和{item:8956}前来：如果失败，事件大约要两小时才会重新出现。",
		["Save 50 peasants before 15 die. Kill the skeletons that attack them, cure their diseases (the purple ones first) and heal the wounded with {spell:139}. Friends may buff you beforehand but must stay out of the fight, or a demon appears and kills everyone."] = "在15个农民死亡之前救下50个。杀掉攻击他们的骷髅，治愈他们的疾病（先治紫色的），并用{spell:139}治疗伤者。朋友可以事先给你加增益，但必须远离战斗，否则会出现一个恶魔杀死所有人。",
		["With both Eyes in your bags: {item:18608}"] = "两只眼睛都在背包里时：{item:18608}",
		["You need {item:18646} first: it comes from the {object:179703} after {npc:12018} in {area:2717}. {item:18665} drops from elite demons ({npc:12397}, a world boss, always; Doomguard Commanders and Manahounds rarely); it binds when equipped, so buying one works too."] = "你需要先拿到{item:18646}：它来自{area:2717}中{npc:12018}之后的{object:179703}。{item:18665}由精英恶魔掉落（世界首领{npc:12397}必掉；{npc:12396}和法力犬偶尔掉落）；它是装备后绑定，所以也可以买一个。",
		["{item:18608} and Anathema"] = "{item:18608}与咒逐",
		["{npc:14494}'s splinter and the two Eyes make {item:18608}, the epic priest staff that turns into Anathema."] = "{npc:14494}的碎片和两只眼睛可以合成{item:18608}，这把史诗牧师法杖可以变成咒逐。",
} end)()
t.guides["forever/class/priest/blood-of-morphaz"] = (function() return {
		["Any undead can drop it. The {npc:7864} in the {area:1221}, below {npc:8405}'s cliffs, are the nearest; Highborne Apparitions and Lichlings haunt the ruins near {area:3137}."] = "任何亡灵都可能掉落。{npc:8405}的悬崖下方、{area:1221}中的{npc:7864}最近；{npc:6116}和上层精灵鬼巫出没于{area:3137}附近的废墟。",
		["At 50 {npc:5489} in {zone:1453}'s Cathedral of Light or {npc:11406} in {zone:1455}'s {object:32386} offers it."] = "50级时，{zone:1453}光明大教堂的{npc:5489}或{zone:1455}{object:32386}的{npc:11406}提供此任务。",
