t.guides["forever/exploration/zephras-isle"] = (function() return {
		["Exploration: {zone:2521}"] = "探索：{zone:2521}",
		["Exploring the entire world map on one character is a Forever Legacy Challenge (1 account-wide Legacy Point)."] = "在一个角色上探索整张世界地图是一项 Forever 传承挑战（1点账号通用传承点数）。",
		["Skyborne start here. Everyone else takes a skyboat, about every five minutes; either faction may take either one."] = "天裔从这里开始。其他人乘坐天空飞船，约每五分钟一班；两个阵营都可以乘坐任意一艘。",
		["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "天空飞船从{zone:1456}北边、{area:17045}南边的悬崖出发（另一艘从{area:279}起飞）。",
		["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "天空飞船从{zone:1416}{area:279}的北侧出发（另一艘从{zone:1456}北边起飞）。",
		["any one of these names counts"] = "以下任意一个名称都算",
		["{zone:2521} is the Skyborne starting island, a world of its own in {area:17221}; anyone may visit, and its map counts towards exploring the world. 20 areas to discover here, levels 3-12."] = "{zone:2521}是天裔的起始岛屿，位于{area:17221}的独立世界；任何人都可前往，其地图计入世界探索。这里有20个区域待发现，3-12级。",
} end)()
t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Back down the beach, past the pirate camp: the crate of boots and the fragile crate with the lens sit at its south end."] = "沿海滩往回走，经过海盗营地：一箱靴子和装着镜片的易碎品箱在营地南端。",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "回到钢鬃营地。钢鬃地卜师和钢鬃防御者占据营地东半部；{npc:3438}在他们中间走动。",
		["Back west along the road."] = "沿道路向西返回。",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}; they drop the {item:6652}. The {item:5026} comes from the Razormane on your next visit to their camp."] = "火刃祭司占据{zone:1411}北部的{area:1898}；它们掉落{item:6652}。{item:5026}在你下次去钢鬃营地时从钢鬃野猪人身上获得。",
		["East to the {area:1703}; {npc:9316} stands at the camp just south of it."] = "向东前往{area:1703}；{npc:9316}站在其南边不远的营地。",
		["East to {area:392}, on the coast."] = "向东前往海岸上的{area:392}。",
		["Follow the road east to the outpost above the {area:814}."] = "沿道路向东前往{area:814}上方的哨站。",
		["Follow the road south-east to {area:392} on the coast."] = "沿道路向东南前往海岸上的{area:392}。",
		["Keep it: {quest:3923} stands outside {zone:1454}; a later guide hands it in"] = "留着：{quest:3923}站在{zone:1454}外；之后的指南会交还",
		["Kolkar Wranglers and Stormers hold the camps south of {npc:3389}."] = "科卡尔牧民和科卡尔召雷师占据{npc:3389}南边的营地。",
		["Kolkar camps"] = "科卡尔营地",
		["Oasis Snapjaws crawl around {area:387}, south-west of the {area:380}, and around the {area:388}."] = "{npc:3461}在{area:380}西南方的{area:387}周围和{area:388}周围爬行。",
		["Plainstriders and Sunscale raptors roam the plains all around the {area:380}, thickest to the north."] = "平原陆行鸟和赤鳞迅猛龙在{area:380}四周的平原上游荡，北边最多。",
		["Plainstriders and raptors"] = "陆行鸟和迅猛龙",
		["Raptor nests"] = "迅猛龙巢穴",
		["Razormane camp"] = "钢鬃营地",
		["South to {npc:3389}'s watch post on the Kolkar border."] = "向南前往{npc:3389}在科卡尔边界的哨站。",
		["South-east of the {area:380}. Test the seeds at the bubbling fissure on the oasis' east bank."] = "在{area:380}东南方。在绿洲东岸冒泡的裂缝处测试种子。",
		["Southsea beach"] = "南海海滩",
		["The Savannah Prowlers hunt the plains between town and the Razormane camp to the east. In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end."] = "草原徘徊者在镇子和东边钢鬃营地之间的平原上狩猎。营地里，钢鬃寻水者和钢鬃织棘者占据西半部，钢鬃猎手在中部；补给箱在营地东端。",
		["The Witchwing Slayers hold the western {area:383}; they wear the rings."] = "巫翼杀戮者占据{area:383}西部；戒指在它们身上。",
		["The pirates camp on the beach south of {area:392}. The piles of complicated parts lie in the sand among them."] = "海盗在{area:392}南边的海滩上扎营。一堆错综复杂的零件散落在他们之间的沙子里。",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers."] = "水池就在{npc:3389}北边。走进水里即可探索；给赫布瑞姆的丰满的蘑菇长在水池周围。杀死途中的每个科卡尔半人马获取护腕。",
		["The three nests sit together in the {area:1697} south-west of the oasis; Sunscale Scytheclaws guard them."] = "三个巢穴一起位于绿洲西南方的{area:1697}；赤鳞镰爪龙守卫着它们。",
		["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}, east of {npc:9316}."] = "装有高强度齿轮的工具桶散落在{npc:9316}东边{area:382}中的风险投资公司钻探点周围。",
		["The {object:4141} stands at the Venture Co. research site west of the {area:382}. Close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471} beside it."] = "{object:4141}位于{area:382}西边的风险投资公司研究站。关闭钻机周围的三个阀门，再次使用控制台，然后从旁边的{npc:3471}身上拿到{item:5089}。",
		["Thunder Lizards and Lightning Hides graze just across the bridge below {area:379}."] = "雷霆蜥蜴和闪电蜥蜴就在{area:379}下方桥对面吃草。",
		["Thunder lizards across the river"] = "河对岸的雷霆蜥蜴",
		["Walk back south to the {area:380}. The next guide starts here and takes you to {zone:1454} and the zeppelin to {zone:1420}."] = "向南走回{area:380}。下一份指南从这里开始，带你前往{zone:1454}并乘飞艇前往{zone:1420}。",
		["Walk back west along the road to the {area:380}."] = "沿道路向西走回{area:380}。",
		["West to the {area:383}. The Witchwing harpies nest all over them; any of them can drop a talon. {quest:819} lies in their hills."] = "向西前往{area:383}。巫翼鹰身人在那里到处筑巢；任何一只都可能掉落爪子。{quest:819}就在它们的山丘中。",
		["Zhevra"] = "斑马",
		["Zhevra Runners graze north and east of town."] = "快步斑马在镇子北边和东边吃草。",
		["{area:1898} cultists"] = "{area:1898}的祭司",
		["{area:380} is your base for this guide. Everyone you need stands within a few steps of the inn."] = "{area:380}是本指南的大本营。你要找的人都在旅店几步之内。",
		["{npc:3442} in {area:392}: later, on the way"] = "{area:392}的{npc:3442}：稍后，顺路",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}：控制台在{area:382}，稍后",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}：鹰身人稍后再打，在{area:383}",
		["{npc:3615}, the wind rider master"] = "{npc:3615}，双足飞龙管理员",
		["{npc:5878} camps beside the road from the {area:380} to {area:392}. The {object:58369} sits in the south of the Razormane camp just north of him."] = "{npc:5878}在从{area:380}到{area:392}的路旁扎营。{object:58369}在他北边不远的钢鬃营地南部。",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900}用焦油和材料袋制作{item:6636}。在他旁边的火盆处使用它，显现出{npc:5893}，杀死它获得{item:6655}，然后把余烬放进火盆。",
		["{npc:5900} waits on the riverbank south of {area:379}, across the bridge."] = "{npc:5900}在{area:379}南边、桥对面的河岸上等候。",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907}站在钢鬃营地北边的山脊上。",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}：{npc:2523}、你的{item:5176}和{item:263412}",
		["{quest:1492}, on the dock"] = "{quest:1492}，在码头上",
		["{quest:3301}: the {area:228} in {zone:1421}, next guide"] = "{quest:3301}：{zone:1421}的{area:228}，下一份指南",
		["{quest:881}, a white lion, prowls the plains north of the Razormane camp."] = "{quest:881}是一头白狮，在钢鬃营地北边的平原上徘徊。",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["At the {area:2362}"] = "在{area:2362}",
		["Cast {spell:18960}; {npc:11802} is in {area:2361}. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "施放{spell:18960}；{npc:11802}在{area:2361}。神殿灵珠躺在{area:656}的湖底，几分钟内就会消失：拿到一个后直接游到西北岸的{area:2362}，在那里使用它并与{npc:11799}交谈。",
		["Fly to {area:1638}: {npc:3033} trains you on {area:1639}. Skyborne: fly back to {zone:1454} for the zeppelin afterwards."] = "飞往{area:1638}：{npc:3033}在{area:1639}训练你。天裔：之后飞回{zone:1454}乘坐飞艇。",
		["Follow the lake shore south-east and swim out to {area:172}. Rot Hide gnolls cover the island; every type drops ichor. Stay out of {area:235} on its north side unless you go for the optional niche: the gnolls there are level 18-22."] = "沿湖岸向东南走，游到{area:172}。岛上到处是腐皮豺狼人；每种都会掉落脓液。除非你要做可选的额外内容，否则别进入岛北侧的{area:235}：那里的豺狼人是18-22级。",
		["Follow the lake shore south-east toward {area:172}: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "沿湖岸向东南朝{area:172}走：沿途的邪鳍切割者和邪鳍潮行者会掉落鱼人的眼球。",
		["Follow the road north out of Silverpine into {zone:1420} and east to the zeppelin towers outside the {area:153}. Take the zeppelin to {zone:1454}."] = "沿道路向北离开银松森林进入{zone:1420}，再向东前往{area:153}外的飞艇塔。乘坐前往{zone:1454}的飞艇。",
		["Follow the road north out of Silverpine into {zone:1420} and on to {area:159}: {npc:246152} trains Paladins there. The zeppelin towers are a short walk south down the road."] = "沿道路向北离开银松森林进入{zone:1420}，继续前往{area:159}：{npc:246152}在那里训练圣骑士。飞艇塔沿道路向南步行不远即到。",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "沿道路向东北前往{area:238}的尤瑞克家。",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "沿道路向南。{object:1627}就在路边，焚木村北边。",
		["From the {area:380}, follow the road north-east to {area:1637} and walk in by the main gate. {npc:3310}, the wind rider master, stands on the tower in the {object:172982}."] = "从{area:380}沿道路向东北前往{area:1637}，从正门进城。双足飞龙管理员{npc:3310}站在{object:172982}的塔上。",
		["Hearth to the {area:228}"] = "用炉石回到{area:228}",
		["Into Silverpine"] = "进入银松森林",
		["Keep it: Thork at the {area:380}"] = "留着它：交给{area:380}的索克",
		["Keep it: {npc:2216} in {area:272}, a later guide"] = "留着它：交给{area:272}的{npc:2216}，在之后的指南中",
		["Mottled Worgs"] = "杂斑座狼",
		["Mottled Worgs prowl the hills around the house."] = "杂斑座狼在房子周围的山丘上游荡。",
		["North again to the Yoricks' house."] = "再次向北前往尤瑞克家。",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "在{area:228}北边。{npc:1983}在{area:240}出没：杀死它，然后穿过田野。",
		["Road to Silverpine"] = "通往银松森林的道路",
		["South-east down the road to {area:233}. Protectors guard the outskirts and Mages the town; both drop pendants. Wizards and Watchers patrol the roads around it. Stay out of the middle, where {npc:2120} stands."] = "沿道路向东南前往{area:233}。达拉然保卫者守卫外围，达拉然法师守在镇里；两者都会掉落坠饰。达拉然巫师和达拉然卫士在周围的道路上巡逻。别进入镇中心，{npc:2120}就站在那里。",
		["South-west of Ambermill, the Ravenclaw Drudgers and Guardians haunt the ruins of {quest:516} in the south-east of the forest."] = "安伯米尔西南方，森林东南部的{quest:516}废墟中出没着鸦爪苦工和鸦爪守护者。",
		["Speak with {npc:10540}, in Grommash Hold"] = "与格罗玛什要塞里的{npc:10540}交谈",
		["Speak with {npc:3230}, in Grommash Hold"] = "与格罗玛什要塞里的{npc:3230}交谈",
		["Swim back and follow the road west to the {area:228}."] = "游回去，沿道路向西前往{area:228}。",
		["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "沿道路向北朝{zone:1420}走：{area:238}的尤瑞克家就在路上。{quest:425}潜伏在房子西边不远处。",
		["The Vile Fin Lakestalkers and Oracles sit on the lake shore south of the {area:237}, east of the {area:228}."] = "邪鳍巡湖者和邪鳍智者在{area:237}南边、{area:228}东边的湖岸上。",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "香蒲和矛草长在暗巷区东边{object:172958}的水边。",
		["The zeppelin lands at the towers outside the {area:153}. Walk west along the road past the ruins and south into {zone:1421}; follow the road to the {area:228}."] = "飞艇降落在{area:153}外的塔上。沿道路向西经过废墟，再向南进入{zone:1421}；沿道路前往{area:228}。",
		["The zeppelin towers stand just outside {zone:1454}'s main gate. Take the zeppelin to {zone:1420} (the other one goes to {object:3202})."] = "飞艇塔就在{zone:1454}正门外。乘坐前往{zone:1420}的飞艇（另一艘去{object:3202}）。",
		["The {object:1593} lies at the ferry landing on the lake shore east of the {area:228}."] = "{object:1593}停在{area:228}东边湖岸的渡口。",
		["The {object:172960} is the canyon under the {object:172982}; {npc:3216} stands at its far end."] = "{object:172960}是{object:172982}下方的峡谷；{npc:3216}站在它的尽头。",
		["The {object:177790} lies on the coast west of the {area:240}. It holds the {item:15882} for {quest:30}."] = "{object:177790}位于{area:240}西边的海岸上。里面装着{quest:30}所需的{item:15882}。",
		["To {area:1637}"] = "前往{area:1637}",
		["Vile Fin murlocs"] = "邪鳍鱼人",
		["Walk in through the main gate. {npc:268701} stands in the {object:172982}; {object:173016} is a few steps north."] = "从正门进城。{npc:268701}站在{object:172982}；{object:173016}就在北边几步远。",
		["Zeppelin to {zone:1420}"] = "乘飞艇前往{zone:1420}",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["Zeppelin tower"] = "飞艇塔",
		["grind on {npc:1909} at {area:1338}, {zone:1421}"] = "在{zone:1421}的{area:1338}刷{npc:1909}",
		["{area:1338} shore"] = "{area:1338}湖岸",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228}是森林中央的被遗忘者墓穴小镇。你要找的人都站在墓穴入口周围；蝙蝠管理员{npc:2226}就在入口东边。",
		["{area:233} comes later, on the southern loop"] = "{area:233}稍后在南线环路中前往",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}，来自湖中的{object:177785}",
		["{item:3317}: a rare drop from the gnolls"] = "{item:3317}：豺狼人的稀有掉落",
		["{npc:11798} in {area:2361} flies druids there; then fly on to {zone:1454} for the zeppelin"] = "{area:2361}的{npc:11798}载德鲁伊飞往那里；然后继续飞往{zone:1454}乘坐飞艇",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}，在{area:2362}",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}：为了奎恩，最后在北边的路上",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978}在房子东北边等候。护送他回到{npc:1950}那里；途中会有座狼袭击。",
		["{npc:2121}: {quest:516}, on the south loop"] = "{npc:2121}：{quest:516}，在南线环路中完成",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152}在{area:159}训练圣骑士，从飞艇塔沿道路向北步行不远即到。之后沿同一条路回来，前往银松森林。",
		["{npc:268684} and {npc:268682} sit behind Grommash Hold in the {object:172957}; the Smooth Boulders lie around them. Train while you are in the city (Druids and Paladins have no trainer here). The next guide starts at {npc:3310}, the wind rider master in the {object:172982}."] = "{npc:268684}和{npc:268682}坐在{object:172957}的格罗玛什要塞后面；光滑的巨石就在他们周围。趁在城里时训练（德鲁伊和圣骑士在这里没有训练师）。下一个指南从{object:172982}的双足飞龙管理员{npc:3310}开始。",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348}和{npc:3347}在暗巷区经营炼金商店；{npc:11046}就在隔壁。",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}，在格罗玛什要塞里",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}：{quest:93739}，游览部落各位领袖",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018}在城西侧的{object:172961}。",
		["{object:112888}, inside the keep"] = "{object:112888}，在城堡里",
		["{object:1599}, just east of the keep"] = "{object:1599}，就在城堡东边",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}：{area:384}，见下一个指南",
		["{zone:1454} class quests"] = "{zone:1454}职业任务",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "协助{npc:261366}：当{npc:261367}和{area:21}水兵走上山脊时，待在他身边",
		["Back to the {area:380}"] = "返回{area:380}",
		["Bael'dun fortress"] = "巴尔丹城堡",
		["Bristleback camps"] = "刺背野猪人营地",
		["Cast {spell:18960}. Tauren: join the two pendant halves at the {area:2362}, on the north-west shore of the lake, before you see {npc:11802} in {area:2361}."] = "施放{spell:18960}。牛头人：在{area:2361}见{npc:11802}之前，先在湖西北岸的{area:2362}把两半坠饰合在一起。",
		["Dogran is chained up in the quilboar camp west of the road."] = "多格兰被锁在道路西边的野猪人营地里。",
		["Doras, the wind rider master, stands on the tower in the {object:172982}."] = "双足飞龙管理员多拉斯站在{object:172982}的塔上。",
		["Down the {area:458} to {area:378} again."] = "再次沿{area:458}向南前往{area:378}。",
		["East across the plains toward the coast: the stolen silver lies in a raptor nest north-west of {area:385}."] = "向东穿过平原前往海岸：被偷的银子在{area:385}西北的一个迅猛龙巢穴里。",
		["East to the {area:382}. {npc:3439} stands inside the Venture Co. camp; {npc:3445} carries the key."] = "向东前往{area:382}。{npc:3439}停在风险投资公司营地里；{npc:3445}带着钥匙。",
		["Fill the {item:7766} at the quilboar watering hole"] = "在野猪人的水坑装满{item:7766}",
		["Fizzule runs the Venture Co. camp at the east end of the {area:382}. He attacks strangers: target him and /salute before he does."] = "费苏勒管理着{area:382}东端的风险投资公司营地。他会攻击陌生人：在他动手前选中他并 /salute。",
		["Fly back to the {area:380}. The next guide starts here and takes the road north to the {area:1703} and {zone:1440}."] = "飞回{area:380}。下一个指南从这里开始，沿道路向北前往{area:1703}和{zone:1440}。",
		["Fly to {area:1637} to train your level 20 ranks. {npc:3354} is in the {object:172958}, {npc:5892} in the {object:172957}."] = "飞往{area:1637}训练20级技能。{npc:3354}在{object:172958}，{npc:5892}在{object:172957}。",
		["Fly to {area:1637} to train."] = "飞往{area:1637}训练。",
		["Fly to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}."] = "飞往{area:1638}训练20级技能：{npc:3033}在{area:1639}。",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "飞往{area:1638}训练：{npc:3033}在{area:1639}。",
		["Fly to {area:392}"] = "飞往{area:392}",
		["Follow the {area:458} south to {area:378}."] = "沿{area:458}向南前往{area:378}。",
		["He gives you the {item:15826}"] = "他会给你{item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "他接下来会提供{quest:1838}（1838，30级）：它需要{area:1717}，还会让你跑遍卡利姆多和东部王国。战士职业指南{quest:1838}涵盖了它。",
		["Hearth to the {area:380}"] = "用炉石回到{area:380}",
		["Keep it: the {object:107045} is beside {area:272}"] = "留着它：{object:107045}在{area:272}旁边",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "留着它：交给{zone:1440}的{npc:12696}，见下一个指南",
		["Keep it: {npc:5875} in {zone:1454}, at the end of this guide"] = "留着它：交给{zone:1454}的{npc:5875}，在本指南结尾",
		["Level 20"] = "20级",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "向北前往{area:383}。{npc:3682}在山下扎营；他身后山脊上的隐士{npc:261366}要等{npc:3682}派你上去后才会给你任务。",
		["On the way back down the {area:458} to {area:378}: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry {item:277277}. Hand them to {npc:3432} on your last {area:380} stop."] = "沿{area:458}返回{area:378}的路上：营地北边道路两侧刺背野猪人营地中的钢鬃掠夺者携带{item:277277}。最后一次在{area:380}停留时交给{npc:3432}。",
		["Ride north from the {area:380} to {area:384} and fill the {item:15842} at the {object:19464}, then back to {npc:3448} in the {area:380}. No {skill:182}? {npc:3490} beside him sells {item:2449}, three at a time until he restocks."] = "从{area:380}向北骑到{area:384}，在{object:19464}装满{item:15842}，然后回到{area:380}找{npc:3448}。没有{skill:182}？他旁边的{npc:3490}出售{item:2449}，每次三个，之后要等他补货。",
		["Savannah Patriarchs roam the plains east of the hills, and the Sprung Traps lie among them. {quest:876} leads the Witchwing harpies in the hills to the west."] = "草原狮王在山丘东边的平原上游荡，爆炸陷阱就散落在它们中间。{quest:876}率领着西边山丘里的巫翼鹰身人。",
		["South of Camp Taurajo the Silithid Mounds dot the {area:390}; the eggs lie in them, and Silithid Swarmers come out to defend them. Silithid Harvesters are rare: if you see one, kill it for its head."] = "陶拉祖营地南边，{object:3685}遍布{area:390}；蛋就在土丘里，{npc:3252}会出来保护它们。{npc:3253}很稀有：如果看到，杀死它取下它的头。",
		["South of Gann, the Bael'dun dwarves dig at {area:359}. Excavators and Foremen work the pit; {npc:3392} (26) carries the journal: pull him alone."] = "在加恩南边，巴尔丹矮人在{area:359}挖掘。巴尔丹挖掘者和巴尔丹工头在坑里干活；{npc:3392}（26级）带着日志：单独把他引出来。",
		["Stay stealthed: {npc:7287} carries the key to the tower; Gallywix and his lockbox are at the top. Gallywix is elite: grouping up is advised."] = "保持潜行：{npc:7287}带着塔的钥匙；加里维克斯和他的保险箱在塔顶。加里维克斯是精英：建议组队。",
		["Sunscale Scytheclaws hunt the plains south of the {area:380}, around the {area:1697}; they drop the horns. Hand them in on your next pass through {area:392}."] = "赤鳞镰爪龙在{area:380}南边的平原上、{area:1697}一带捕猎；它们掉落角。下次路过{area:392}时交还。",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "牛头人：{npc:11957}在桥上方的南边山丘上等候。天裔：{npc:272054}站在双桥南边。然后前往湖东边的兽穴：解除变形，点击入口处的雕像获得五分钟潜行，避开里面的灵魂，每种遗物各拿一件；{item:280680}在白色猎豹雕像脚下。",
		["The Bael'dun Soldiers, Riflemen and Officers guard the fortress on the east side of the dig; all three items drop from them."] = "巴尔丹士兵、巴尔丹火枪手和巴尔丹军官守卫着挖掘场东侧的城堡；三样物品都由他们掉落。",
		["The Bristleback quilboar camps spread over the plains north of {area:378}, either side of the {area:458}. Every Bristleback drops a tusk; {npc:3432}'s wife lies at the north edge. Keep one {item:5075}. {quest:883}, a grey kodo, sometimes wanders here: his hoof starts a quest."] = "刺背野猪人的营地遍布{area:378}北边的平原，位于{area:458}两侧。每个刺背野猪人都会掉落獠牙；{npc:3432}的妻子躺在北缘。留一个{item:5075}。{quest:883}是一头灰色科多兽，有时会在这里游荡：它的蹄子可以开始一个任务。",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "地区东北角矿洞的风险投资公司监督和风险投资公司执行者掉落{item:5097}。",
		["The antennae vanish fifteen minutes after they drop, so gather them now, on the way back north: kill the Silithid Swarmers and Creepers at the {area:390}' mounds until you have five, then hearth to {area:378} straight away."] = "触角掉落十五分钟后就会消失，所以趁现在北返时收集：在{area:390}的土丘旁杀异种群居蝎和异种爬行者，直到拿到五个，然后立刻用炉石回到{area:378}。",
		["The dwarves' flying machine sits on its platform inside the dig site."] = "矮人的飞行器停在挖掘场内的平台上。",
		["The flying machine"] = "飞行器",
		["The level-20 class quests in {zone:1454} ({npc:3354}, {npc:5892}, the Warlock and Rogue trainers) are only offered from level 20, so finish the level here before you fly. The Thunderhawk Hatchlings (18) on the plains south-west of the {area:380} and the Kolkar (14-15) at the {area:388} are the nearest mobs worth killing; you need well under a level."] = "{zone:1454}的20级职业任务（{npc:3354}、{npc:5892}、术士和潜行者训练师）20级才提供，所以飞走前先在这里升到20级。{area:380}西南平原上的雷鹰雏鸟（18级）和{area:388}的科卡尔半人马（14-15级）是最近的值得击杀的怪物；你需要的经验远不到一级。",
		["The pirates camp on the beach south of {area:392}; {npc:3467} stands at its southern end."] = "海盗在{area:392}南边的海滩上扎营；{npc:3467}站在营地南端。",
		["The {area:2363}"] = "{area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960}是{object:172982}下方的峡谷。",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792}位于{area:382}北缘、风险投资公司的塔旁。里面装着{quest:30}所需的{item:15883}。",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "雷鹰破云者在营地南边同一片平原上空盘旋。",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "电角蜥蜴在{area:378}正南的平原上吃草。{quest:884}是一只蓝色的雷霆蜥蜴，在它们中间游荡：它的尾刺可以开始一个任务。",
		["Twitching Antennae"] = "颤抖的触角",
		["Twitching Antennae from the silithid"] = "从异种蝎身上获取颤抖的触角",
		["Venture Co. tower"] = "风险投资公司的塔",
		["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {npc:3238} lizards and Hecklefang Stalkers roam the plain between {npc:3341} and the ridge. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest."] = "在{npc:3341}西边，钢鬃野猪人占据着{area:1701}。{npc:3436}在东侧，{npc:3434}在南边，{npc:3435}在西端。洛克（25级）和钢鬃战士（24-25级）比你高几级；稀有精英{npc:5859}有时会在山脊上走动：别惹他。钢鬃探路者和钢鬃捕猎者掉落钢鬃背刺匕首，钢鬃先知掉落烧焦的钢鬃魔杖，钢鬃战士掉落钢鬃大盾。{npc:3238}和乱齿捕猎者在加恩与山脊之间的平原上游荡。{quest:885}是一条稀有的红色风蛇，在山脊上空飞行：它的羽毛可以开始一个任务。",
		["Wizzlecrank drives his shredder out of the camp: stay with him and kill whatever attacks him. {npc:3442} takes it in {area:392}."] = "维兹克兰克驾驶伐木机离开营地：跟着他，杀死所有攻击他的敌人。在{area:392}向{npc:3442}交还。",
		["grind on Thunderhawk Hatchlings south-west of the {area:380}"] = "在{area:380}西南刷雷鹰雏鸟",
		["{area:385}, on the coast further south. The Theramore Marines and Preservers (15-16) drop the medals; {npc:3393} (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now."] = "{area:385}在更南边的海岸上。塞拉摩水兵和塞拉摩医师（15-16级）掉落勋章；{npc:3393}（20级）和两名炮手（19级）在城堡里和城墙上，所以要塞要等到现在才来。",
		["{item:15852}: Lost Barrens Kodos on the plains around the Kolkar camp"] = "{item:15852}：科卡尔营地周围平原上的落单的草原科多兽",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}：在{area:2362}使用其中一半",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "向{npc:3490}购买{item:2449}；草药师可以在平原上采集",
		["{item:2449}: herbalists pick it here"] = "{item:2449}：草药师可在这里采集",
		["{npc:11798} in {area:2361} flies druids there"] = "{area:2361}的{npc:11798}载德鲁伊飞往那里",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}：{npc:3033}的问候",
		["{npc:12296}: use the {item:15826} on them; they roam the plains all around the {area:380}"] = "{npc:12296}：对它们使用{item:15826}；它们在{area:380}周围的平原上游荡",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}，在{npc:3341}正东的树上",
		["{npc:209797} swims in the harbour just off {area:392}'s docks. {npc:209797} is elite: grouping up is advised."] = "{npc:209797}在{area:392}码头外的港湾里游动。{npc:209797}是精英：建议组队。",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{area:272}的{npc:2391}教授毒药：留着它",
		["{npc:246344} teaches Paladins in {area:1638}. You have no flight path there yet: fly to {area:378}, ride west through {zone:1412} and up a lift, and take the flight path from {npc:2995} on the central rise."] = "{npc:246344}在{area:1638}训练圣骑士。你还没有那里的飞行路线：飞往{area:378}，向西骑马穿过{zone:1412}，乘升降梯上去，在中央高台的{npc:2995}处开通飞行路线。",
		["{npc:262119} and his marines hold the wrecked caravan south of {npc:261366}."] = "{npc:262119}和他的水兵守着{npc:261366}南边被毁的商队。",
		["{npc:3238}, on the plain between {npc:3341} and the ridge"] = "{npc:3238}，在{npc:3341}与山脊之间的平原上",
		["{npc:3341} waits in a small camp further south, on the road toward {area:359}."] = "{npc:3341}在更南边通往{area:359}的道路旁的一个小营地里等候。",
		["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389}站在{area:380}正西的科卡尔哨所。",
		["{npc:3394} stands in the Kolkar camp north-west of {npc:3389}."] = "{npc:3394}站在{npc:3389}西北的科卡尔营地里。",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the {area:380}."] = "{npc:3395}在{area:380}东南的{area:388}，在科卡尔半人马中间走动。",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. Hand his head to {npc:3389} on your last {area:380} stop."] = "{npc:3396}率领着{area:387}西岸的科卡尔半人马，位于{npc:3389}南边。最后一次在{area:380}停留时把他的头颅交给{npc:3389}。",
		["{npc:3401} stands in the {object:172960}. Target him and type /salute to finish {quest:2460}."] = "{npc:3401}站在{object:172960}。选中他并输入 /salute 来完成{quest:2460}。",
		["{npc:3428}: the eggs are in the {area:390}, later"] = "{npc:3428}：蛋在{area:390}，稍后进行",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}，在塔顶",
		["{npc:3429}. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}。留着它：交给{area:1703}的卡德拉克，见下一个指南",
		["{npc:3430}, in the cage"] = "{npc:3430}，在笼子里",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{quest:4921}交还后，{npc:3432}会提供{quest:95774}",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}，在营地北缘",
		["{npc:3442}, beside the wind rider master. Keep it: {quest:1483} is in Stonetalon, later"] = "{npc:3442}，在双足飞龙管理员旁边。留着它：{quest:1483}在石爪山脉，稍后进行",
		["{npc:3453}, on the dock"] = "{npc:3453}，在码头上",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465}被锁在要塞里。和他交谈开始护送，并紧跟着他：出去的路上会有塞拉摩士兵袭击。他会和你一起走回{area:392}。",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197}住在{area:2539}，那是从{npc:3389}处向西的道路尽头、刚进入石爪山脉的巨魔村庄。",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875}站在{object:172960}。在那里的召唤法阵上使用{item:6626}，击败魅魔来束缚她。",
		["{npc:5878} camps beside the road east of the {area:380}."] = "{npc:5878}在{area:380}东边的路旁扎营。",
		["{npc:5899}, just west of {npc:3341}"] = "{npc:5899}，就在{npc:3341}西边",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901}在{area:392}南边的山上等候，就在你北上的路上。",
		["{npc:5909}, a few steps away"] = "{npc:5909}，就在几步之外",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018}站在城西侧的{object:172961}。",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}：{zone:1458}的{npc:4606}，见后面第二个指南",
		["{object:3972} poster"] = "{object:3972}告示",
		["{quest:2458}: {npc:7233}, by the {area:382}"] = "{quest:2458}：{npc:7233}，在{area:382}旁",
		["{quest:882}, a big Sunscale raptor, hunts the plains north of the road from {area:392} to the {area:380}."] = "{quest:882}是一只大型赤鳞迅猛龙，在从{area:392}到{area:380}的道路北边的平原上捕猎。",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "回到向南的道路。在道路向东转入{area:287}的地方，{npc:2214}在{area:285}等候。",
		["Back to {npc:8582}"] = "回到{npc:8582}处",
		["East of Ziz, the Venture Company is clear-cutting {area:461}; one of the Operators carries the blueprints. {npc:4276} mines in the small mine on the east side: stay with him while he mines, Venture Co. thugs come for him."] = "在菲兹克斯东边，风险投资公司正在{area:461}大肆砍伐；其中一个风险投资公司操作员携带图纸。{npc:4276}在东侧的小矿洞里采矿：他采矿时守在他身边，风险投资公司的打手会来找他。",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "哨站北边海滩上的每个怒尾纳迦都会掉落头颅。",
		["Fly to {area:431} and ride south down the road to the {area:1703}."] = "飞往{area:431}，沿道路向南骑到{area:1703}。",
		["Follow the road east along the river, then north-east up into the hills to {area:272}."] = "沿河边道路向东，然后向东北爬进山丘到{area:272}。",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "沿道路向北朝{area:467}前进。巨角鹿沿途吃草；腐蚀兽、夜行虎和灵龙在山峰下方的树林中游荡，塞纳里奥德鲁伊占据那里的树林。",
		["Follow the road west to {area:460}."] = "沿道路向西前往{area:460}。",
		["From the {area:380} follow the road north. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}. Open the {item:16783} he gives you."] = "从{area:380}沿道路向北。{npc:8582}站在道路进入{zone:1440}处{area:1703}的瞭望塔上。打开他给你的{item:16783}。",
		["Gaea Dirt Mounds"] = "盖亚土堆",
		["Gaea Seeds"] = "盖亚之种",
		["If you already know the {area:272} flight path, fly there and skip to {area:272}. Otherwise fly from the {zone:1458} to the {area:228} and ride south down the road past Pyrewood. The Ravenclaw undead haunt the ruins of {area:231} east of the road in the south-east of the forest; a {npc:1973} drops the {item:271343} that leads to the {object:645153}."] = "如果你已经知道{area:272}的飞行路线，就飞过去并跳到{area:272}。否则从{zone:1458}飞往{area:228}，沿道路向南经过焚木村。鸦爪亡灵在森林东南部、道路东边的{area:231}废墟中游荡；{npc:1973}掉落{item:271343}，指引你找到{object:645153}。",
		["Keep north on the road. The {npc:12862} waits at the Warsong lumber camp, south of Splintertree."] = "继续沿道路向北。{npc:12862}在碎木岗哨南边的战歌伐木营地等候。",
		["Naga heads"] = "纳迦头颅",
		["On the ride west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "向西骑行时，{npc:267214}被困在主路南边的一条峡谷里，位于{area:415}东南。黑角鹿和灰谷熊在峡谷周围的林子里游荡。",
		["Ride back down the {area:1076} to {area:2539}."] = "沿{area:1076}骑回{area:2539}。",
		["Ride east to the {area:380} and fly to {zone:1454}. Take the zeppelin from the towers outside {zone:1454} to {zone:1420}; the {area:1497} lies below the {area:153}. The bat handler is in the {object:36078}."] = "向东骑到{area:380}，飞往{zone:1454}。从{zone:1454}外的塔楼乘飞艇前往{zone:1420}；{area:1497}在{area:153}下方。蝙蝠管理员在{object:36078}。",
		["Ride south to the {area:380}, then west along the road out of the {zone:1413} into Stonetalon. The troll village of {area:2539} sits at the entrance of the canyon."] = "向南骑到{area:380}，然后沿道路向西离开{zone:1413}进入石爪山脉。巨魔村庄{area:2539}位于峡谷入口。",
		["Ride west along the main road across {zone:1440}, past {area:415} (Alliance: keep to the road), to the coast. {area:2897} is on the {area:414} in the north-west. Its other quests are for the next visit, at 27."] = "沿主路向西穿过{zone:1440}，经过{area:415}（联盟：别离开道路），到达海岸。{area:2897}位于西北部的{area:414}。它的其他任务留到27级下次来时。",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "烈日石居西南方是烧焦的{area:465}。把{item:16205}种在谷底的土堆里；火元素掉落{item:16312}。血怒鹰身人和血怒伏击者在北侧筑巢，血怒杀戮者和血怒游荡者在南侧。",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "与{object:36126}的{npc:10181}交谈：{quest:93739}",
		["Sputtervalve in {area:392}: the next guide passes there"] = "{area:392}的斯布特瓦夫：下一份指南会经过那里",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "在四分钟内操控{npc:267214}的{npc:271181}离开峡谷到达主路；如果引导中断，再找{npc:267214}一次。",
		["The Gaea Seeds lie in the grass around the southern shore of {area:464}, north of Sun Rock."] = "盖亚之种散落在烈日石居北边{area:464}南岸的草丛中。",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "道路向北攀升，即{area:1076}。{quest:1483}的小屋在道路向东分岔通往{area:461}的地方。",
		["The {npc:12864} patrols the road east of {area:428} toward the {area:430}."] = "{npc:12864}在{area:428}东边朝{area:430}方向的道路上巡逻。",
		["To the {area:1497}"] = "前往{area:1497}",
		["Use the {npc:212753} at the {object:645153} for a willing sacrifice and kill the {npc:212753} that answers. {quest:95883} is elite: grouping up is advised."] = "在{object:645153}使用{npc:212753}作为自愿的祭品，杀死回应的{npc:212753}。{quest:95883}是精英任务：建议组队。",
		["{area:431} is just north up the road."] = "{area:431}就在道路北边不远处。",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}，来自{npc:1973}",
		["{item:271350}, from the Tortured Souls among the ruins"] = "{item:271350}，来自废墟中的被折磨的灵魂",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}，来自任何血怒鹰身人",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}：从血怒鹰身人获取闪光的太阳石",
		["{npc:11860}: Grish is at the {area:1718}, in the next guide"] = "{npc:11860}：瑞什在{area:1718}，下一份指南",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}，在{npc:11862}旁边",
		["{npc:11862}, up on the ledge"] = "{npc:11862}，在上方的岩架上",
		["{npc:12696} stands at {area:428}, the Warsong camp just north-east of Splintertree, beside the hunt board."] = "{npc:12696}站在{area:428}的狩猎告示板旁，那是碎木岗哨东北方不远的战歌营地。",
		["{npc:12696}'s hunt targets (Ursangous, Shadumbra, Sharptalon) are for the next {zone:1440} visit, at 27."] = "{npc:12696}的狩猎目标（乌萨苟斯、萨杜布拉、沙普塔隆）留到27级下次来{zone:1440}时。",
		["{npc:12736} at Zoram'gar, at 27"] = "佐拉姆加的{npc:12736}，27级时",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}：{area:272}的达萨利亚",
		["{npc:271181}, on the road"] = "{npc:271181}，在路上",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "{npc:4198}的下一个任务“奥达努斯”在{zone:1440}的联盟一方。跳过。",
		["{npc:4198}, outside the gate"] = "{npc:4198}，在大门外",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606}站在{object:36070}。",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["Bears, creepers and lions"] = "熊、食苔蛛和山地狮",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings; open both locks."] = "德鲁尔和{npc:2238}被锁在{area:275}庭院的建筑里；把两把锁都打开。",
		["Drull's ball and chain"] = "德鲁尔的镣铐",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "在旅店旁的{object:107045}装满{item:7768}",
		["Follow the road south to the dwarf dig site at {area:359}. {npc:3421} hides at the south edge of the dig; {object:3646} sits at the bottom of the excavation."] = "沿道路向南前往{area:359}的矮人挖掘场。{npc:3421}躲在挖掘场南缘；{object:3646}在挖掘坑底部。",
		["From {area:272} go south-east into the hills on the way to {area:275}. Rogues and Watchmen hold the camps along the way."] = "从{area:272}向东南进入山丘，前往{area:275}。沿途的营地由辛迪加潜行者和辛迪加卫士占据。",
		["From {zone:1454} (zeppelin from the towers outside the {zone:1458}) fly to {area:1638} and train on {area:1639}, then fly on to {area:378}."] = "从{zone:1454}（在{zone:1458}外的塔上乘飞艇）飞往{area:1638}，在{area:1639}训练，然后继续飞往{area:378}。",
		["From {zone:1454} (zeppelin from the towers outside the {zone:1458}) fly to {area:378}."] = "从{zone:1454}（在{zone:1458}外的塔上乘飞艇）飞往{area:378}。",
		["Hearth to {area:378} and fly to {area:392}. {quest:874} camps on the shore north of {area:392}."] = "用炉石回到{area:378}，飞往{area:392}。{quest:874}在{area:392}北边的海岸上扎营。",
		["Keep it: the {area:287} coast, later on the route"] = "留着它：{area:287}海岸，路线后面会去",
		["Masoj hides on the hillside above {area:290}, south of Durnholde, on the way down to the blossoms."] = "Masoj躲在{area:290}上方的山坡上，位于敦霍尔德城堡南边，就在下去采花的路上。",
		["No Gallywix yet? The Class guide Poisons (Horde) runs the chain from Shenthul again, with a group for Gallywix."] = "还没击败加里维克斯？职业指南“毒药（部落）”会从申苏尔处重新带你做这条任务线，并组队击败加里维克斯。",
		["Only if Gallywix fell in the {zone:1413} (Mission: Possible But Not Probable): {npc:2391} stands in {area:272}. Wait beside him while he brews the cure, then take your reward: Poisons."] = "仅当你已在{zone:1413}击败加里维克斯（申苏尔的潜行者任务线）时：{npc:2391}站在{area:272}。在他调制解药时在旁边等候，然后领取奖励：毒药。",
		["Peasants and skulls"] = "农民和头骨",
		["South-west of Bael Modan, {npc:12576} waits at the top of the {area:485}."] = "在巴尔莫丹西南，{npc:12576}在{area:485}顶部等候。",
		["South-west of Durnholde, the {item:3502} grow on the hillsides above the river."] = "在敦霍尔德城堡西南，{item:3502}长在河上方的山坡上。",
		["Syndicate camps"] = "辛迪加营地",
		["Take the zeppelin from the towers outside the {zone:1458} to {zone:1454} and train before you fly on."] = "在{zone:1458}外的塔上乘飞艇前往{zone:1454}，继续飞行前先训练。",
		["The Peasants work the fields south of the farmhouses. Every {area:287} human drops skulls; the Peasants drop them most often."] = "希尔斯布莱德农民在农舍南边的田里干活。每个{area:287}人类都会掉落头骨；希尔斯布莱德农民掉得最多。",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "{area:287}镇东边的农场。{npc:232}在北边农舍旁的田里干活，{npc:2403}在更东南的那片田；到处都是希尔斯布莱德雇农和希尔斯布莱德农夫。{npc:2451}照料农场南边的田地。",
		["The smithy"] = "铁匠铺",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "铁匠铺在{area:287}镇中央。{npc:2404}和他的希尔斯布莱德见习铁匠在熔炉旁干活；{object:1736}堆在旁边。{npc:2449}在它北边的街上走动。",
		["The town hall is on the west side of {area:287}. {npc:2335} (30) and {npc:2448} are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town."] = "市政厅在{area:287}西侧。{npc:2335}（30级）和{npc:2448}在里面，旁边是希尔斯布莱德城镇文档；希尔斯布莱德宣言就贴在它旁边。希尔斯布莱德议员在镇上走动。",
		["The {area:288} lies south of {area:287} town. Miners work the tunnels; {npc:2305} (30) and {npc:2450} (29) are deep inside."] = "{area:288}在{area:287}镇南边。希尔斯布莱德矿工在坑道里干活；{npc:2305}（30级）和{npc:2450}（29级）在深处。",
		["The {object:1763} poster by the inn"] = "旅店旁的{object:1763}告示",
		["The {quest:567} poster: its targets come up along the way"] = "{quest:567}告示：上面的目标会在沿途遇到",
		["Town hall"] = "市政厅",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "在塔伦米尔西边，{npc:2351}、{npc:2350}和{npc:2384}在通往农场的山丘上游荡。食苔蛛很少掉落{item:3477}；你只需要一个。",
		["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272}是本指南的据点：炉石会两次把你带回这里。所有人都站在镇广场周围。",
		["{item:3692}: the Peasants in the fields"] = "{item:3692}：田里的希尔斯布莱德农民",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}，在炼金房",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}，在{zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}：给{npc:270438}的命令，在前往敦霍尔德城堡的路上",
		["{npc:2230}, next to Lydon"] = "{npc:2230}，在林度恩旁边",
		["{npc:2238}'s ball and chain"] = "{npc:2238}的镣铐",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274}是{npc:232}的狗，在{area:286}北边的农舍旁。",
		["{npc:2388}: the last guide binds here, so this usually ticks at once"] = "{npc:2388}：上一份指南在这里绑定炉石，所以这一步通常会立即完成",
		["{npc:2391}: Poisons"] = "{npc:2391}：毒药",
		["{npc:3442}, by the docks in {area:392}"] = "{npc:3442}，在{area:392}的码头旁",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "{npc:5899}的小屋在{area:378}南边野猪人水坑上方的山脊上，就在前往{area:359}的路上。",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}：蓝色水袋在{zone:1440}装满，见下一个指南",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}：{area:272}的红色水袋",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}是一头巨大的鱼龙，在{area:391}外的浅水中游动，位于{npc:3388}东边。",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "向南回到营地，然后上到{zone:1456}，飞往{area:378}。",
		["Back south-west to {area:421}. Befouled Water Elementals drift around its shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "向西南回到{area:421}。污浊的水元素在湖岸周围漂浮；瞭望台在岛上，俯瞰着联盟的前哨站。",
		["Back west to Zoram'gar before heading east for good."] = "向西回到佐拉姆加前哨站，然后再彻底向东出发。",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "沿小路爬上{area:2097}顶部。{npc:10646}被囚禁在{npc:10896}（29级）旁边：先清掉守卫和{npc:10896}，再救出她并在下山路上保护她；途中会有恐怖图腾伏击者袭击你。",
		["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold."] = "在佐拉姆加前哨站东边，蓟皮熊怪占满了村庄和它们巢穴周围的山丘。",
		["Felmusk satyrs"] = "魔草萨特",
		["Fly from {area:392} to {area:2897} on the {zone:1440} coast."] = "从{area:392}飞往{zone:1440}海岸的{area:2897}。",
		["Fly from {zone:1456} to {area:378} and take the road south to the {area:1718} at the bottom of the {zone:1413}."] = "从{zone:1456}飞往{area:378}，沿道路向南前往{zone:1413}南端的{area:1718}。",
		["Fly from {zone:1456} to {area:378}. {npc:5899}'s hut stands on the ridge above the quilboar watering hole south of the camp, on the road to the {area:1718}."] = "从{zone:1456}飞往{area:378}。{npc:5899}的小屋在营地南边野猪人水坑上方的山脊上，就在通往{area:1718}的路上。",
		["Fly to {area:1638} if you know the flight path. If not, fly to {area:378}, ride west into {zone:1412} past {area:222} to {area:1638} and take its flight path from {npc:2995} on the central rise."] = "如果你知道飞行路线，就飞往{area:1638}。否则飞往{area:378}，向西骑马进入{zone:1412}，经过{area:222}前往{area:1638}，在中央高台的{npc:2995}处开通飞行路线。",
		["Follow the canyon east out of the mesas onto the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "沿峡谷向东离开石柱区，来到盐滩。{area:2240}的地精和侏儒是中立的，为两个阵营提供任务。",
		["Follow the canyon west to {area:2237}."] = "沿峡谷向西前往{area:2237}。",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "沿主路向东经过{area:415}（联盟据点：别离开道路）。{npc:12678}是一头巨大的灰熊，在道路南边、{area:421}西边的{area:418}游荡。它的爪子可以开始下一个狩猎任务。",
		["Galak centaurs"] = "加拉克半人马",
		["Gazebo"] = "瞭望台",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "暮升毒液样本，从{npc:264096}获取",
		["Grimtotem camps"] = "恐怖图腾营地",
		["His crate is for Stranglethorn, later on the route"] = "他的箱子要送去荆棘谷，在路线后面",
		["Inside the hold, Troll Chests lie along the tunnels. {npc:12818} is held deep inside: free him and protect him all the way out, then he runs home to {area:428}."] = "巢穴里，巨魔的箱子散落在坑道各处。{npc:12818}被关在深处：救出他并一路护送他出去，之后他会跑回{area:428}的家。",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "继续沿道路向东。{npc:12858}在战歌伐木营地西南等候。他和他的步兵会猛攻{area:2360}：让他们吸引仇恨，跟着{npc:12858}直到{npc:12860}死去。",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "杀死前来袭击{npc:10638}的{npc:10720}",
		["Naga brazier"] = "纳迦火盆",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "在营地北边，蜘蛛占据了{area:17044}的墓地。对{npc:264096}使用{npc:264074}的{item:273015}；那里的蜘蛛掉落{item:273181}。{npc:264082}在北端：她的{item:273658}可以开始{quest:96294}。",
		["North up the road to {area:431} and {area:428} beside it."] = "沿道路向北前往{area:431}和旁边的{area:428}。",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "在碎木岗哨西北，魔草萨特在树林里扎营。每个萨特都可能掉落角。",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "乘升降梯下去，然后沿道路向东穿过峡谷前往{area:484}，那是一座建在石柱顶上的牛头人村庄。它的升降梯在北侧。",
		["Sapphires of Aku'Mai"] = "阿库麦尔蓝宝石",
		["South of Darkcloud, the harpies of {area:487}. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s."] = "在黑云峰南边是{area:487}的鹰身人。{npc:4490}（31级）在它们中间走动：引她之前先清掉她周围的鹰身人。那里的尖啸的鹰身人、尖啸的游荡者和尖啸的唤风者是{npc:4877}要的。",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "与{area:1638}的{npc:3057}交谈：{quest:93739}",
		["Take a lift down from {zone:1456}. The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}."] = "从{zone:1456}乘升降梯下去。大地之环的营地在高崖北边：{npc:264074}、{npc:264072}和{npc:259118}。",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "乘升降梯下去。蛋在峡谷底部的一个巢里，位于三个地点之一：石柱东南（52.3,55.2）、东边（56.4,50.4）或西南（37.6,56.1）。",
		["The Earthen Ring"] = "大地之环",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "污林熊怪占据着{area:421}东边、道路南边的树林。把{item:16972}放在{object:178206}上并守护它：熊怪会来摧毁它。{npc:12918}最后出现；他的图腾会掉进篮子里。",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks between the camps: kill him when you meet him, his note starts a quest for {area:2237}."] = "加拉克半人马的营地遍布乱风岗北边的峡谷；每个营地都有加拉克斥候、加拉克争斗者和加拉克逐风者。一个落单的{npc:10617}在营地之间走动：遇到就杀死他，他的信件可以开始一个{area:2237}的任务。",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "阿库麦尔蓝宝石是通往{area:2797}传送门的坑道墙壁上的蓝色水晶，位于地下、副本之外：从坑里潜下去，从墙下游进洞穴。坑道里的萨特和纳迦是精英：建议组队。水晶刷新很快，不用深入。",
		["The Wanted poster beside {npc:10537}"] = "{npc:10537}旁的通缉告示",
		["The fountain stands in the middle of the {area:418}: use the {item:7767} there."] = "喷泉在{area:418}中央：在那里使用{item:7767}。",
		["The next guide flies on from here to {zone:1454}."] = "下一个指南从这里飞往{zone:1454}。",
		["The salt flats"] = "盐滩",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "去阿库麦尔蓝宝石的路要穿过海滩北端沉没的废墟：沿台阶下到坑里。",
		["Thistlefur Hold"] = "蓟皮熊怪的巢穴",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "在乱风岗西边，恐怖图腾的营地在{area:2097}下方。密信在东南、西南和西北营地的文件箱里。",
		["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}."] = "在白沙岗哨西边，双足飞龙在{area:482}的悬崖上筑巢；蛋就在巢里。{npc:10427}在筑巢地东侧等候：救出他，并在走回{area:2237}的路上保护他。",
		["for {npc:5901}, south of {area:392}: next guide"] = "交给{area:392}南边的{npc:5901}：见下一个指南",
		["{area:2797} ruins"] = "{area:2797}废墟",
		["{area:418} fountain"] = "{area:418}的喷泉",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}，从{npc:264081}获取",
		["{item:273658}, from {npc:264082}"] = "{item:273658}，从{npc:264082}获取",
		["{npc:10079}, at the top of the lift"] = "{npc:10079}，在升降梯顶部",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}，在双足飞龙管理员旁边",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "{npc:10428}的下一个任务（生命圣火）在{zone:1456}结束，不在本路线上。跳过它。",
		["{npc:12676}, a big nightsaber, prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest."] = "{npc:12676}是一只巨大的夜刃豹，在战歌伐木营地东南的树林里潜行。它的爪子可以开始下一个狩猎任务。",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}是一只暗影豹，在魔草萨特营地西边的{area:426}周围的树林里潜行。它的头颅可以开始下一个狩猎任务。",
		["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead."] = "{npc:12717}沿着海滩向北走到一个纳迦火盆旁。熄灭火盆，然后在纳迦一波波来袭时保护他，直到鞭笞者沃尔沙死去。",
		["{npc:12717}: starts his escort at once"] = "{npc:12717}：立即开始护送",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}：仅当你带着手册书页时",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736}接下来会提供一个{area:2797}任务；除非你有队伍，否则别接。",
		["{npc:12759}, a corrupted water elemental, drifts in {area:421}. Her {item:16408} starts a quest for Splintertree."] = "{npc:12759}是一个被腐化的水元素，在{area:421}里漂浮。它掉落的{item:16408}可以开始一个碎木岗哨的任务。",
		["{npc:12867} stands at the lumber camp. The night elf Outrunners stalk the woods south-east of it; they stealth, so watch for them."] = "{npc:12867}站在伐木营地。暗夜精灵灰谷先驱者在营地东南的树林里潜伏；他们会潜行，所以留意他们。",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}是Forever新增的NPC，站在{area:421}西岸，有三个简短的屠龙者任务。",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986}站在加拉克营地东边的一座石柱顶上。做{quest:1149}时，从他旁边的木板尽头走下去：你会安全落地。",
		["{npc:4454}: his letter goes to Martek in the {zone:1418}, around level 38"] = "{npc:4454}：他的信要交给{zone:1418}的马特克，大约38级时",
		["{npc:4499}, a hard-hitting rock elemental, walks the cliffs of {area:482}. {npc:4499} is elite: grouping up is advised."] = "{npc:4499}是一个攻击力很高的石元素，在{area:482}的悬崖上走动。{npc:4499}是精英：建议组队。",
		["{npc:4877}, the trade supplies vendor: the Screeching harpies of {area:487}"] = "{npc:4877}，商业用品商人：{area:487}的尖啸的鹰身人",
		["{object:176344}, north-west camp"] = "{object:176344}，西北营地",
		["{object:176344}, south-east camp"] = "{object:176344}，东南营地",
		["{object:176344}, south-west camp"] = "{object:176344}，西南营地",
		["{object:19868} lies all over the flats north of the raceway. Scorpid Reavers and Sparkleshell Tortoises roam the north half, Salt Flats Scavengers circle overhead, and Saltstone Basilisks graze west of the track. The Crystalhides roam the middle of the flats and the Gazers (34-35, five levels above you: one at a time) the far south."] = "{object:19868}散落在赛道北边的盐滩上。恐蝎劫掠者和盐壳龟在北半部游荡，盐湖食腐鹫在空中盘旋，盐石蜥蜴在赛道西边吃草。盐石水晶蜥蜴在盐滩中部游荡，盐石凝视者（34-35级，比你高五级：一次引一只）在最南边。",
} end)()
t.guides["forever/horde/30-40/01-desolace"] = (function() return {
		["Back at {area:609}, every Kolkar can drop an ear."] = "回到{area:609}，每个科卡尔半人马都可能掉落耳朵。",
		["Back to {area:272}"] = "返回{area:272}",
		["Clam beds"] = "蚌床",
		["Daggerspine naga"] = "刺脊纳迦",
		["Daggerspine shore"] = "刺脊海岸",
		["Do your shopping in the {area:1497} first, then fly to the {area:228}. The {object:113791} stands on the hill just south-west of it: beat the Corrupt Manifestation of Water beside it, place its bracers in the brazier, speak to the {npc:5895} and keep the {item:7813} for {npc:5901}. Fly on to {area:272} from the {area:228}."] = "先在{area:1497}采购，然后飞往{area:228}。{object:113791}在它西南边的小山上：击败旁边的堕落水之魂，把它的护腕放进火盆，与{npc:5895}交谈，留着{item:7813}交给{npc:5901}。然后从{area:228}继续飞往{area:272}。",
		["Fly to the {area:1497}"] = "飞往{area:1497}",
		["Fly to {area:1637}"] = "飞往{area:1637}",
		["Fly to {area:1638} from Shadowprey and train with {npc:3033} on {area:1639}, then fly on to {zone:1454}."] = "从葬影村飞往{area:1638}，在{area:1639}找{npc:3033}训练，然后继续飞往{zone:1454}。",
		["Fly to {area:392}. {npc:5901} camps on the coast a short ride south of the town."] = "飞往{area:392}。{npc:5901}在城镇南边不远的海岸上扎营。",
		["Fly to {area:460}"] = "飞往{area:460}",
		["Fly to {area:484}. {npc:5905} hides in a small cave in the canyon wall north-east of the post."] = "飞往{area:484}。{npc:5905}躲在哨站东北峡谷崖壁上的一个小山洞里。",
		["Follow the road north out of {area:272} into the Alterac foothills. {quest:535} waits by the Syndicate camp; hand him the stout."] = "沿道路向北离开{area:272}，进入奥特兰克山麓。{quest:535}在辛迪加营地旁等候；把南海镇烈酒交给他。",
		["Follow the road south-west out of Sun Rock into {zone:1443} and on south past {area:608}. {npc:11625}'s kodo caravan waits by the road north of {area:609}; if it has already left, ride on."] = "沿道路向西南离开烈日石居进入{zone:1443}，继续向南经过{area:608}。{npc:11625}的科多兽商队在{area:609}北边的路旁等候；如果它已经出发，就继续骑行。",
		["Follow the shore west past {area:271}'s bay; the Torn Fin murlocs camp on the beaches beyond it."] = "沿海岸向西经过{area:271}的海湾；碎鳍鱼人在海湾另一边的海滩上扎营。",
		["From {area:484}, fly to {area:1637}."] = "从{area:484}飞往{area:1637}。",
		["Gizelton caravan"] = "基泽尔顿商队",
		["Head west along the foot of the mountains to the violet dome of {area:279}. {npc:2411}, {npc:2412} and {npc:2413} (33-34) stand together inside the crater's eastern rim, {npc:2414} (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-32) around them drop the Worn Stone Tokens."] = "沿山脚向西前往{area:279}的紫色穹顶。{npc:2411}、{npc:2412}和{npc:2413}（33-34级）一起站在陨坑东缘内侧，{npc:2414}（35级）在他们西边不远处；每人携带一块血石。他们周围的达拉然持盾守卫和达拉然法师（31-32级）掉落{item:3714}。",
		["Hearth back (or ride north if it is on cooldown)."] = "用炉石回去（如果炉石在冷却，就向北骑回去）。",
		["His next errand is not on this route."] = "他的下一个差事不在本路线上。",
		["Keep north to {area:598}. The Oracles stand among the other naga at its north end; pull one at a time."] = "继续向北前往{area:598}。滑刃智者站在北端的其他纳迦中间；一次引一只。",
		["Kolkar ears"] = "半人马的耳朵",
		["Leave {zone:1454} by the main gate; the zeppelin tower stands just north-east of it. Take the {area:1497} zeppelin."] = "从正门离开{zone:1454}；飞艇塔就在大门东北边。乘坐前往{area:1497}的飞艇。",
		["North along the eastern hills, the satyrs hold the ruins of {area:603}. The Shadowstalkers walk unseen; the four kinds you need do not."] = "沿东边的山丘向北，萨特占据着{area:603}的废墟。怨怒巡影者隐形行走；你需要的四种萨特则不会。",
		["Place the {object:1729} on the {object:1728} beside the inn"] = "把{object:1729}放在旅店旁的{object:1728}上",
		["Ride back east to {area:272}."] = "向东骑回{area:272}。",
		["Ride back north to {area:272}, keeping west of {area:271}."] = "向北骑回{area:272}，从{area:271}西边绕过。",
		["Ride back south to the post."] = "向南骑回哨站。",
		["Ride back south to {area:272}."] = "向南骑回{area:272}。",
		["Ride north past {quest:535}'s camp to {area:280}, the Syndicate-held village (35-37). {npc:2431} carries the {item:3704}; {quest:503} sits in a cage in the house on the north side."] = "向北骑过{quest:535}的营地，前往辛迪加占据的村庄{area:280}（35-37级）。{npc:2431}携带{item:3704}；{quest:503}被关在北侧房子的笼子里。",
		["Ride north up the coast. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach; open each clam in your bags for its meat."] = "沿海岸向北骑行。巨型软壳蚌躺在浅水里，狂怒的暗礁蟹在海滩上走动；在背包里打开每个蚌取出软壳蚌肉。",
		["Ride north-east to {area:609}. {quest:1365} (35) walks among the tents on the east side with a Battle Lord or two (32-33): clear around him, then pull him alone at full health."] = "向东北骑往{area:609}。{quest:1365}（35级）带着一两个科卡尔队长（32-33级）在东侧的帐篷间走动：先清理他周围，然后在满血时单独引他。",
		["Ride south, east of {area:271}, down to the coast. The Daggerspine naga line the shore south-east of the town."] = "向南骑行，从{area:271}东边下到海岸。刺脊纳迦分布在城镇东南的海岸上。",
		["Ride south-east to the post."] = "向东南骑往哨站。",
		["Ride south-west to the troll village on the coast, keeping clear of the {area:606} on the way."] = "向西南骑往海岸边的巨魔村庄，途中避开{area:606}。",
		["Ride south-west towards Shadowprey. The Gelkis centaurs (32-35) around their village are a good camp; fight them until level 32."] = "向西南朝葬影村骑行。村庄周围的吉尔吉斯半人马（32-35级）很适合刷；打到32级为止。",
		["Ride west to {area:599}. Beat a Burning Blade cultist down, then use the {item:6436} on it before it dies to fill one {item:6435}. They also drop a {item:20310} now and then (1-5%); if one drops, read it."] = "向西骑往{area:599}。把一个火刃氏族信徒打到残血，在它死前对它使用{item:6436}，充满一个{item:6435}。他们偶尔也会掉落{item:20310}（1-5%）；如果掉了，就阅读它。",
		["Shadowstalker scalp"] = "巡影者的头皮",
		["Shindigger keg"] = "矿工烈酒酒桶",
		["Slitherblade Oracles"] = "滑刃智者",
		["South-west, the Cave and Ferocious Yetis (30-31) fill the caves in the hills west of {area:272}; about one in sixteen carries the rod."] = "在西南，洞穴雪人和凶恶的雪人（30-31级）占满了{area:272}西边山丘里的洞穴；大约十六分之一带着魔棒。",
		["Syndicate missives"] = "辛迪加信件",
		["Thaivand's next task ends at {area:271}'s graveyard and the magus offers a dungeon errand: leave both."] = "塞万德的下一个任务在{area:271}的墓地结束，而那位魔导师提供的是一个地下城差事：两个都别接。",
		["The Hatefury Shadowstalkers at {area:603} walk unseen until they strike; about one in three carries a scalp."] = "{area:603}的怨怒巡影者在攻击前都是隐形的；大约三分之一带着头皮。",
		["The Seer stands on the south side of {area:599}, east of {area:2405}. Clear the cultists around it first."] = "火刃先知站在{area:599}南侧，{area:2405}东边。先清掉它周围的信徒。",
		["The Syndicate Footpads and Thieves (32-33) around the camps west of the road carry the missives; about one in three drops one."] = "道路西边营地周围的辛迪加劫匪和辛迪加窃贼（32-33级）携带信件；大约三分之一会掉落。",
		["The caravan rolls south past {area:609}. Kolkar raiders ambush it in waves: kill them before they reach {npc:11625}. It stops by {area:2617}, east of {area:597}."] = "商队向南经过{area:609}。科卡尔袭击者会一波波伏击商队：在他们接近{npc:11625}之前杀死他们。商队停在{area:597}东边的{area:2617}旁。",
		["The keg stands with a few others at the Syndicate camp on the south-east coast of {area:287}."] = "酒桶和另外几个酒桶一起放在{area:287}东南海岸的辛迪加营地里。",
		["The next guide starts in the {area:1497}, at the {object:3202} zeppelin."] = "下一个指南从{area:1497}的{object:3202}飞艇处开始。",
		["The {area:279} traitors"] = "{area:279}的叛徒",
		["Torn Fin beach"] = "碎鳍海滩",
		["Torn Fin murlocs"] = "碎鳍鱼人",
		["Train"] = "训练",
		["Train your new spells."] = "训练你的新法术。",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. Five kodos, one at a time."] = "对坟场里的老迈的科多兽、濒死的科多兽或{npc:4702}使用{npc:11596}的{item:13892}，把驯服的科多兽带回{npc:11596}那里。共五头，一次一头。",
		["Your trainer is in {area:1638}, one flight away: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly on to {area:460} from there."] = "你的训练师在{area:1638}，飞一次即到：{area:1639}的{npc:3033}（德鲁伊），{npc:246344}（圣骑士）。然后从那里飞往{area:460}。",
		["Zeppelin to the {area:1497}"] = "乘飞艇前往{area:1497}",
		["Zeppelin tower"] = "飞艇塔",
		["for {npc:5901}: from Stranglethorn, next guide"] = "交给{npc:5901}：从荆棘谷前往，见下一个指南",
		["grind on Gelkis Stampers and Windchasers at the {area:606}, {zone:1443}"] = "在{zone:1443}的{area:606}刷吉尔吉斯践踏者和吉尔吉斯逐风者",
		["{area:2408} flight master"] = "{area:2408}的飞行管理员",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388}：拍卖行或炼金术士，用于{quest:515}。",
		["{item:3703}, for {npc:2333}"] = "{item:3703}，交给{npc:2333}",
		["{npc:11863} waits in the ruined tower of {area:2405}, inland to the south-east."] = "{npc:11863}在内陆东南方{area:2405}的废塔里等候。",
		["{npc:11877}: for {npc:715} in Stranglethorn"] = "{npc:11877}：交给荆棘谷的{npc:715}",
		["{npc:2229}: for the {zone:1413}, later on the route"] = "{npc:2229}：交给{zone:1413}，路线后面会去",
		["{npc:260093} trains Paladins in the {area:1497}."] = "{npc:260093}在{area:1497}训练圣骑士。",
		["{npc:2770}: for {area:321} in Arathi, later on the route"] = "{npc:2770}：交给阿拉希高地的{area:321}，路线后面会去",
		["{npc:4551}, the bat handler"] = "{npc:4551}，蝙蝠管理员",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}，在格罗玛什要塞，如果你带着它",
		["{npc:5395} stands in the post; {npc:5641} and {npc:4498} wait on the rise west of it, above the {area:596}."] = "{npc:5395}站在哨站里；{npc:5641}和{npc:4498}在哨站西边的高地上等候，俯瞰{area:596}。",
		["{npc:5639} waits in the Drag; {npc:5640} stands in the {object:172961} on the west side of the city. Skyborne: {npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:5639}在暗巷区等候；{npc:5640}站在城西侧的{object:172961}。天裔：{npc:4949}在{object:172957}的格罗玛什要塞里等候。",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "{npc:5641}的下一个差事要你去对付一个带着精英护卫的恶魔领主：跳过它。",
		["{npc:5641}'s next {quest:1431} sends you back to {zone:1454} for nothing: leave it."] = "{npc:5641}的下一个任务{quest:1431}让你白跑一趟{zone:1454}：别接。",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892}站在{object:172957}。",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905}还会开始元素援助（{area:1717}），这是通往风暴武器的33-40级任务线：见萨满祭司职业指南“空气的召唤和风暴武器（部落）”。",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}：你的{item:5178}",
		["{quest:515} needs a {item:3388}, an {skill:171} item: buy one at the auction house here if you can (or ask an alchemist). No potion: skip the Elixir steps in {area:287}."] = "{quest:515}需要一瓶{item:3388}，这是{skill:171}物品：如果可以，在这里的拍卖行买一瓶（或找炼金术士）。没有药水：跳过{area:287}的药剂步骤。",
		["{zone:1454} class quests"] = "{zone:1454}职业任务",
} end)()
t.guides["forever/horde/30-40/02-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "向北回到营地。",
		["Back to {object:3202}"] = "返回{object:3202}",
		["Back to {object:3202}."] = "返回{object:3202}。",
		["Basilisks and the Bloodscalp village"] = "蜥蜴和血顶村庄",
		["Bloodscalp headhunters"] = "血顶猎头者",
		["Bloodscalp ruins"] = "血顶废墟",
		["East of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}."] = "在食人魔东边，深喉猎豹（37-38级）在攻击前都是隐形的；荆棘谷雌虎在同一片地方游荡，偶尔掉落雌虎的牙齿。钳嘴鳄鱼分布在丛林正西的河边；留着它们的皮交给{npc:2495}。",
		["Elder tigers and Lashtail raptors"] = "老年猛虎和鞭尾迅猛龙",
		["Fly to {area:35}"] = "飞往{area:35}",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "沿道路向北离开{object:3202}；奈辛瓦里的狩猎营地在河东北边的山上。从现在起，留着拾取到的每一页{quest:338}：{npc:716}之后会要。",
		["Follow the road on south into {area:35}."] = "沿道路继续向南进入{area:35}。",
		["Follow the road south to {area:35} at the southern tip of the vale and enter through the tunnel in the cliffs. Stay on the road: the jungle beside it is well above your level. {npc:2858}, the Horde flight master, waits on the upper deck."] = "沿道路向南前往山谷南端的{area:35}，从悬崖上的隧道进入。别离开道路：路旁丛林里的怪物比你高得多。部落飞行管理员{npc:2858}在上层甲板等候。",
		["Follow the road south to {object:3202}."] = "沿道路向南前往{object:3202}。",
		["Green Hills pages"] = "荆棘谷的青山书页",
		["Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it."] = "向西经过营地。荆棘谷迅猛龙（33-34级）在林间空地捕猎，血顶巨魔占据着海岸边的废墟：每个血顶巨魔都可能掉落獠牙。他们极少掉落{item:4614}：如果掉了，就阅读它。",
		["Hearth to {area:35}"] = "用炉石回到{area:35}",
		["Hearth to {object:3202}"] = "用炉石回到{object:3202}",
		["Jungle Stalkers"] = "丛林捕猎者",
		["Lashtail raptors"] = "鞭尾迅猛龙",
		["Leave the {zone:1458} by the lift and walk up through the ruins to the zeppelin towers; the {object:3202} zeppelin is the one on the south-west tower."] = "乘升降梯离开{zone:1458}，穿过废墟走到飞艇塔；前往{object:3202}的飞艇在西南边的塔上。",
		["Mistvale gorillas"] = "迷雾谷猩猩",
		["Mosh'Ogg camp"] = "莫什奥格营地",
		["Nesingwary's camp"] = "奈辛瓦里的营地",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "{area:104}位于格罗姆高营地西北的近海水下。{item:4094}躺在沉没废墟旁的海底；注意呼吸和鱼人。",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "{item:2755}的每一页从血顶巨魔和劈颅巨魔身上的掉率约为1%；留着拾取到的每一页，其余的去拍卖行找。{npc:716}会在本指南稍后收取各章节。",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; take what drops and check the Auction House for the rest."] = "{item:2755}的每一页从血顶巨魔和劈颅巨魔身上的掉率约为1%；拿上掉落的，其余的去拍卖行找。",
		["Raptors and the Bloodscalp trolls"] = "迅猛龙和血顶巨魔",
		["Ride back south to {object:3202}."] = "向南骑回{object:3202}。",
		["Ride north past Nesingwary's camp to the lake. The Venture Co. Geologists (34-36) work the camps along its western shore; they carry the Tumbled Crystals."] = "向北骑过奈辛瓦里的营地前往湖边。风险投资公司地质学家（34-36级）在湖西岸的营地里干活；他们携带打磨过的水晶。",
		["Ride south down the coast to {object:3202} and fly to {area:35}."] = "沿海岸向南骑往{object:3202}，然后飞往{area:35}。",
		["Shadowmaw jungle and the Snapjaw river"] = "深喉猎豹的丛林和钳嘴鳄鱼的河流",
		["Shadowmaw panthers"] = "深喉猎豹",
		["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "荆棘谷猛虎和黑豹（32-33级）在营地东边沿湖岸的山丘上游荡。",
		["Take the road south towards {area:35}. The Elder Mistvale Gorillas (40-41) live in {area:1737}, east of the road; about one in twenty carries an aged sinew."] = "沿道路向南朝{area:35}前进。老迈的迷雾谷猩猩（40-41级）住在道路东边的{area:1737}；大约二十分之一带着成年大猩猩的肌腱。",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202} and fly to {area:392}. {npc:5901} camps on the coast a short ride south of it."] = "在{object:3202}西侧的塔上乘坐前往{zone:1454}的飞艇，然后飞往{area:392}。{npc:5901}在它南边不远的海岸上扎营。",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202} and train in the city before you fly on."] = "在{object:3202}西侧的塔上乘坐前往{zone:1454}的飞艇，继续飞行前先在城里训练。",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads."] = "海岸村庄里的血顶猎头者（36-37级）携带皱缩的头颅。",
		["The Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "血顶巨魔占据着暗礁北边沿海的废墟和更远处的村庄；每个都可能掉落{item:3915}。继续拾取{quest:338}的书页。",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp; the Lashtail Raptors (35-36) hunt further south, towards {object:3202}."] = "老年荆棘谷猛虎（34-35级）在营地西南的山丘上游荡；鞭尾迅猛龙（35-36级）在更南边、靠近{object:3202}的地方捕猎。",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "丛林捕猎者（40-41级）在{object:3202}南边的海岸捕猎。它们比你高得多：一次引一只，战斗间隙休息。",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "鞭尾迅猛龙（35-36级）在{object:3202}东北不远的丛林里捕猎。",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}. Kill one Brute and one Witch Doctor (36-37); pull them one at a time."] = "莫什奥格食人魔在{object:3202}正东的山丘上扎营。杀死一个莫什奥格蛮兵和一个莫什奥格巫医（36-37级）；一次引一个。",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "深喉猎豹（37-38级）在莫什奥格山丘东边和东北方通往湖泊的丛林里潜行；它们会从潜行中发动攻击。沿途拾取你找到的每一页荆棘谷的青山。",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "深喉猎豹要很久以后才会遇到，在{object:3202}附近",
		["The camp by the river"] = "河边的营地",
		["The next guide flies you north to {area:272} and into the {zone:1417}."] = "下一个指南会带你向北飞往{area:272}，进入{zone:1417}。",
		["The zeppelin lands at the tower on the west side of the camp."] = "飞艇降落在营地西侧的塔上。",
		["Tigers and panthers"] = "猛虎和黑豹",
		["Venture Co. camp"] = "风险投资公司营地",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear."] = "向西经过营地，晶背蜥蜴（34-35级）趴在岩石上；再往前的村庄里每个血顶巨魔都可能掉落耳朵。",
		["Young Stranglethorn Tigers prowl west of the camp, Young Panthers south and east of it."] = "荆棘谷猛虎幼崽在营地西边游荡，猎豹幼崽在营地南边和东边。",
		["Young tigers and panthers"] = "猛虎幼崽和猎豹幼崽",
		["Zeppelin to {object:3202}"] = "乘飞艇前往{object:3202}",
		["Zeppelin towers"] = "飞艇塔",
		["{npc:2495}: the Snapjaw skins gathered earlier"] = "{npc:2495}：之前收集的钳嘴鳄鱼的皮",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}：交给阿拉希高地，路线后面会去",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}：{npc:3527}和你的{item:5177}",
		["{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp."] = "{npc:729}是一只37级的老虎，在营地西南的山顶上游荡。",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "{npc:773}失踪猎人的营地就是奈辛瓦里的营地：在帐篷间走一圈，调查就会完成。淡水鳄趴在营地下方的河边。",
} end)()
t.guides["forever/horde/30-40/03-arathi-highlands"] = (function() return {
		["Back to {area:321}"] = "回到{area:321}",
		["Boulderfist camp"] = "石拳营地",
		["Cast {spell:18960} and take {npc:11798}'s flight to {area:1638}; {npc:3033} trains you on {area:1639}. Then fly to {zone:1454} and take the {zone:1458} zeppelin from the tower outside the main gate."] = "施放{spell:18960}，乘{npc:11798}的飞行路线前往{area:1638}；{npc:3033}在{area:1639}训练你。然后飞往{zone:1454}，在正门外的塔上乘坐前往{zone:1458}的飞艇。",
		["Coyotes and buzzards"] = "山狗和秃鹫",
		["Daggerspine shore"] = "刺脊海岸",
		["Each {object:180105} is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of {area:321}."] = "每个{object:180105}都是一圈立石；钥匙在中心的石头上。东部的法阵在{area:321}西北方的山丘上。",
		["Escort the professor down to the shore. Two Daggerspine naga ambush him on the way: stay close."] = "护送教授到岸边。途中会有两个刺脊纳迦伏击他：跟紧他。",
		["Fleshstalker raptors"] = "猎兽龙",
		["Fly to {area:272}"] = "飞往{area:272}",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Follow the road north; {npc:4618}'s camp is on the way."] = "沿道路向北；{npc:4618}的营地就在路上。",
		["From {area:35}, fly to {object:3202}. {object:1661} zeppelin leaves from the tower on the west side of the camp."] = "从{area:35}飞往{object:3202}。{object:1661}飞艇从营地西侧的塔楼出发。",
		["Greater Rock Elementals"] = "巨型石元素",
		["Hearth to {area:340}"] = "用炉石返回{area:340}",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "高地猎兽龙（36-37级）在南部高地狩猎，一群在{area:316}北边，另一群在其西边的平原上。一次拉一只。",
		["Highland Striders roam the hills all around {area:321}; both they and the Thrashers further west drop the eyes."] = "高地阔步龙在{area:321}四周的山丘上游荡；它们和更西边的高地长尾龙都会掉落眼睛。",
		["Highland raptors"] = "高地迅猛龙",
		["Into the {zone:1418}"] = "进入{zone:1418}",
		["Keep north on the road; the chest lies in the {area:1517} dig site, at the foot of the ruins north-west of the road."] = "继续沿道路向北；箱子在{area:1517}挖掘场，位于道路西北方的废墟脚下。",
		["Lesser Rock Elementals"] = "次级石元素",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael."] = "落锤镇东北方，枯须狗头人在峡谷中采矿；峡谷口的枯须狗头人和深处的枯须掘地工、枯须勘探员都会掉落密斯莱尔之尘。",
		["Ride back south down the road, past the {area:1877}."] = "沿道路向南骑回，经过{area:1877}。",
		["Ride back south to the {area:380} and fly to {area:392}."] = "向南骑回{area:380}，飞往{area:392}。",
		["Ride east out of {area:272} through {area:1857} and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south-east of {area:313}."] = "从{area:272}向东骑出，穿过{area:1857}，沿道路向东。石拳食人魔和石拳执行者（32-34级）在道路南边、{area:313}东南方扎营。",
		["Ride north back to {area:340}."] = "向北骑回{area:340}。",
		["Ride north up the road from the {area:380} to the {area:386}; {npc:3389} keeps watch on the rise above the water."] = "从{area:380}沿道路向北骑到{area:386}；{npc:3389}在水边的高地上放哨。",
		["Ride north; the outer circle stands in the middle of the highlands."] = "向北骑行；外部法阵位于高地中央。",
		["Ride south along the coast from {area:392} to {area:720}. {npc:6236} stands by the arena: step on the grate to start the fight; the challengers come one at a time, then {npc:6238} (33)."] = "从{area:392}沿海岸向南骑到{area:720}。{npc:6236}站在竞技场旁：踏上格栅开始战斗；挑战者依次上场，然后是{npc:6238}（33级）。",
		["Ride south-west out of Arathi over {area:880}, south through the {zone:1437} (keep clear of {area:150}) and east into {zone:1432}; the road leaves {zone:1432} to the south into the {zone:1418}. Follow it south to the goblin camp in the {area:1877}."] = "从阿拉希向西南越过{area:880}，向南穿过{zone:1437}（远离{area:150}），向东进入{zone:1432}；道路从{zone:1432}向南通往{zone:1418}。沿路向南到{area:1877}的地精营地。",
		["Ride south-west to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "向西南骑行到南部海岸的地精海湾。{npc:2766}在海湾上方的悬崖上放哨。",
		["Ride west along the road; {npc:2921}'s camp sits in the {area:1878} halfway to {area:340}."] = "沿道路向西骑行；{npc:2921}的营地在前往{area:340}半途的{area:1878}。",
		["Rock Elementals"] = "石元素",
		["Stonevault troggs"] = "石窟穴居人",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202}."] = "在{object:3202}西侧的塔楼乘飞艇前往{zone:1454}。",
		["The Boulderfist Brutes camp outside the ogres' hall south of {area:321}; the Magus stand among them. Pull them one at a time."] = "石拳蛮兵在{area:321}南边食人魔大厅外扎营；石拳法师站在它们中间。一次拉一个。",
		["The Elder Crag Coyotes and Giant Buzzards roam the basin south of the {area:1878}. Coyotes drop both the jawbones and the fangs; only the buzzards drop wings and gizzards."] = "{npc:2729}和{npc:2831}在{area:1878}南边的盆地中游荡。山狗掉落颚骨和尖牙；只有秃鹫掉落翅膀和胃。",
		["The Greater Rock Elementals (42-44, well above you) wander the gulches in the south-west; the bracers drop about one kill in five. Pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "巨型石元素（42-44级，远高于你）在西南部的沟壑中游荡；护腕约五次击杀掉落一次。一次拉一个，战斗间休息，或者放弃。途中继续击杀还需要的山狗和秃鹫。",
		["The Stonevault troggs dig around the cave mouths south of the {area:1877}, on the way to {area:345}; the Bonesnappers and Shamans drop the flakes."] = "石窟穴居人在{area:1877}南边、通往{area:345}路上的洞口周围挖掘；石窟断骨者和石窟萨满祭司掉落薄片。",
		["The Syndicate hold the walled manor and its farm in the north-west; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets."] = "辛迪加占据西北部有围墙的庄园和农场；辛迪加路霸、辛迪加雇佣兵和辛迪加巡路者携带血石护符。",
		["The Witherbark trolls hold the village in the south-eastern hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village."] = "枯木巨魔占据东南部山丘中的村庄。枯木掷斧者守卫外围的小屋；枯木巫医和枯木猎头者占据村子中心。",
		["The bigger Rock Elementals stand on the slopes north-west of the {area:1878}; each one drops a slab."] = "更大的{npc:92}站在{area:1878}西北方的山坡上；每个都掉落一块石板。",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "内部法阵在西部法阵南边、激流堡东边。",
		["The next guide heads into {zone:1445}."] = "下一份指南前往{zone:1445}。",
		["The orc stronghold at the eastern end of the road. Urda, the wind rider master, stands by the gate."] = "道路东端的兽人要塞。双足飞龙管理员尤尔达站在大门旁。",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "小型元素在{npc:2921}营地正西的平地上飘荡。这个地区的每个石元素都可能掉落{npc:6868}要的石元素的碎片：留着它们。",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "石头的下一个任务需要击败42级精英弗兹鲁克：放着别管。",
		["The violet shards glow just off the road a short way west of {area:321}."] = "紫色碎片在{area:321}西边不远处的路旁发光。",
		["The western circle is near {area:1857}, where you rode in."] = "西部法阵在你进来时经过的{area:1857}附近。",
		["The zeppelin lands at the towers outside the {zone:1458}: ride down into the city and fly to {area:272}."] = "飞艇降落在{zone:1458}外的塔楼：骑下去进城，飞往{area:272}。",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2689}"] = "{object:2689}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701}在峡谷最深处。",
		["The {object:2702}"] = "{object:2702}",
		["Theldurin sits among the dwarven ruins at {area:345}, south of the {area:1877}."] = "塞尔杜林坐在{area:1877}南边{area:345}的矮人废墟中。",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "趁在{zone:1458}时训练：训练师在{object:36070}、{object:36073}和{object:36082}（圣骑士：{npc:260093}）。",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "海湾西边，刺脊袭击者和刺脊巫师（38-40级）占据海岸：一次拉一个。两艘沉船在近海浅水中，海图和日志在船里；宝石在沉船周围的海底。",
		["Your trainer is in {area:1638}, one flight from {zone:1454}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly on to the {area:380} from there."] = "你的训练师在{area:1638}，从{zone:1454}飞一次即到：{area:1639}的{npc:3033}（德鲁伊），{npc:246344}（圣骑士）。然后从那里飞往{area:380}。",
		["Zeppelin to the {zone:1458}"] = "乘飞艇前往{zone:1458}",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["Zeppelin tower"] = "飞艇塔",
		["for Helgrum in {area:75}, around level 42"] = "交给{area:75}的赫格拉姆，约42级",
		["for {npc:2487} in {area:35}, around level 44"] = "交给{area:35}的{npc:2487}，约44级",
		["for {npc:5395} in {zone:1443}, in the next guide"] = "交给{zone:1443}的{npc:5395}，在下一份指南中",
		["{area:340} is the Horde fortress built into the cliffs at the zone's western edge."] = "{area:340}是建在地区西缘悬崖中的部落要塞。",
		["{item:3713}, for \"Swamp Eye\" Jarl in {zone:1445}"] = "{item:3713}，交给{zone:1445}的“沼泽之眼”加尔",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "{npc:2771}的下一个{quest:678}要对付石拳精英：放着别管。",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920}：仅当你携带{item:2868}时（{skill:164}或拍卖行）",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661}没有猎人或萨满祭司训练师：改从同一座塔楼乘飞艇前往{zone:1454}，在城里训练，然后从{zone:1454}正门外的塔楼乘飞艇前往{zone:1458}。",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}：来自{area:439}的菲兹尔的信",
		["{zone:1458} trainers"] = "{zone:1458}的训练师",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Darkfang spiders"] = "暗牙蜘蛛",
		["Fly to {area:378}"] = "飞往{area:378}",
		["For {npc:2519} at {object:3202}, in the next guide"] = "交给{object:3202}的{npc:2519}，在下一个指南中",
		["Hearth to Shadowprey"] = "用炉石回到葬影村",
		["Hearth to {area:392}"] = "用炉石回到{area:392}",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "加尔住在{area:502}东南的{area:497}。",
		["Kodo bones and ghosts"] = "科多兽骨和幽灵",
		["Maraudine totems"] = "玛洛迪图腾",
		["Mirefin murlocs"] = "黑鳍鱼人",
		["Pick up the kodo bones scattered across the graveyard, and use the {item:15848} among the bones: the ghosts it draws drop the ghost-o-plasm."] = "捡起散落在坟场各处的科多兽骨，并在骨头间使用{item:15848}：被吸引来的幽灵会掉落幽灵电浆。",
		["Ride back west to Brackenwall with the head."] = "带着头颅向西骑回蕨墙村。",
		["Ride east back to the {area:497}."] = "向东骑回{area:497}。",
		["Ride east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "从{area:378}沿道路向东骑进沼泽。烧毁的{area:403}就在边界过去一点的路旁；盾牌、徽章和蹄印都在废墟里面和旁边。",
		["Ride east to {area:602}. Use the Rod of Banishing by each demon portal to close six of them."] = "向东骑往{area:602}。在每个恶魔传送门旁使用任务给你的放逐法杖，关闭其中六个。",
		["Ride north from the coven to {npc:5412} at {area:597}."] = "从集会所向北骑往{area:597}的{npc:5412}。",
		["Ride north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "向北骑往{area:502}。伊格纳兹站在山脚下；在他到山南边采集叶子时护送他。",
		["Ride north up the road to the hut by the road north of the graveyard."] = "沿道路向北骑往坟场北边路旁的小屋。",
		["Ride north-east to the {area:607}. {npc:12277} is held in the Maraudine centaur camp; free her and escort her out east of the valley."] = "向东北骑往{area:607}。{npc:12277}被关在玛洛迪半人马的营地里；救出她，护送她从山谷东边出去。",
		["Ride on south-west to Shadowprey."] = "继续向西南骑往葬影村。",
		["Ride south from {area:2405} into the {area:607}. The Maraudine Scouts, Wranglers, Maulers, Windchasers and Marauders (36-39) drop the {quest:93225}."] = "从{area:2405}向南骑进{area:607}。玛洛迪斥候、玛洛迪争斗者、玛洛迪虐待者、玛洛迪逐风者和玛洛迪掠夺者（36-39级）掉落{quest:93225}。",
		["Ride west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "向西骑回沼泽对面。蕨墙村北边山脊上的暗牙毒蜘蛛掉落毒囊。塞拉摩间谍（35-36级）潜伏在同一片树林里：他们处于潜行状态，所以要仔细看。",
		["Ride west to {npc:11863}'s tower at {area:2405} on the north-west coast."] = "向西骑往西北海岸{area:2405}的{npc:11863}之塔。",
		["Slitherblade coast"] = "滑刃海岸",
		["Stinky Ignatz"] = "伊格纳兹",
		["Swamp Eye Jarl"] = "“沼泽之眼”加尔",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "在岔路口沿道路向北，前往食人魔村庄蕨墙村。",
		["The Burning Blade hold the fortress north-west of {area:2407}. Use the {item:14523} on the {npc:11876} in the fortress to get the {item:13542}."] = "火刃氏族占据着{area:2407}西北的要塞。在要塞里对{npc:11876}使用{item:14523}，获得{item:13542}。",
		["The Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes."] = "黑雾蜘蛛聚集在蕨墙村西北的洞口；每种都会掉落眼球。",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "黑鳍鱼人聚集在{area:502}东边和东北边的海岸上；每种都会掉落头。",
		["The Slitherblade naga hold the coast north of {area:2405}, up to {area:598}. {npc:12369} guards the {quest:6027} at the far northern tip."] = "滑刃纳迦占据着{area:2405}北边直到{area:598}的海岸。{npc:12369}在最北端守护着{quest:6027}。",
		["The caravan ends at {npc:11596}'s camp on the east side of the {area:596}."] = "商队终点是{area:596}东侧{npc:11596}的营地。",
		["The next guide takes you back to {zone:1434}."] = "下一个指南会带你回到{zone:1434}。",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "仅当你带着{item:3853}时（{skill:164}或拍卖行）",
		["{npc:11626}'s caravan stops on the road at the edge of {area:602}. Escort it east past the coven; demons attack it twice."] = "{npc:11626}的商队停在{area:602}边缘的路上。护送商队向东经过集会所；恶魔会袭击两次。",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}，在道路进入村庄处的南缘",
		["{npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "{npc:4983}在村庄东边的{area:2302}等候。跟着他去找雷瑟，并在随后爆发的战斗中保护他活下来。",
		["{npc:5395} and {npc:5412} stand in the post just west of {npc:11596}'s camp."] = "{npc:5395}和{npc:5412}站在{npc:11596}营地正西的哨站里。",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019}在{area:596}西侧的地精营地里等候。",
		["{npc:6791}: the last guide binds here, so this usually ticks at once"] = "{npc:6791}：上一份指南在这里绑定炉石，所以这一步通常会立即完成",
		["{object:20985}, beside the manor"] = "{object:20985}，在庄园旁边",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}，现在{npc:4791}已经读过报告了",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Boat to {area:35}"] = "乘船前往{area:35}",
		["Draenethyst crystals"] = "德莱尼水晶",
		["Fly to {area:392}"] = "飞往{area:392}",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "沿海岸向南。纳迦探险者在岸边涉水而行，携带一捆海蛇草；{object:759}就在他们正东的山丘里冒泡。",
		["From {area:2408} fly to {area:392}."] = "从{area:2408}飞往{area:392}。",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals."] = "再往北，风险投资公司的地精在道路东边的矿洞里挖掘；矿工、工头、勘探员和修理工都会掉落水晶。",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "把猩猩牙交给安巴格瓦并待在他身边：他会召唤三波猩猩，然后是{npc:1514}。一次对付一个。",
		["Hearth to {area:35}"] = "用炉石回到{area:35}",
		["Hearth to {object:3202}"] = "用炉石回到{object:3202}",
		["His strongbox waits at his old camp north of {area:75}."] = "他的保险箱在{area:75}北边他原来的营地里。",
		["Into the {zone:1435}"] = "进入{zone:1435}",
		["Jungle stalkers"] = "丛林捕猎者",
		["Keep riding north into {zone:1431}, then east along the road through {zone:1430} into the swamp. {npc:1776} waits at the {area:657}, the draenei camp near the way in from {zone:1430}."] = "继续向北骑进{zone:1431}，然后沿道路向东穿过{zone:1430}进入沼泽。{npc:1776}在{area:657}等候，那是靠近{zone:1430}入口的德莱尼营地。",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "从隧道出城；信件在{area:35}正北的海盗海湾里。",
		["Mistvale gorillas"] = "迷雾谷猩猩",
		["Naga shore and the {object:759}"] = "纳迦海岸和{object:759}",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "木棒诺博鲁在{area:76}西南的空地上游荡；他的木棒可以开始一个任务。",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "在迷雾谷东北，赞吉尔的追随者在丛林里扎营；他们每个人都可能携带赞吉尔的药剂。",
		["Pirate ghosts"] = "海盗幽灵",
		["Ride back east past {area:75} and follow the road south-east to the small Horde post on the shore."] = "向东骑回{area:75}，沿道路向东南前往岸边的部落小哨站。",
		["Ride east to {area:75}, in the reeds south of the road."] = "向东骑往道路南边芦苇丛中的{area:75}。",
		["Ride north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "向北骑往风险投资公司矿洞东边的劈颅巨魔废墟；把猎头者和狂战士一个个引出来。{npc:1059}守卫着西南边的废墟，一堆颅骨堆就在废墟北侧。每个劈颅巨魔都可能掉落獠牙或项链：项链是最慢的部分，所以在废墟北边的战士营地里一直杀，直到拿齐为止。",
		["Ride north up the road to the hunters' camp."] = "沿道路向北骑往猎人营地。",
		["Ride north up the road; the hunters camp on the hill above the river."] = "沿道路向北骑行；猎人们在河上方的山丘上扎营。",
		["Ride north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "向东北骑往{area:76}。水晶分布在通往{npc:5391}笼子的路上。",
		["Ride north-west to {object:3202}."] = "向西北骑往{object:3202}。",
		["Ride south to {area:35}. Shaky Phillipe waits on the docks."] = "向南骑往{area:35}。“病鬼”菲利普在码头上等候。",
		["Ride west along the road to the draenei camp at the {area:657}, near the way in from {zone:1430}."] = "沿道路向西骑往{area:657}的德莱尼营地，靠近{zone:1430}的入口。",
		["Ride west to {object:3202}."] = "向西骑往{object:3202}。",
		["Sawtooth crocolisks"] = "盐齿鳄鱼",
		["Sawtooth snappers"] = "盐齿钳嘴鳄",
		["Skullsplitter warriors"] = "劈颅战士",
		["South of Booty Bay the Bloodsail swashbucklers camp on the {area:43}; the charts and the orders lie in their tents. Any Bloodsail can carry snuff and {npc:2493}'s eye, so keep killing until you have both."] = "在藏宝海湾南边，血帆流氓在{area:43}扎营；血帆海图和血帆计划书就在他们的帐篷里。任何血帆海盗都可能携带鼻烟和{npc:2493}的眼睛，所以一直杀到两样都拿到为止。",
		["Take the road north out of {area:35}; Unbagwa sits on a hill in {area:1737}, east of the road."] = "沿道路向北离开{area:35}；安巴格瓦坐在道路东边{area:1737}的一座山丘上。",
		["The Bloodsail ships"] = "血帆海盗船",
		["The boat lands in {area:35}'s harbour. The quest givers stand on the boardwalks around the harbour and in the inn."] = "船停靠在{area:35}的港口。任务给予者站在港口周围的木栈道上和旅店里。",
		["The boat to {area:35} docks at the end of {area:392}'s pier."] = "前往{area:35}的船停靠在{area:392}码头的尽头。",
		["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "鳄鱼在{npc:5391}营地周围的水塘里打滚，一直到南边的{area:75}；大约四分之一会掉落鳄鱼肉。",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "猩猩在安巴格瓦周围的山谷里游荡。老迈的猩猩掉落内脏；任何猩猩都可能掉落猩猩牙。",
		["The last skulls are in the ruins a short ride west, on the way back to {object:3202}."] = "最后的颅骨堆在西边不远的废墟里，就在回{object:3202}的路上。",
		["The next guide starts here and takes you to {zone:1446}."] = "下一个指南从这里开始，带你前往{zone:1446}。",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp."] = "下一堆颅骨堆在战士营地正北的小废墟里。",
		["The snappers line the strand south of the post."] = "钳嘴鳄分布在哨站南边的海滩上。",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "丛林捕猎者迅猛龙在{object:3202}南边的丛林里捕猎，一直到西海岸。",
		["The three ghostly pirates haunt the jungle north of {area:35}, near Zanzil's camps: {npc:2535} and {npc:2536} stand together, {npc:2537} further east."] = "三个海盗幽灵在{area:35}北边、赞吉尔营地附近的丛林里出没：{npc:2535}和{npc:2536}站在一起，{npc:2537}在更东边。",
		["The three ships lie off the {area:43}. The crews are 42-45, Stillwater 45, Keelhaul 46 and {npc:2546} 48: at 41 this is a fight for a group, or for the end of the guide. If you go, swim out and pull the crew to the rail one at a time. A scroll, {quest:624}, lies on the ships' decks: take it."] = "三艘船停在{area:43}外的海面上。船员是42-45级，斯蒂沃特船长45级，尼哈鲁船长46级，{npc:2546}48级：41级时这是小队的战斗，或者留到本指南结束时再来。如果要去，就游过去，把船员一个个引到船舷边。船的甲板上有一张卷轴{quest:624}：拿上它。",
		["The {area:43}"] = "{area:43}",
		["Venture Co. mine"] = "风险投资公司矿洞",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "在远征队营地西边，血顶酋长{npc:1061}和{npc:1062}一起站在祖昆达废墟里。先清掉他们的守卫，再引他们。",
		["Zanzil's camps"] = "赞吉尔的营地",
		["Zul'Kunda"] = "祖昆达废墟",
		["Zul'Mamwe"] = "祖玛维废墟",
		["for Stoley in {zone:1446}"] = "交给{zone:1446}的斯杜雷",
		["for a later stop in the {zone:1435}"] = "留到之后在{zone:1435}停留时",
		["for later: the {zone:1425}, around level 48"] = "留到之后：{zone:1425}，大约48级时",
		["the {object:2076}"] = "{object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "{object:2076}，在{npc:2497}旁边",
		["{area:392} pier"] = "{area:392}码头",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391}被关在沼泽东北的{area:76}。救出他并跟着他出去，击退追赶他的沼泽生物。",
		["{npc:773}: for {quest:2864} in {area:976}"] = "{npc:773}：交给{area:976}的{quest:2864}",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Eastern Wastewander camps"] = "东部废土营地",
		["Fly to {area:1637}. The Droffers brothers run their shop in the Drag."] = "飞往{area:1637}。杜佛斯兄弟在暗巷区经营他们的商店。",
		["Fly to {area:484}"] = "飞往{area:484}",
		["Fly to {area:484}, ride down the lift east of the post and across the salt flats, then south into {zone:1446}."] = "飞往{area:484}，乘哨站东边的升降梯下去，穿过盐滩，然后向南进入{zone:1446}。",
		["Fly to {area:484}, then ride west through the canyons past {area:2237}; the road climbs into the {zone:1444} jungle and on to {area:1099}."] = "飞往{area:484}，然后向西穿过峡谷经过{area:2237}；道路向上进入{zone:1444}的丛林，一直通往{area:1099}。",
		["Fly to {area:75}"] = "飞往{area:75}",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Galestriders: {npc:265756}, in {area:16638} on Zephras Isle."] = "疾风陆行鸟：{npc:265756}，在泽风岛的{area:16638}。",
		["Grimtotem camp"] = "恐怖图腾营地",
		["Hearth to {area:1099}"] = "用炉石回到{area:1099}",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "继续向西骑到海岸。海滩上的海滩龙虾人先知和海滩利爪龙虾人大约每杀四十只掉落一个OOX-22/FE定位器：如果掉了，就使用它开始任务。",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "科多兽：{npc:3685}，在{area:222}的{npc:3690}旁边。",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "在豺狼人北边，食人魔占据着一座山顶前哨站；把食人魔法师引到你身边来打。戈杜尼钴矿石在前哨站周围的土堆里，戈杜尼卷轴就在前哨站里的地上。",
		["Only with the distress beacon: the robot sits in a small cave on the north side of {area:1105}. Escort it to the dock on the {area:1108}; yetis and gorillas ambush you on the way. Its reward waits in {area:35} for a later visit."] = "仅当你有定位器时：机器人在{area:1105}北侧的一个小山洞里。护送它到{area:1108}的码头；途中会有雪人和猩猩伏击你。它的奖励在{area:35}，留到之后再去领取。",
		["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "迅猛龙：祖尼尔，在{area:367}的{npc:7953}旁边。",
		["Ride back north-west from {area:1978} to {area:75} and fly to {object:3202}."] = "从{area:1978}向西北骑回{area:75}，然后飞往{object:3202}。",
		["Ride back west to {area:976}."] = "向西骑回{area:976}。",
		["Ride north-east to the goblin harbour on the coast."] = "向东北骑往海岸边的地精港口。",
		["Ride south-west to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb."] = "向西南骑往{area:1105}下方的食人魔废墟。里面满是戈杜尼萨满祭司、戈杜尼术士和戈杜尼虐待者；南端的戈杜尼大法师携带宝珠。",
		["Ride west into the middle of {zone:1444}. Kill a {npc:5308}, use {item:10699} on its body and kill the spirit that rises."] = "向西骑进{zone:1444}中部。杀死一只{npc:5308}，对它的尸体使用{item:10699}，再杀死升起的灵魂。",
		["Riding at 40"] = "40级学骑术",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is {npc:3690} in {area:222}, with {npc:3685}'s kodos (20 gold each) beside him. Forever may let any race learn from any riding trainer (not confirmed): try {npc:4752} in {zone:1454}'s {object:172958} first, as he is the nearest, and skip this step if he teaches you."] = "骑术需要40级，花费100金；学会后会获得一匹坐骑。在经典版中，每个种族都向本种族的训练师学习：你的训练师是{area:222}的{npc:3690}，旁边是{npc:3685}的科多兽（每匹20金）。Forever 可能允许任何种族向任何骑术训练师学习（未确认）：先试试{zone:1454}{object:172958}的{npc:4752}，因为他最近，如果他能教你就跳过此步骤。",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is {npc:4773} in {area:159}, with {npc:4731}'s skeletal horses (20 gold each) beside her. Forever may let any race learn from any riding trainer (not confirmed): try {npc:4752} in {zone:1454}'s {object:172958} first, as he is the nearest, and skip this step if he teaches you."] = "骑术需要40级，花费100金；学会后会获得一匹坐骑。在经典版中，每个种族都向本种族的训练师学习：你的训练师是{area:159}的{npc:4773}，旁边是{npc:4731}的骸骨军马（每匹20金）。Forever 可能允许任何种族向任何骑术训练师学习（未确认）：先试试{zone:1454}{object:172958}的{npc:4752}，因为他最近，如果他能教你就跳过此步骤。",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is {npc:7953} in {area:367} on the {zone:1411} coast, with Zjolnir's raptors (20 gold each) beside him. Forever may let any race learn from any riding trainer (not confirmed): try {npc:4752} in {zone:1454}'s {object:172958} first, as he is the nearest, and skip this step if he teaches you."] = "骑术需要40级，花费100金；学会后会获得一匹坐骑。在经典版中，每个种族都向本种族的训练师学习：你的训练师是{zone:1411}海岸{area:367}的{npc:7953}，旁边是祖尼尔的迅猛龙（每匹20金）。Forever 可能允许任何种族向任何骑术训练师学习（未确认）：先试试{zone:1454}{object:172958}的{npc:4752}，因为他最近，如果他能教你就跳过此步骤。",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel; no Skyborne riding trainer is known, so Skyborne try {npc:4752} too. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "骑术需要40级，花费100金；学会后会获得一匹坐骑。{npc:4752}在{object:172958}教授兽人，就在{npc:3362}的狼舍旁；目前不知道天裔的骑术训练师，所以天裔也试试找{npc:4752}。你种族的其他坐骑每匹20金：收藏指南“坐骑 · 40级”为每种坐骑都提供了指南。",
		["Rogue Vale screechers"] = "游荡的山谷尖啸者",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "骸骨军马：{npc:4731}，在{area:159}的{npc:4773}旁边。",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often."] = "沿海岸向南，南海海盗占据着海湾。{npc:7883}和被偷的货物在海湾尽头的码头上。任何海盗都可能掉落海盗帽，南海绑匪掉得最多。",
		["Southern Gordunni ruins"] = "南部戈杜尼废墟",
		["Southern Wastewander camps"] = "南部废土营地",
		["Sprite darters and Woodpaw alphas"] = "小精龙和木爪突击队员",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "恐怖图腾牛头人在小精龙的树林旁扎营；恐怖图腾袭击者、恐怖图腾博学者和恐怖图腾萨满祭司都携带恐怖图腾之角。",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane."] = "木爪豺狼人在莫沙彻营地西北不远的山丘上扎营；任何一个都可能掉落鬃毛。",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "祖卡什异种蝎的巢穴深入营地东南的山丘；{quest:7731}在最深处的洞室里等候。",
		["The bandits and thieves camp in the dunes east of {area:976}. Every Wastewander can carry a water pouch: keep ten, five for each of Luglunket's bounties."] = "强盗和窃贼在{area:976}东边的沙丘里扎营。任何废土敌人都可能携带废土水袋：留十个，鲁格伦克的两个悬赏各需五个。",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "木爪作战地图在莫沙彻营地南边的木爪营地里。",
		["The shadow mages, rogues and assassins camp south-east of {area:976}."] = "废土暗法师、废土游荡者和废土刺客在{area:976}东南扎营。",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour."] = "小精龙在莫沙彻营地正西的树林上空飞来飞去；几乎每只都会掉落翅膀。木爪突击队员率领着树林西南的营地：在一小时内杀死它们。",
		["The {object:3202} zeppelin leaves from the tower just north-east of {zone:1454}'s main gate."] = "前往{object:3202}的飞艇从{zone:1454}正门东北不远的塔上出发。",
		["The {zone:1454} zeppelin leaves from the tower beside {object:3202}; it lands just outside {zone:1454}'s main gate."] = "前往{zone:1454}的飞艇从{object:3202}旁的塔上出发；它降落在{zone:1454}正门外。",
		["Thysta, the flight master, stands just east of the zeppelin tower. Fly to {area:75}: the next guide starts there."] = "飞行管理员塞斯塔站在飞艇塔正东。飞往{area:75}：下一个指南从那里开始。",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "狼：{npc:3362}，在{npc:4752}旁边。",
		["Woodpaw battle map"] = "木爪作战地图",
		["Woodpaw north camp"] = "木爪北营地",
		["Your trainer is in {area:1638}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly there from {zone:1454}, then on to {area:484}."] = "你的训练师在{area:1638}：{area:1639}的{npc:3033}（德鲁伊），{npc:246344}（圣骑士）。从{zone:1454}飞过去，然后继续飞往{area:484}。",
		["Zeppelin to {object:3202}"] = "乘飞艇前往{object:3202}",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["Zeppelin tower"] = "飞艇塔",
		["for the {zone:1425}, around level 48"] = "交给{zone:1425}，大约48级时",
		["for {area:35}, around level 50"] = "交给{area:35}，大约50级时",
		["for {zone:1454}, around level 45"] = "交给{zone:1454}，大约45级时",
		["the {object:150075} in the square"] = "广场上的{object:150075}",
		["water pouches in your bags"] = "背包里的废土水袋",
		["{area:392} for the Felsteed"] = "前往{area:392}做地狱战马任务",
		["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976}是刚过{zone:1446}边界的地精城镇，有城墙环绕。",
		["{npc:3690}, riding trainer"] = "{npc:3690}，骑术训练师",
		["{npc:4752}, riding trainer"] = "{npc:4752}，骑术训练师",
		["{npc:4773}, riding trainer"] = "{npc:4773}，骑术训练师",
		["{npc:7953}, riding trainer"] = "{npc:7953}，骑术训练师",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}：交给{zone:1454}，大约45级时",
		["{npc:8579}: the screechers live in {zone:1444}"] = "{npc:8579}：尖啸者生活在{zone:1444}",
		["{quest:2863}: one hour from now"] = "{quest:2863}：从现在起一小时内",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "往回向东经过{area:75}：阿塔莱神器躺在{quest:1424}的水里和岸边。",
		["Dragon caves"] = "龙穴",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Forest walkers"] = "森林漫游者",
		["Frayfeather hippogryphs"] = "乱羽角鹰兽",
		["Monstrous Crawlers"] = "巨型淤泥蟹",
		["Murlocs of the Misty Reed"] = "芦苇丛中的鱼人",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "沿道路向西北，狂暴的怒痕雪人住在山丘里的洞穴周围。它们也都可能掉落{quest:7738}，它可以开始一个单独的任务。",
		["Northspring harpies"] = "北泉鹰身人",
		["Onyxia's eggs"] = "奥妮克希亚的蛋",
		["Rage Scar yetis"] = "怒痕雪人",
		["Ride back east to the camp. Stay here: the next guide starts with the flight to {area:976}."] = "向东骑回营地。留在这里：下一个指南从飞往{area:976}开始。",
		["Ride back north to Brackenwall."] = "向北骑回蕨墙村。",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "向西北骑往{area:1108}；{npc:14637}在码头上等候。",
		["Ride south-west to the {object:2555}, then east through the {area:511}. The Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "向西南骑往{object:2555}，然后向东穿过{area:511}。火鬃斥候和火鬃灰尾龙人与灼热龙崽、灼热雏龙一起在北缘游荡；火鬃守卫守护着更东南的龙穴。莫格穆洛克的鼻烟、烈酒和保险箱都在龙人营地里。",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "沿道路向西骑行；卷轴在沼泽最西边的水边。",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "海元素和巨型海元素沿着码头周围的海岸漂荡。先用{item:18904}电击巨人：被缩小后，它们就失去了精英的力量。海岸巨人在水中涉行；大地行者和峭壁巨人在更北边的山丘上游荡。",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "在山谷南边，乱羽角鹰兽栖息在山坡上；几乎每只都会掉落肌腱和金属碎片。",
		["South-west, the yetis den in {area:1105}; every yeti there can drop a thick hide."] = "在西南，雪人在{area:1105}筑巢；那里的每个雪人都可能掉落厚重的雪人皮。",
		["Sprite darters and forest walkers"] = "小精龙和森林漫游者",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "奥妮克希亚的蛋在{area:511}东南的龙穴里，由火鬃守卫看守；砸碎五个。",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "沼泽鱼人住在哨站南边的海滩上；沼泽喷墨鱼人在哨站东边的岸边，沼泽食腐鱼人在更西边、西岸的小屋周围。",
		["The Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see on the way south."] = "巨型淤泥蟹在东海岸的海滩上走动，数量稀少、相隔很远：向南的路上见一只杀一只。",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "北泉鹰身人在遥远西北的山脊上筑巢。它们是48-50级，比你高几级：北泉唤风者会治疗，所以先杀它们，一次引一只。",
		["The same murlocs again, plus the Oracles, who stay near the huts on the western shore."] = "还是同样的鱼人，外加沼泽鱼人智者，它们待在西岸的小屋附近。",
		["The small Horde post on the southern shore."] = "南岸的部落小哨站。",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "小精龙在营地正西的树林上空飞来飞去，携带{item:9589}；再往西一点的森林漫游者携带断裂的原木。",
		["The zeppelin to {zone:1454} leaves from the tower beside {object:3202}; it lands just north-east of {zone:1454}'s main gate."] = "前往{zone:1454}的飞艇从{object:3202}旁的塔上出发；它降落在{zone:1454}正门东北不远处。",
		["The {area:511}"] = "{area:511}",
		["You start in {area:75}. Bind here: you hearth back after the coast."] = "你从{area:75}出发。在这里绑定炉石：沿海岸做完后要用炉石回来。",
		["Your trainer is in {area:1638}: fly there (no flight path there yet? fly to {area:378} and ride west through {zone:1412}), then on to {area:496}."] = "你的训练师在{area:1638}：飞过去（还没有那里的飞行路线？飞往{area:378}，再向西骑马穿过{zone:1412}），然后继续前往{area:496}。",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["Zeppelin tower"] = "飞艇塔",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "交给{zone:1425}的{npc:5598}，大约48级时",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "交给{zone:1445}的{object:2555}，在本指南稍后",
		["for the {zone:1425} owlbeasts, around level 48"] = "交给{zone:1425}的枭兽任务，大约48级时",
		["the {object:2555}"] = "{object:2555}",
		["{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "{npc:4500}是精英：建议组队。把他打到认输，然后向{npc:4501}报告。",
		["{npc:7875}: for {npc:7010} in {zone:1454}, around level 50"] = "{npc:7875}：交给{zone:1454}的{npc:7010}，大约50级时",
		["{object:172958}, then the {object:172960} and the {object:172961}."] = "{object:172958}，然后是{object:172960}和{object:172961}。",
		["{quest:7738}, a rare drop"] = "{quest:7738}，稀有掉落",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Boat to {area:35}"] = "乘船前往{area:35}",
		["Dark Iron Lookouts"] = "黑铁哨兵",
		["Fly to {area:1637} and train: the next guide's training stop is the {zone:1458}, which has no Hunter or Shaman trainer. Then fly to {area:392}."] = "飞往{area:1637}训练：下一个指南的训练地点是{zone:1458}，那里没有猎人和萨满祭司训练师。然后飞往{area:392}。",
		["Fly to {area:1638} and train with {npc:3033} on {area:1639}, then fly to {area:392}."] = "飞往{area:1638}，在{area:1639}找{npc:3033}训练，然后飞往{area:392}。",
		["Fly to {area:340}"] = "飞往{area:340}",
		["Fly to {area:392}"] = "飞往{area:392}",
		["Fly to {area:976}"] = "飞往{area:976}",
		["From the {area:35} flight master, above the harbour."] = "从港口上方的{area:35}飞行管理员处出发。",
		["From {area:1099}'s flight master."] = "从{area:1099}的飞行管理员处出发。",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive."] = "再往南，初级勘察员谢申克的勘探设备在一个森提帕尔巢穴的入口处。",
		["Greater Lava Spiders"] = "灼热熔岩蜘蛛",
		["Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it."] = "重型作战傀儡在卡拉然下方的大熔炉里巡逻，掉落傀儡之油；在它们中间漂荡的熔岩元素和炽热元素掉落烈焰之心。黑铁工头和黑铁奴隶贩子在小路上驱赶奴隶；黑铁奴隶贩子可能掉落{item:11818}：留着它。",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "他的下一个请求需要精英信徒身上的{item:10552}：别接。",
		["Kalaran stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "卡拉然独自站在{area:1446}南边，大熔炉的边缘。听他讲他的故事。",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to {area:977}; its reward waits with Oglethorpe in {area:35}."] = "仅当你有定位器时：OOX-17/TN在谢申克所在巢穴的东南边。护送它向北前往{area:977}；它的奖励在{area:35}的奥格索普那里。",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "仅当你有{item:11818}时：向东回到挖掘场的{object:173265}。",
		["Ride back north to {area:1446}. Stay here: the next guide starts with the flight to {area:75}."] = "向北骑回{area:1446}。留在这里：下一个指南从飞往{area:75}开始。",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "向西北骑过峡谷；{area:1446}是西北边搭着脚手架的营地。",
		["Ride south-west to {area:976}."] = "向西南骑往{area:976}。",
		["Scrimshank's gear"] = "谢申克的勘探设备",
		["South down the road again."] = "再次沿道路向南。",
		["South of the {area:982} the Dunemaul ogres hold their compound, with {npc:12046} at its eastern end. Dig up {quest:3161} ornaments between the fights."] = "在{area:982}南边，砂槌食人魔占据着他们的营地，{npc:12046}在营地东端。在战斗间隙挖出{quest:3161}饰物。",
		["South-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp."] = "在加基森东南，废土强盗在沙丘里扎营；{npc:7847}站在东边的营地里。",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south-west to the dig site. The {object:173265} stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 {item:4306} (the Auction House sells it)."] = "从{area:340}西侧的山口进入{zone:1427}，然后向西南骑往挖掘场。{object:173265}在挖掘场南端；黑铁地质学家就在它北边挖掘。带上15块{item:4306}（拍卖行有卖）。",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "黑铁哨兵站在大熔炉南边哨塔周围的山脊上；大约十分之一带着{item:18960}。",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "黑铁锻造师在大熔炉中央的熔炉旁干活；他们一半带着{item:10551}，十分之一带着{item:18959}。奴隶工、黑铁奴隶贩子和黑铁工头也带着匕首。",
		["The Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge."] = "灼热熔岩蜘蛛在峡谷西南的高地和熔岩池一带游荡。",
		["The Steamsmiths' furnaces"] = "黑铁锻造师的熔炉",
		["The boat to {area:35} docks at {area:392}'s pier, below the flight master's hill."] = "前往{area:35}的船停靠在{area:392}的码头，就在飞行管理员所在山丘的下方。",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "{object:179827}告示板",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "沿道路向西再向南；{npc:7771}在{area:1938}的废墟旁扎营。戴上他的{item:9978}：它会显示埋在这里和{area:983}周围的饰物。",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "在加基森西边，在巨魔营地的水坑旁使用{item:8584}。",
		["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one."] = "在营地西边，仙人掌生物占满了山谷；只有灌木露水收集者携带露水腺。{zone:1446}的大多数怪物都可能掉落OOX-17/TN定位器，但很少见：如果看到就留着。",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts."] = "向西，森提帕尔虫群聚集在它们的巢穴周围；任何一只都会掉落森提帕尔昆虫肢体。",
		["for {npc:7010} in {area:1637}, around level 50"] = "交给{area:1637}的{npc:7010}，大约50级时",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526}生长在{zone:1425}，大约48级时",
		["the {object:150075} in the square"] = "广场上的{object:150075}",
		["the {object:173265}"] = "{object:173265}",
		["{area:1443} opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge."] = "{area:1443}在大熔炉北部。熏火龙在熔岩池里游动：把它们引到池边。秘密设计图在坑的上层岩架上。",
		["{area:392} pier"] = "{area:392}码头",
		["{item:11818}, a rare drop"] = "{item:11818}，稀有掉落",
		["{item:8623}, a rare drop"] = "{item:8623}，稀有掉落",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955}在山谷里等候。一路带他到东北方沙漠另一头{area:977}的妻子{npc:6015}那里：紧跟着他，放慢速度等他，击退攻击他的敌人。别骑上坐骑或用炉石离开他的范围。{npc:8579}也站在港口里。",
		["{npc:5955}'s escort"] = "护送{npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在双足飞龙管理员旁边",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "向西回到{area:350}；高原游侠和高原神射手待在旅舍附近，高原斥候和高原前锋在旅舍南边的山坡上。",
		["East of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south."] = "在道路东边，灰鬃野猪和格朗特在红石蜥蜴旁的山坡上拱土。远离更南边52级的地狱野猪。",
		["East of the village, the violet flower grows in the hills."] = "在村庄东边，紫色水生菇生长在山丘上。",
		["Fly to the {area:1497}"] = "飞往{area:1497}",
		["Fly to {area:272}"] = "飞往{area:272}",
		["Fly to {area:75}"] = "飞往{area:75}",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "沿道路向东穿过{zone:1425}，前往东海岸的巨魔村庄。",
		["From {area:1446}'s flight master."] = "从{area:1446}的飞行管理员处出发。",
		["Grind to 48"] = "刷到48级",
		["Highvale"] = "高原精灵",
		["His next request, going on to the {area:355}, is for a group."] = "他的下一个请求要前往{area:355}，需要组队。",
		["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. Keep to the paths: the trolls inside are elite."] = "猎户莫克霍尔的颅骨在邪枝废墟下方的一堆骨头上，他的骨头在{area:354}脚下的一堆上。污染之血容器放在下层平台上，{npc:14757}被关在最顶上。沿着小路走：里面的巨魔都是精英。",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "沿海岸向北，{npc:14731}的午餐篮在小岛上；一个{npc:14748}守着它。",
		["OOX-09/HL"] = "OOX-09/HL",
		["On the way back east, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps."] = "在东返途中，邪枝占卜者占据着中部山丘南边的巨魔神殿{area:355}。奇尔加和{npc:8636}（精英，50级）站在神殿顶上：只打下层台阶上的占卜者。",
		["Only if you are not level 48 yet."] = "仅当你还没到48级时。",
		["Only with the distress beacon: the robot sits at the head of the river west of {area:351}. Escort it east to the shore beyond the {area:307}; its reward waits with Oglethorpe in {area:35}."] = "仅当你有定位器时：机器人在{area:351}西边的河流源头处。护送它向东前往{area:307}另一边的海岸；它的奖励在{area:35}的奥格索普那里。",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "一路向西骑到蛮锤矮人的城镇{area:348}，把警告放在镇中央的水井旁。镇上全是联盟守卫：进去，放好，然后离开。",
		["Ride back north to the bloodmages."] = "向北骑回血法师那里。",
		["Ride north back to {area:75} and fly to the {area:1497}."] = "向北骑回{area:75}，飞往{area:1497}。",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "从{area:272}向东北骑进{zone:1425}，再沿道路向东；{npc:7801}在精灵的{area:350}南边的山上扎营。",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "从{area:75}向西出发，再向南穿过峡谷进入{zone:1419}；两位血法师就站在入口不远处的路旁。",
		["Saltwater Snapjaws"] = "海水钳嘴龟",
		["Silvermane Howlers"] = "银鬃嗥狼",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "在旅舍南边，枯木巨魔占据着他们的村庄。他们每个都携带头皮：收集到二十个后，使用{item:15002}做成尼姆布亚的长矛，然后把它插在村子里。",
		["South-west again, the exile hides by the ruins of {area:353}."] = "再次向西南，流放者躲在{area:353}的废墟旁。",
		["South-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "在西南，银鬃嗥狼在枯木村庄东边的山丘上游荡。",
		["The Highvale elves camp around {area:350}. Burn the report, the notes and the records in their camps. {npc:7780} is held inside the lodge: lead him out and fight off the ambush on the way."] = "高原精灵在{area:350}周围扎营。烧掉他们营地里的高原精灵报告、高原精灵信件和高原精灵记录。{npc:7780}被关在旅舍里：带他出来，并在路上击退伏击。",
		["The Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and {area:351}. Use the {item:9618} on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for {npc:14738}'s second message."] = "银鬃捕猎者、野蛮的枭兽和翱翔的锋喙狮鹫共处于神殿与{area:351}之间的山丘上。对你杀死的枭兽使用{item:9618}。锋喙狮鹫还会掉落细长的狮鹫羽毛：留十根给{npc:14738}的第二个口信用。",
		["The Vilebranch temples"] = "邪枝神殿",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "大海龟沿着村庄北边的海滩爬行。{npc:2491}的酒瓶也在这些海滩上，但他的任务不在本路线上。钳嘴龟可能掉落OOX-09/HL定位器，但很少见：留着它。",
		["The bloodmages"] = "血法师",
		["The central hills"] = "中部山丘",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "一箱箱{item:8684}散落在{area:351}被遗弃的部落营地周围，混在软泥怪中间。",
		["The eastern slopes"] = "东部山坡",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills."] = "这五个任务需要的是同样的部件：一趟全部收集齐。在道路西边，{npc:5982}秃鹫、饥饿的弯牙土狼、厚甲毒刺蝎和死眼蜥蜴共处于山丘上。",
		["The next guide starts here, at {area:3317}."] = "下一个指南从这里开始，在{area:3317}。",
		["The northern beasts"] = "北部的野兽",
		["The secret lies on the {area:307}, above the beach."] = "林吉的秘密在海滩上方的{area:307}。",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "他们的后续任务又要同样的部件，换取一件增益物品，而且不给经验：别接。",
		["Vilebranch soothsayers"] = "邪枝占卜者",
		["Vulture hills"] = "秃鹫山丘",
		["West of the island, the Vilebranch scalpers hold the temples of {area:1884} and {area:1917}. Slagtree's tools lie at one of the temples."] = "在小岛西边，邪枝割颅者占据着{area:1884}和{area:1917}的神殿。斯拉提的工具在其中一座神殿里。",
		["for {npc:6986} in {zone:1454}, around level 50"] = "交给{zone:1454}的{npc:6986}，大约50级时",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "交给{zone:1458}的{npc:7825}，大约50级时",
		["grind on {npc:5982} at the northern hills, {zone:1419}"] = "在{zone:1419}北部山丘刷{npc:5982}",
		["{area:348} well"] = "{area:348}水井",
		["{item:8704}, a rare drop"] = "{item:8704}，稀有掉落",
		["{npc:14731}'s lunch"] = "{npc:14731}的午餐",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}，在{area:354}顶上",
		["{npc:6741}: for {zone:1456}, around level 50"] = "{npc:6741}：交给{zone:1456}，大约50级时",
		["{npc:7801}'s camp"] = "{npc:7801}的营地",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}，在{object:36126}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "向东北回到{npc:8420}那里。",
		["Back to {area:1099}"] = "返回{area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "回到神殿的{npc:11548}那里；待在{area:3137}守卫的西边。",
		["Back to {object:3202}"] = "返回{object:3202}",
		["Continue south to {area:35}. {npc:7406} has his workshop on the upper ring of the bay."] = "继续向南前往{area:35}。{npc:7406}的工作室在海湾的上层环道上。",
		["Fly from {area:1237} to {zone:1454}, walk out of the main gate to the zeppelin towers and take the zeppelin to {object:3202}."] = "从{area:1237}飞往{zone:1454}，从正门走到飞艇塔，乘飞艇前往{object:3202}。",
		["Fly to the {area:1497}"] = "飞往{area:1497}",
		["Fly to {area:1638}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and {npc:4046} are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "飞往{area:1638}；它在前往{area:1099}的路上。还没有那里的飞行路线？飞往{area:378}，再向西骑马穿过{zone:1412}。哈缪尔和{npc:4046}在{area:1639}；德鲁伊和圣骑士在这里训练（{npc:3033}，{npc:246344}）。",
		["Follow the road north to {area:1237}, the Horde camp."] = "沿道路向北前往部落营地{area:1237}。",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "沿道路向南；蜥蜴在丛林中部道路东边的岩石上晒太阳。它们经常掉落碎片。",
		["Frayfeather Hippogryphs"] = "乱羽角鹰兽",
		["From {area:3317}'s flight master, fly to the {area:1497}."] = "从{area:3317}的飞行管理员处飞往{area:1497}。",
		["Highborne and Haldarr satyrs"] = "上层精灵和哈达尔萨特",
		["Ironjaw Basilisks"] = "铁腭蜥蜴",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "留着给{npc:4046}、{npc:8659}和{npc:6522}的货物：你之后会经过{zone:1456}、{zone:1454}和{zone:1458}。",
		["Keep {area:1417} for {npc:7771} in {zone:1446}."] = "留着{area:1417}给{zone:1446}的{npc:7771}。",
		["Keep {npc:8659}'s payment and Ag'tor's {quest:3504}: they go back to {area:1237} on a later visit."] = "留着{npc:8659}的报酬和阿格图的{quest:3504}：之后再去{area:1237}时交还。",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "留着{quest:3444}：{npc:7771}的箱子要之后再来时才能打开。",
		["Only once all three robots are home"] = "仅当三个机器人都回家后",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "沿道路向东离开碎木岗哨。{npc:11548}在道路旁的{area:1235}等候，位于联盟{area:3137}西边几步远：从西边过去，避开艾萨拉哨兵和加罗迪努斯（精英）。",
		["Ride into {zone:1447}"] = "骑马进入{zone:1447}",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}."] = "向东北骑往{area:1227}上方悬崖上的地精营地。",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "向西北骑往{area:1108}；{npc:14637}在码头上等候。",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "沿道路向南骑往{area:1938}；{npc:7771}在旁边扎营。从这里向西的道路通往{zone:1449}，下一个指南从那里开始。",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "向西南骑往废墟。四块石板散落在废墟中，由恶鞭纳迦看守；任何恶鞭海妖或恶鞭侍从都可能携带{npc:8420}的符文。",
		["Ride west back to {area:1237}."] = "向西骑回{area:1237}。",
		["Sea elementals"] = "海元素",
		["Sprite Darters"] = "小精龙",
		["Take the zeppelin back to {zone:1454}."] = "乘飞艇返回{zone:1454}。",
		["Take the zeppelin to {zone:1454} from the tower outside the {zone:1458}, then fly to {area:431}."] = "在{zone:1458}外的塔上乘飞艇前往{zone:1454}，然后飞往{area:431}。",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "上层精灵的幽灵在神殿正北的废墟里出没；哈达尔萨特在更北一点的地方扎营。",
		["The Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "大地行者和峭壁巨人在码头北边的山丘上游荡。先用{item:18904}电击每一个：被缩小后，它们就不再是精英。每个被电击的巨人都会掉落残渣；也对它的尸体使用灵魂精华容器。",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock."] = "海元素和巨型海元素沿着码头周围的海岸漂荡。",
		["The Thunderhead Hippogryphs fly over the hills just south of {area:1237}."] = "雷首角鹰兽在{area:1237}正南的山丘上空飞翔。",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "血精灵的营地就在{npc:8420}南边。他的四件设备在营地周围的箱子里。",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "精灵龙在营地正西的树林里飞来飞去。对你杀死的每一只使用容器。",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "角鹰兽在营地西南的山丘上筑巢。杀死一只，然后对它的尸体使用灵魂精华容器。",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "树人在营地和{zone:1444}中部之间的林间道路上游荡；数量很少，所以沿着小路找。",
		["The {object:2076} beside {npc:2519}"] = "{npc:2519}旁边的{object:2076}",
		["To {object:3202}"] = "前往{object:3202}",
		["Undamaged Hippogryph Feathers"] = "完好无损的角鹰兽羽毛",
		["Wandering Forest Walkers"] = "森林漫游者",
		["Xylem's tower stands on the cliff just north of {area:1237}; the path winds up its north side."] = "克希雷姆的塔建在{area:1237}正北的悬崖上；小路沿塔的北侧蜿蜒而上。",
		["Zapped giants"] = "被电击的巨人",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}，在暗巷区",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}：熊在{zone:1448}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825}站在{object:36082}。",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "{npc:7876}要的焦油和匹斯特苏格要的样本都来自{zone:1449}。",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在双足飞龙管理员旁边",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}，在营地东缘：没有经验，只能传送到克希雷姆的法师塔",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}，在{object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761}在下一个指南中收集；{npc:4046}的报酬之后交还给{npc:8587}。",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back north-east to {area:251}."] = "向东北回到{area:251}。",
		["Back to {area:2268}"] = "返回{area:2268}",
		["Black Broodlings"] = "黑色小龙",
		["Black Broodlings nest in the hills just east of {area:251}. Use {npc:10267}'s {item:12284} on a broodling when it is almost dead to capture its essence."] = "黑色小龙在{area:251}正东的山丘上筑巢。在小龙快死时对它使用{npc:10267}的{item:12284}来捕获它的精华。",
		["Bloodpetal Flayers"] = "血瓣花掠夺者",
		["Bridge into {area:254}"] = "通往{area:254}的桥",
		["Cross the south of the crater to the pylon on the western cliffs."] = "穿过环形山南部，前往西边悬崖上的水晶塔。",
		["Darrowshire Spirits"] = "达隆郡居民的灵魂",
		["Eastern Pylon"] = "东部水晶塔",
		["Escort {npc:9999}"] = "护送{npc:9999}",
		["Fly to {area:1637} and train before the {object:3202} zeppelin: the {zone:1458} stop later in this guide has no Hunter or Shaman trainer."] = "在乘坐前往{object:3202}的飞艇前，先飞往{area:1637}训练：本指南稍后经过的{zone:1458}没有猎人和萨满祭司训练师。",
		["Fly to {area:1637}, take the zeppelin to {object:3202} and fly from there to {area:340}, built into the cliffs on the {zone:1418}' west edge."] = "飞往{area:1637}，乘飞艇前往{object:3202}，再从那里飞往{zone:1418}西缘依悬崖而建的{area:340}。",
		["Fly to {area:1638} and train with {npc:3033} on {area:1639}, then fly to {area:1637} for the {object:3202} zeppelin."] = "飞往{area:1638}，在{area:1639}找{npc:3033}训练，然后飞往{area:1637}乘坐前往{object:3202}的飞艇。",
		["Fly to {area:340}"] = "飞往{area:340}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "沿悬崖向南前往火腹食人魔的山丘{quest:3821}。{npc:9136}的遗骸在山脚下。",
		["Follow the road east through the {zone:1422} and across the river into the {zone:1423}; leave it north for {area:2627}, the ruined town in the north-west. {npc:12384} sits in a hut at its edge."] = "沿道路向东穿过{zone:1422}，过河进入{zone:1423}；然后离开道路向北前往西北的废墟城镇{area:2627}。{npc:12384}坐在城镇边缘的一间小屋里。",
		["Free Darrowshire Spirits: talk to them"] = "释放达隆郡居民的灵魂：和它们交谈",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "从现在起，捡起路过的每一块能量水晶（蓝色、绿色、红色、黄色）和每一堆{quest:3761}：总共25份土壤，20份给哈缪尔，5份给匹斯特苏格。",
		["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "从{area:1938}向西骑到蜿蜒下降进入{zone:1449}的长坡道，然后沿着环形山的北壁前往{area:541}，那是建在悬崖洞穴里的营地。这里的所有人都是中立的。",
		["Gorillas"] = "猩猩",
		["Into the {zone:1427}"] = "进入{zone:1427}",
		["Into {zone:1449}"] = "进入{zone:1449}",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "留着诱饵：{npc:9684}是56级，第二圈会经过它的巢穴。",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "留着{npc:10267}的信：{quest:4808}在{zone:1452}的{area:2255}。",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "留着{npc:9118}的{quest:4147}和{npc:8737}的信，在之后的指南中使用。",
		["Keep {quest:5152}: Marlene lives at {area:197} in the {zone:1422}."] = "留着{quest:5152}：玛莱恩住在{zone:1422}的{area:197}。",
		["Lar'korwi Mates"] = "拉克维的配偶",
		["Lashers and Threshers"] = "鞭笞者和猛击者",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "带{npc:9999}向北前往{area:541}。他晕倒时，对他使用{item:11804}把他叫醒。",
		["Leave the {zone:1458} and ride east along the road through {zone:1420} to the {area:152}, the Forsaken fort on the border."] = "离开{zone:1458}，沿道路向东穿过{zone:1420}，前往边境上的被遗忘者要塞{area:152}。",
		["North of Torwa, a dead Threshadon lies by the water."] = "在托尔瓦北边，一头死去的蛇颈龙躺在水边。",
		["Northern Pylon"] = "北部水晶塔",
		["Out of the refuge"] = "离开避难所",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "匹斯特苏格的下一个任务需要击败精英首领{npc:10041}。跳过它。",
		["Power Crystals and soil"] = "能量水晶和土壤",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "沿环形山东侧骑下去，前往东边悬崖上的水晶塔。",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "向东骑往{area:537}，爬上去，在接近山顶的熔岩口使用{npc:10541}，然后向西骑回{npc:10302}那里。",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "沿东侧向北骑行。血瓣花鞭笞者和血瓣花猛击者占满了丛林。",
		["Ride north back to {area:541}."] = "向北骑回{area:541}。",
		["Ride south back to the road and follow it east across the whole zone to {area:2268}."] = "向南骑回道路，沿路向东穿过整个地区前往{area:2268}。",
		["Ride south-west along the western cliffs. {npc:9167} fly over the west side, and Bloodpetal Trappers grow in the same jungle."] = "沿西边的悬崖向西南骑行。{npc:9167}在西侧上空飞翔，血瓣花捕兽者生长在同一片丛林里。",
		["Ride south-west to {area:537}, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot."] = "向西南骑往环形山中央的火山{area:537}。血瓣花掠夺者生长在山脚周围。",
		["Ride west to the dig site. {npc:7039} golems (53) stomp around it and drop the shards often; the {quest:4296} stands in its middle among the Thaurissan dwarves. Copy it."] = "向西骑往挖掘场。{npc:7039}傀儡（53级）在周围走动，经常掉落碎片；{quest:4296}立在挖掘场中央的索瑞森矮人中间。抄录它。",
		["South of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales {npc:9998} wants. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon."] = "在温泉南边，剑龙在吃草，恐龙骨头从它们身上掉落或散落在地上；附近的双帆龙携带{npc:9998}想要的鳞片。暴掠龙在西南成群捕猎：它们的爪子是给{npc:8659}的，偶尔会有一只携带被撕破的日记（稀有掉落：只有拿到了才接它的任务）。避开57级的剑龙格鲁夫。",
		["Stegodons and ravasaurs"] = "剑龙和暴掠龙",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "从德灵顿旁边的箱子里拿一个{object:176092}，用于{quest:5096}，在回程时完成。装备{quest:5401}：只有佩戴它时才会掉落天灾石。",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south across the gorge to the long bridge into {area:254}. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "从{area:340}西侧的山口进入{zone:1427}，然后向南穿过峡谷，走上通往{area:254}的长桥。进去后沿着铁链走道往下走，从南边的出口离开；别走通往地下城传送门的路。",
		["Termite mounds"] = "白蚁丘",
		["Thaurissan dig site"] = "索瑞森挖掘场",
		["The Gorishi hive"] = "格里什虫巢",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "拉克维的配偶在{npc:9619}西北的丛林里潜行。",
		["The Large Termite Mounds stand all over the hills east of {area:2627}. Use the {item:15042} on each mound you pass."] = "大白蚁丘遍布{area:2627}东边的山丘。对路过的每个白蚁丘使用{item:15042}。",
		["The book lies in the ruined inn of {area:2627}."] = "收据册在{area:2627}被毁的旅店里。",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "水晶簇遍布整个环形山，{area:537}周围很多。每种颜色多拿几块给水晶塔用。",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "洋娃娃的脑袋和两半身体在{npc:10926}周围的房子里；在背包里把它们拼起来。",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "考察队的食物箱在东部丛林一个废弃的营地里。",
		["The expedition's lost equipment lies in the south-west jungle."] = "考察队丢失的研究设备在西南丛林里。",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "猩猩住在东北的高地上。别进入最深的洞穴：{npc:9622}住在那里。",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "从山里出来就在{area:252}旁边，那里满是55-57级的兽人。沿北边悬崖的道路向东，前往部落营地{area:251}。",
		["The next guide starts here, at the chapel's flight master."] = "下一个指南从这里的教堂飞行管理员处开始。",
		["The pylon stands on the slope east of the refuge."] = "水晶塔在避难所东边的山坡上。",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "破碎的木筏在东南湖泊的岸边；小背包就在旁边的水里。",
		["The silithid hive fills the south of the crater. Gorishi wasps and workers drop the scent gland; use the Scraping Vial on the egg mass inside the first chamber. The Hive Queen at the bottom is an elite boss: stay out of her chamber. {npc:9166} nest on the cliffs above the hive; their scales are for {npc:9998}."] = "异种蝎的巢穴占据着环形山南部。格里什异种蝎和格里什工蝎掉落格里什信息素；在第一个洞室里对卵块使用采集瓶。底部的格里什皇后是精英首领：别进入她的洞室。{npc:9166}在虫巢上方的悬崖上筑巢；它们的鳞片是给{npc:9998}的。",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "焦油池就在避难所正南。焦油兽、焦油潜伏者和焦油爬行者掉落{item:11834}。",
		["The wooden sign beside {npc:9997}"] = "{npc:9997}旁边的木牌",
		["Theodora's next errand goes to Lotwil east of town and then into {area:1584}: skip it."] = "塞朵拉的下一个差事要去镇东边找鲁特维尔，然后进入{area:1584}：跳过它。",
		["Theodora's quest in {area:340} needs level 52. The Tar Lurkers and Tar Lords just south of the refuge are the closest camp."] = "塞朵拉在{area:340}的任务需要52级。避难所正南的焦油潜伏者和焦油兽王是最近的刷怪点。",
		["Use the Mangled Journal to start it"] = "使用被撕破的日记开始任务",
		["Western Pylon"] = "西部水晶塔",
		["Western jungle"] = "西部丛林",
		["With {npc:11063}'s quest in your log, slain Scourge sometimes leave a {npc:11064}; talk to it to free it. Kill undead on the ride south-west to {area:2262}."] = "任务日志里有{npc:11063}的任务时，被杀死的天灾军团有时会留下一个{npc:11064}；和它交谈来释放它。在向西南骑往{area:2262}的路上击杀亡灵。",
		["grind on Tar Lurkers at {area:538}, {zone:1449}"] = "在{zone:1449}的{area:538}刷焦油潜伏者",
		["{item:11116}, a rare drop"] = "{item:11116}，稀有掉落",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302}让你去找{zone:1452}的{npc:9298}：留着它。",
		["{npc:10302} the goblin sits at {area:543}, just east of the pylon."] = "地精{npc:10302}坐在水晶塔正东的{area:543}。",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}，在{object:36078}的蝙蝠管理员旁边",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "{npc:10926}的鬼魂站在西南边{area:2262}的废墟里。",
		["{npc:12250} lurks just west of {area:2262}."] = "{npc:12250}潜伏在{area:2262}正西。",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}，在{object:36073}",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}，在炼金房：瓶子之后在{zone:1447}装满",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}，在洞穴深处",
		["{npc:9618}, just outside"] = "{npc:9618}，就在外面",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619}在环形山的东南角扎营。",
		["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "{npc:9619}接下来要东北洞穴里{npc:9622}的毛皮：跳过它。",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "{npc:9623}接着要一个{item:10561}，这是{skill:202}物品。除非你有，否则跳过。",
		["{npc:9623}, the robot on the plateau"] = "{npc:9623}，高地上的机器人",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "{npc:9684}的巢穴就在水晶塔正南。在那里使用{npc:9619}的诱饵；{npc:9684}是56级，攻击很重，所以满血再开始。",
		["{npc:9998}, at the entrance"] = "{npc:9998}，在入口",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}，在避难所入口",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999}坐在山脊上，迷路了，筋疲力尽。",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822}在{quest:3821}的洞穴和矿道里走动；如果他不在，就清理入口周围的食人魔，直到他回来。",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back at {area:1762}, the Deadwood furbolgs (53-54) are close to the tunnel and every kill raises your Timbermaw reputation."] = "回到{area:1762}，死木熊怪（53-54级）就在隧道附近，每杀一个都会提升你的木喉要塞声望。",
		["Back north to {area:1763}. Fill {npc:10922}'s canteen at the corrupted moonwell in the middle of the southern camp."] = "向北回到{area:1763}。在南部营地中央被腐化的月亮井装满{npc:10922}的水壶。",
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "德灵顿的哨塔、范蒂丝的瘟疫之锅和{npc:11615}的木桶留到之后再来时完成：留着它们。",
		["Diseased Grizzlies"] = "生病的灰熊",
		["Diseased Wolves"] = "生病的狼",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "在血毒岗哨东边，是{npc:9878}和热能恐兽游荡的坑洼山谷。每种各杀两只，然后走到三个邪能水坑的每一个那里。",
		["Fly to the {area:1497}"] = "飞往{area:1497}",
		["Follow the road north-east to {area:1767}. The Warpwood Moss Flayers and Shredders on the east side of the woods each carry a {item:11503}; Angerclaw Grizzlies and Felpaw Ravagers roam the same woods for Talo."] = "沿道路向东北前往{area:1767}。树林东侧的曲木食苔者和曲木撕裂者各带着一块{item:11503}；怒爪灰熊和魔爪掠夺者在同一片树林里游荡，是塔罗要的。",
		["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "沿道路向西北。{area:1763}南部那口被腐化的月亮井周围被暗影议会的加德纳尔祭司、加德纳尔精兵、卫兵和恶犬占据。",
		["From {area:2268}'s flight master, fly to the {area:1497}."] = "从{area:2268}的飞行管理员处飞往{area:1497}。",
		["He camps by the {area:202}, south-east of {area:200}."] = "他在{area:200}东南的{area:202}旁扎营。",
		["Jadefire moonwell"] = "碧火月亮井",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "留着树枝：{npc:5770}在{zone:1456}。",
		["Keep the parcel: {npc:10781} is in the {area:1497}."] = "留着包裹：{npc:10781}在{area:1497}。",
		["Keep {quest:5142}: Pamela is in {area:2262}, visited again later."] = "留着{quest:5142}：帕米拉在{area:2262}，之后会再去。",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "留着{quest:5158}：{npc:5901}在{zone:1413}。",
		["Keep {quest:8465} for {zone:1452}."] = "留着{quest:8465}去{zone:1452}。",
		["Knights and magi work the {area:192}; the medics and hunters camp south of it."] = "血色骑士和血色占星师在{area:192}干活；血色医护员和血色猎人在它南边扎营。",
		["Leave the {area:1497} and ride east along the road through {zone:1420}, past the {area:152}. Felstone Farm is the first farm along the road; {npc:10778} waits in the house."] = "离开{area:1497}，沿道路向东穿过{zone:1420}，经过{area:152}。费尔斯通农场是路边的第一座农场；{npc:10778}在房子里等候。",
		["Northern crater"] = "北部水坑",
		["Only if a {item:13140} dropped: use it to start the quest, then free {npc:11018} in her cage in {area:1770}, the cave at the north end of {area:1763}, and escort her out."] = "仅当掉落了{item:13140}时：使用它开始任务，然后到{area:1763}北端的洞穴{area:1770}里，把笼子里的{npc:11018}救出来，并护送她出去。",
		["Only if you rescued {npc:11018}: the succubus {npc:9518} waits in the middle of {area:1763}, beside the {npc:11020}."] = "仅当你救出了{npc:11018}时：魅魔{npc:9518}在{area:1763}中部，就在{npc:11020}旁边等候。",
		["Only with 5 Deadwood Headdress Feathers"] = "仅当你有5根死木头饰羽毛时",
		["Radley and Durgen"] = "莱德雷和杜尔根",
		["Ride back south past {area:1763} to the corrupted moonwell of the Jadefire satyrs and fill {npc:9996}'s flasket there."] = "向南骑过{area:1763}，前往碧火萨特那口被腐化的月亮井，在那里装满{npc:9996}的小瓶。",
		["Ride back south-east to the Sanctuary."] = "向东南骑回翡翠圣地。",
		["Ride back to the {area:1497}, take the zeppelin to {zone:1454} and fly to {area:431}. Follow the road west out of Splintertree and take the fork north into {zone:1448}."] = "骑回{area:1497}，乘飞艇前往{zone:1454}，飞往{area:431}。沿道路向西离开碎木岗哨，在岔路口向北进入{zone:1448}。",
		["Ride north along the eastern hills; {npc:1855} lives in a small house by the {area:2619}, at the border with the {zone:1423}."] = "沿东边的山丘向北骑行；{npc:1855}住在{area:2619}旁的一间小房子里，就在与{zone:1423}的交界处。",
		["Ride north up the road again."] = "再次沿道路向北骑行。",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "向西北骑进安多哈尔。{npc:10667}在城镇西侧被毁的旅店里等候；里面的骷髅是54-57级，所以沿着边缘走。",
		["Ride south past the {area:202} to {area:197}; {npc:10927}'s house stands by the road, and {npc:10936}'s monument is in the graveyard behind it. Kill the Diseased Wolves you meet in the fields on the way."] = "向南骑过{area:202}前往{area:197}；{npc:10927}的房子在路旁，{npc:10936}的纪念碑在房后的墓地里。路上把在田野里遇到的生病的狼都杀掉。",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "向西南骑过费尔斯通农场，沿道路向西回到{area:152}。",
		["Ride the road south through {zone:1448} to the Sanctuary."] = "沿道路向南穿过{zone:1448}前往翡翠圣地。",
		["Ride west to the {area:192}; {npc:11610} hides on the hill north-east of it."] = "向西骑往{area:192}；{npc:11610}躲在它东北的山上。",
		["Ror stands at the far south end of {area:1761}."] = "洛尔站在{area:1761}最南端。",
		["Scarlet Crusade"] = "血色十字军",
		["Scarlet forward camp"] = "血色十字军前线营地",
		["Southern crater"] = "南部水坑",
		["Southern {area:1763}"] = "{area:1763}南部",
		["Take the kitten to the same moonwell and release it there; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "把小猫带到同一口月亮井并在那里放出它；它变成{npc:10042}后，把它带回{npc:9996}那里，点击它交给她。",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "达隆郡的历史就在安多哈尔市政厅里的发霉的书籍中间；一本本打开，直到找到正确的那本。",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "隧道正西的死木熊怪村庄。{npc:9462}（56级）站在它们中间。{npc:11557}是一个友善的熊怪，坐在村庄北端。",
		["The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your {area:1769} reputation; keep the headdress feathers."] = "死木熊怪的村庄就在翡翠圣地正南。每杀一个死木熊怪也会提升你在{area:1769}的声望；留着死木头饰羽毛。",
		["The Horde camp just north of {area:1763}."] = "{area:1763}正北的部落营地。",
		["The Jadefire moonwell"] = "碧火月亮井",
		["The Scarlet Crusade's tents stand between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner."] = "血色十字军的帐篷在{area:199}和{area:200}之间。用{object:176092}点燃指挥帐篷，并插上天灾战旗。",
		["The bears roam the hills north and east of the {area:202}."] = "熊在{area:202}北边和东边的山丘上游荡。",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "日记在农舍里，柜子在屋里，厕所在屋后。一个{npc:10816}带着厕所钥匙；打开厕所时{npc:10836}会出来，他带着柜子钥匙。",
		["The druids' camp is just past the border."] = "德鲁伊的营地就在边界过去一点。",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "道路的尽头是{npc:15395}，就在遥远东北的{area:1769}隧道外。",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east."] = "狼在安多哈尔、{area:200}和{area:202}之间的田野里游荡。向东骑回去的路上把它们杀完。",
		["The {area:1763} moonwell"] = "{area:1763}的月亮井",
		["Through {area:1769}"] = "穿过{area:1769}",
		["To {zone:1448}"] = "前往{zone:1448}",
		["Walk into the {area:1769} tunnel beside {npc:15395} and never attack the Timbermaw furbolgs inside. The tunnel opens into {zone:1452}; follow the road east to {area:2255}, the goblin town where the next guide starts."] = "走进{npc:15395}旁边的{area:1769}隧道，千万别攻击里面的木喉熊怪。隧道出口在{zone:1452}；沿道路向东前往地精城镇{area:2255}，下一个指南从那里开始。",
		["Western crater"] = "西部水坑",
		["grind on Deadwood Avengers at {area:1762}, {zone:1448}"] = "在{zone:1448}的{area:1762}刷死木复仇者",
		["grind on Scarlet Knights at {area:192}, {zone:1422}"] = "在{zone:1422}的{area:192}刷血色骑士",
		["{area:190}'s Scarlets are level 58-60. Ride in to the high point marked on your map, look over the town, and get out."] = "{area:190}的血色十字军是58-60级。骑到地图上标记的高处，俯瞰城镇，然后离开。",
		["{area:200} farmhouse"] = "{area:200}的农舍",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}：枭兽在{zone:1452}",
		["{npc:10840}, at the graveyard's south end"] = "{npc:10840}，在墓地南端",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}，在营地南缘",
		["{npc:11557}: keep 30 {quest:6031} for him; he trades only at Neutral with the Timbermaw"] = "{npc:11557}：为他留30块{quest:6031}；他只在木喉要塞声望达到中立时才交易",
		["{npc:11558}, at the tunnel mouth"] = "{npc:11558}，在隧道口",
		["{npc:11610}'s last task needs level 53. The Scarlet Knights and Magi (54-55) working the lumber camp just south-west of her are the closest camp."] = "{npc:11610}的最后一个任务需要53级。在她西南不远的伐木场干活的血色骑士和血色占星师（54-55级）是最近的刷怪点。",
		["{npc:11613} stands east of the lumber camp; {npc:11611} guards the road north-east of {npc:11610}, toward {area:190}."] = "{npc:11613}站在伐木场东边；{npc:11611}守着{npc:11610}东北、通往{area:190}的道路。",
		["{npc:1855}'s hunts are in the {zone:1423}: keep them for later."] = "{npc:1855}的狩猎任务在{zone:1423}：留到之后。",
		["{npc:9529}, just west of the camp"] = "{npc:9529}，在营地正西",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}，在翡翠圣地西侧",
		["{npc:9996}'s kitten"] = "{npc:9996}的小猫",
		["{object:175894}, beside the house"] = "{object:175894}，在房子旁边",
		["{quest:5210} goes to {area:2268}: keep it for later."] = "{quest:5210}要前往{area:2268}：留到之后。",
		["{quest:8470}, a rare drop"] = "{quest:8470}，稀有掉落",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Any Winterfall furbolg can carry the beads; the camps just south of {npc:11556} are the closest."] = "任何冬泉熊怪都可能携带冬泉灵魂珠串；{npc:11556}正南的营地最近。",
		["Back at {area:1099}."] = "回到{area:1099}。",
		["Back to {area:2255}"] = "返回{area:2255}",
		["Chillwind chimaeras"] = "冰风奇美拉",
		["Fly to {area:1099}"] = "飞往{area:1099}",
		["Fly to {area:1637}"] = "飞往{area:1637}",
		["Fly to {area:1638}"] = "飞往{area:1638}",
		["From Krakle in Un'Goro"] = "来自安戈洛的克拉兰克",
		["Frostfire Winterfall camp"] = "冰火温泉的冬泉熊怪营地",
		["Frostfire Winterfall camps"] = "冰火温泉的冬泉熊怪营地",
		["Gregor's and Harlo's quests lead to other zones: keep them."] = "格雷戈和哈鲁的任务会把你带到其他地区：留着它们。",
		["Grind to 55"] = "刷到55级",
		["He stands on {area:1641}. Each donation wants cloth from your bags; hand them in when you have it, later in the route."] = "他站在{area:1641}。每次捐献都需要你背包里的布料；有了布料再交，在路线后面。",
		["Ice Thistle yetis"] = "冰蓟雪人",
		["In the {object:172958}."] = "在{object:172958}。",
		["In the {object:172961}."] = "在{object:172961}。",
		["Linken's letter"] = "林克的信",
		["Matriarchs and Patriarchs hit hard: pull them one at a time."] = "冰蓟雪人女王和冰蓟雪人王攻击很重：一次引一只。",
		["Pathfinders, Den Watchers and Totemics share the furbolg camps around the hot springs; Ragged Owlbeasts roam the slopes between them. Kill Totemics first. Save every {item:14047} you loot for Meilosh."] = "冬泉探路者、冬泉巢穴守卫和冬泉图腾师共处于温泉周围的熊怪营地；蓬毛枭兽在营地之间的山坡上游荡。先杀冬泉图腾师。把拾取到的每一块{item:14047}都留给梅罗什。",
		["Pristine Yeti Horns"] = "完美的雪人角",
		["Raging Owlbeasts"] = "狂暴的枭兽",
		["Ride back west to {area:2246}."] = "向西骑回{area:2246}。",
		["Ride east, then south down {area:2249}. The Frostmaul giants there are elite level 59: keep to the middle and keep moving. The strange source is at the mouth of {area:2256}, at the south end."] = "向东骑行，然后向南下到{area:2249}。那里的霜槌巨人是59级精英：走在中间，保持移动。奇怪的源头在南端{area:2256}的入口处。",
		["Ride west along the road past {area:2251}; Raging Owlbeasts roam the hills north of it."] = "沿道路向西经过{area:2251}；狂暴的枭兽在它北边的山丘上游荡。",
		["The chimaeras roam the snowfields south and west of {area:2255}. Stay clear of {area:2245}'s cave: its blue dragonkin are elite."] = "奇美拉在{area:2255}南边和西边的雪原上游荡。远离{area:2245}的洞穴：里面的蓝龙龙人都是精英。",
		["The furbolg village fills the valley north-east of {area:2255}. Kill Shamans first; they heal. {npc:10738} in the cave at the back is elite: stay out."] = "熊怪村庄占满了{area:2255}东北的山谷。先杀冬泉萨满祭司；他们会治疗。后面洞穴里的{npc:10738}是精英：别进去。",
		["The yeti hills start just south-east of {area:2255}. Every yeti drops fur; only Matriarchs and Patriarchs drop horns, so keep those for after the turn-in."] = "雪人的山丘就在{area:2255}东南不远处开始。每个雪人都会掉落毛皮；只有冰蓟雪人女王和冰蓟雪人王掉落角，所以交还后再去打它们。",
		["Umi's third prank targets goblins in {area:976} and Un'Goro: keep it for later."] = "乌米的第三个恶作剧针对的是{area:976}和安戈洛环形山的地精：留到之后。",
		["grind on {npc:7440} at {area:2244}, {zone:1452}"] = "在{zone:1452}的{area:2244}刷{npc:7440}",
		["{area:2255} is the goblin town on the east side of the valley."] = "{area:2255}是山谷东侧的地精城镇。",
		["{item:12771}, a rare drop from the Winterfall furbolgs"] = "{item:12771}，冬泉熊怪的稀有掉落",
		["{npc:10307}, beside him"] = "{npc:10307}，在他旁边",
		["{npc:11118}: the last guide binds here, so this usually ticks at once"] = "{npc:11118}：上一份指南在这里绑定炉石，所以这一步通常会立即完成",
		["{npc:11556} stands by the {zone:1452} exit of {area:1769}'s tunnel, north of the hot springs."] = "{npc:11556}站在{area:1769}隧道的{zone:1452}出口旁，在温泉北边。",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{area:1639}的{npc:3033}；{npc:246344}",
		["{npc:7775}, a dwarf, camps in the {area:1137} north-west of {area:1099}; he has the elixir."] = "矮人{npc:7775}在{area:1099}西北的{area:1137}扎营；他有药剂。",
		["{npc:9087} buys {item:11040} grown from your {quest:3761}."] = "{npc:9087}收购用你的{quest:3761}种出来的{item:11040}。",
		["{npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "{npc:9298}在山谷西部{area:2246}的热气腾腾的水池间扎营。",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123}在{zone:1450}等候：留到之后。",
		["{quest:3909} comes from {npc:7775} in {zone:1444}, later in this guide."] = "{quest:3909}来自{zone:1444}的{npc:7775}，在本指南稍后。",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084}要在{zone:1448}的{object:176091}交还，留到之后那一趟。",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}，冬泉熊怪的稀有掉落",
} end)()
t.guides["forever/horde/50-60/04-azshara"] = (function() return {
