		["Mark {npc:10904} with the {item:12815}"] = "用{item:12815}标记{npc:10904}",
		["Mark {npc:10905} with the {item:12815}"] = "用{item:12815}标记{npc:10905}",
		["North to the lumber camp; set the termite barrel down in the middle of the mill."] = "向北前往伐木场；把白蚁桶放在锯木厂中央。",
		["Ride east across the plaguelands to the chapel."] = "向东骑过瘟疫之地前往教堂。",
		["Ride east along the road to the {area:152} on the border."] = "沿道路向东骑往边境上的{area:152}。",
		["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "向东骑往{area:2619}旁{npc:1855}的小屋，听他把话说完。",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "向东北骑往{area:3077}；你从旁边的山口离开{zone:1451}。",
		["Ride north-east to {area:3447}."] = "向东北骑往{area:3447}。",
		["Ride north-west to {npc:1855}'s hut."] = "向西北骑往{npc:1855}的小屋。",
		["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "向南骑进安多哈尔。{npc:10667}在城镇西侧被毁的旅店里等候。拿着{item:12815}站在四座塔的每一个门口来标记它；沿城镇边缘走。在镇中央的粮仓旁使用{item:12627}引出时光寄生虫。",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "向东南骑往安戈洛悬崖下的{area:3447}。",
		["Ride south-west to the ruins of {area:2738}. The {object:179565} for {npc:11801} sits inside one of the ruined houses."] = "向西南骑往{area:2738}的废墟。给{npc:11801}的{object:179565}在其中一座毁坏的房子里。",
		["Ride south-west to {npc:10667} in Andorhal."] = "向西南骑往安多哈尔的{npc:10667}那里。",
		["Ride to {area:2262} in the south-west; {npc:10926} plays among the houses. {npc:11886} lurks in the {area:2261}, the crypt just west of the town."] = "骑往西南的{area:2262}；{npc:10926}在房子间玩耍。{npc:11886}潜伏在城镇正西的墓穴{area:2261}里。",
		["Ride west to the Horde camp north of {area:2744}."] = "向西骑往{area:2744}北边的部落营地。",
		["Ride west to the walled hold in the middle of the desert."] = "向西骑往沙漠中央有城墙环绕的塞纳里奥要塞。",
		["Scourge Champions"] = "天灾勇士",
		["Scourge Champions roam the {area:2270}, north of the chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants."] = "天灾勇士在教堂北边的{area:2270}游荡。在你杀死的每一个身上晃一晃{npc:11063}的{item:13156}：产生共鸣的头骨就是他要的。",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "水晶尘喷泉在南部沙漠各处喷发。走进喷泉留下的水晶尘，把它带到吉里卡营地的部落水晶尘提取器；战斗或骑上坐骑都会让它掉落。",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "石鞭掠夺者和石行蜘蛛在吉里卡营地西南的沙丘上游荡。",
		["Take the zeppelin from the tower outside {area:1637} to {zone:1420} and ride into the {zone:1458}. Lady Sylvanas holds the {object:36126}."] = "在{area:1637}外的塔上乘飞艇前往{zone:1420}，再骑进{zone:1458}。希尔瓦娜斯·风行者在{object:36126}。",
		["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too."] = "发光的石板碎片散落在遥远西北的暮光营地周围；那里的灰尘风暴和沙漠奔行者也会掉落碎片。",
		["The libram lies further north, on the way to {area:190}."] = "圣契在更北边，通往{area:190}的路上。",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "从安戈洛环形山出来的山口通往{area:3077}，那是{zone:1451}东北部的墓地。{npc:13220}站在坟墓之间。",
		["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "诺格的背包在遥远南方的山里，过了铜须营地。精英蝎子死亡弯钩在附近巡逻：趁它走开时拿走背包。",
		["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "盾牌在{npc:1855}小屋南边的{area:201}。",
		["The spare texts from the cultists"] = "信徒身上多出来的密文信",
		["Through the pass and east along the northern cliffs to {area:541}. {npc:8737} stands by the cave; {npc:9117} is inside it."] = "穿过山口，沿北边的悬崖向东前往{area:541}。{npc:8737}站在洞穴旁；{npc:9117}在洞里。",
		["Twilight Vanguard"] = "暮光先锋军营地",
		["Use {npc:10980} on {npc:10977}"] = "对{npc:10977}使用{npc:10980}",
		["West to the {area:152}. The next guide starts in the {zone:1458}, a short ride west."] = "向西前往{area:152}。下一个指南从西边不远的{zone:1458}开始。",
		["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "{npc:10667}的达隆郡之战最后要对付精英。跳过它。",
		["{npc:10778}'s farm is the first one east of the {area:152}. Jabbering Ghouls on the farm carry the other half of her charm; {npc:11075} guards the cauldron in the field."] = "{npc:10778}的农场是{area:152}东边的第一座农场。农场上的{npc:10801}携带她护身符的另一半；{npc:11075}守着田里的瘟疫之锅。",
		["{npc:10926} and the {area:2261}"] = "{npc:10926}和{area:2261}",
		["{npc:10926}'s own errand is not on this route. Skip it."] = "{npc:10926}自己的差事不在本路线上。跳过它。",
		["{npc:11803} walks the Vanguard camp in the far south-west. Every cultist here drops Encrypted Twilight Texts, quest or not: collect twenty, ten for {npc:15306} and ten for Ortell."] = "{npc:11803}在遥远西南的暮光先锋军营地里走动。这里的每个信徒都会掉落暮光密文信，不管你有没有任务：收集二十份，十份给{npc:15306}，十份给奥泰尔。",
		["{npc:11804} stands in the outpost west of {area:3425}. Top your Encrypted Twilight Texts up to twenty on the cultists here."] = "{npc:11804}站在{area:3425}西边的前哨站里。在这里的信徒身上把暮光密文信补到二十份。",
		["{npc:11878}' errands are not on this route. Skip them."] = "{npc:11878}的差事不在本路线上。跳过它们。",
		["{npc:15193}'s champion holds the {area:2260} farmhouse, north of the {area:2261}."] = "{npc:15193}的勇士占据着{area:2261}北边{area:2260}的农舍。",
		["{npc:15200} holds the camp in the west."] = "{npc:15200}占据着西边的营地。",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}，在要塞西侧",
		["{npc:1855}'s next task, Of Lost Honor, is not on this route. Skip it."] = "{npc:1855}的下一个任务（失落的荣耀）不在本路线上。跳过它。",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "回到木喉隧道，走{zone:1452}出口；{npc:9298}就在出口外的温泉旁扎营。",
		["Back south to the Sanctuary, a short ride."] = "向南回到翡翠圣地，路程很短。",
		["Dungeon instead of grinding"] = "用地下城代替刷怪",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "飞往{area:431}，沿道路向西北离开{zone:1440}进入{zone:1448}。{area:2479}是刚过边界的德鲁伊营地。",
		["From the {zone:1458}, take the zeppelin from the tower outside the city to {zone:1454}."] = "在{zone:1458}城外的塔上乘飞艇前往{zone:1454}。",
		["Grind to 60"] = "刷到60级",
		["In {zone:1454}: fly from {area:2255}"] = "在{zone:1454}：从{area:2255}飞过去",
		["In {zone:1456}: fly from {area:2255}"] = "在{zone:1456}：从{area:2255}飞过去",
		["Only if you carry {quest:5087}: the runners walk the road from {area:1769} toward {area:2244} in small groups; wait by the road near {npc:9298} and kill them as they pass. Each one carries a crate."] = "仅当你有{quest:5087}时：信使们成小群地沿着从{area:1769}到{area:2244}的道路行走；在{npc:9298}附近的路边等候，在他们经过时杀死他们。每个都带着一个箱子。",
		["Only if {npc:9298} gave you {quest:5086}: ride north up the {zone:1448} road to {area:1767}; the {quest:5086} ooze between the trees."] = "仅当{npc:9298}给了你{quest:5086}时：沿{zone:1448}的道路向北骑往{area:1767}；{quest:5086}在树木之间蠕动。",
		["Only with 30 {quest:6031}, and only at Neutral with the Timbermaw: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "仅当你有30块{quest:6031}，且木喉要塞声望达到中立时：沿道路向北前往{area:1769}；{npc:11557}就在入口里面交易。",
		["Optional. Running {area:2279}, {area:2057}, Lower Blackrock Spire or {area:1584} with a group instead of grinding gets you there faster."] = "可选。和队伍一起刷{area:2279}、{area:2057}、黑石塔下层或{area:1584}，代替刷怪能更快到达。",
		["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "可选：有队伍时，用一个55-60级的地下城代替下面的刷怪。",
		["Ride east along the road to {area:2255}."] = "沿道路向东骑往{area:2255}。",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "沿道路向北骑行，经过{area:1763}，前往{area:1997}。",
		["Ride north-west to {area:1763}. The four braziers stand among the Shadow Council's buildings; use the Cleansed Water on each one."] = "向西北骑往{area:1763}。四个火盆立在暗影议会的建筑之间；对每一个使用净化后的水。",
		["South to the Sanctuary once more."] = "再次向南前往翡翠圣地。",
		["The quests run out here. Rabid Shardtooths prowl {area:2249} in southern {zone:1452}, south of the road from {area:2255}."] = "任务到这里就没了。疯狂的碎齿熊在{zone:1452}南部的{area:2249}潜行，位于从{area:2255}出发的道路南边。",
		["The {area:2479}"] = "{area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "穿过木喉隧道前往{zone:1450}。{npc:11939}在{area:2361}的一座房子里读书。",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["grind on {npc:7446} at {area:2249}, {zone:1452}"] = "在{zone:1452}的{area:2249}刷{npc:7446}",
		["{npc:10306}'s next {quest:4741} would bring you back here from {zone:1452}. Skip it."] = "{npc:10306}的下一个任务{quest:4741}会让你从{zone:1452}跑回这里。跳过它。",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "{npc:11801}的魔藤碎片需要{area:2577}。跳过它。",
		["{npc:9116}'s Silver Heart needs an {item:11173} from northern {zone:1448} and a ride back here. Skip it."] = "{npc:9116}的银色之心需要{zone:1448}北部的一个{item:11173}，还要再骑回这里。跳过它。",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "{npc:9298}接下来让你去对付{npc:10738}，他是洞穴里的精英。跳过它。",
		["{npc:9861}, {npc:9860} and {npc:9517} wait at the back of {area:1770}, the cave in {area:1763}'s north. Clear the tunnel as you go."] = "{npc:9861}、{npc:9860}和{npc:9517}在{area:1763}北部的洞穴{area:1770}深处等候。一路清理隧道。",
} end)()
t.guides["forever/horde/orc-troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "{npc:3126}在{area:362}西边的平原上爬行。驯服一只，然后返回{npc:3171}处。",
		["Back at the Den"] = "回到洞穴",
		["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "向东回到{npc:275657}北边的海岸。{npc:275662}和其他恶鞭纳迦占据着{area:370}下方的海滩。猎人：在海滩上驯服一只{npc:3107}。",
		["Back south to {area:362}."] = "向南返回{area:362}。",
		["Back to the Den"] = "返回洞穴",
		["Back to {area:362}."] = "返回{area:362}。",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "回到{object:172960}找{npc:5875}。在那里的召唤法阵上使用{item:7464}，击败虚空行者以束缚它。",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "火刃氏族祭司占据着{quest:827}的洞穴；任何一个都会掉落{item:4871}。{npc:3204}是14级术士，站在洞穴深处，掉落{item:4903}。",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "地狱捕猎者在山谷北侧、洞穴下方的山坡上游荡。",
		["Fizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way."] = "费索·暗雷占据着{area:362}西北方{area:369}上的火刃氏族营地。猎人：沿途用{item:15908}驯服一只{npc:3099}。",
		["Follow the road east out of the valley to {area:367} on the coast."] = "沿道路向东离开山谷，到海岸边的{area:367}。",
		["Follow the road north from {area:362} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "沿道路从{area:362}向北到{zone:1454}的正门，就在{area:817}西边。{npc:3352}和猎人训练师一起站在{object:172958}。",
		["Follow the road north to {area:362}."] = "沿道路向北到{area:362}。",
		["Follow the road north toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "沿道路向北前往{zone:1454}。{npc:3293}在路边扎营；被偷走的补给袋散落在他南边的路上。",
		["Follow the road south-west from {area:379} to the {area:380}. {zone:1413} guide starts here."] = "沿道路从{area:379}向西南到{area:380}。{zone:1413}指南从这里开始。",
		["Follow the road west from {area:362} over the {area:814} bridge; {area:379} sits just above it on the {zone:1413} side."] = "沿道路从{area:362}向西过{area:814}的桥；{area:379}就在桥上方的{zone:1413}一侧。",
		["Free {npc:275811} and see her safely out of the crag"] = "救出{npc:275811}，护送她安全离开峭壁",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "向南穿过群岛。被遗忘的洛阿神像散落在南部各岛；巫毒巨魔和{npc:3207}守着它们，并掉落{item:275724}。{quest:826}和明希纳的笼子在最南边的岛上。",
		["Hit the sleeping peons north of the Den with the {item:16114}."] = "用{item:16114}敲打洞穴北边睡觉的苦工。",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "进入洞穴后，在第一个岔口直走，然后右转，沿左手边的溪流走到瀑布：镐在水边、一根石柱后面发光。",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "进入洞穴后，一直沿右侧洞壁绕行，越过溪流：{npc:3183}在尽头等候。",
		["Makrura and crawlers"] = "龙虾人和海浪蟹",
		["Makrura and surf crawlers line the beaches north-east of Sen'jin."] = "龙虾人和海浪蟹遍布森金村东北方的海滩。",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "米莎·托克伦的小屋在蜥蜴南边。西边{area:814}沿岸的鳄鱼带着{item:4891}。",
		["North end of the valley"] = "山谷北端",
		["Prickly pears"] = "仙人掌果",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "钢鬃野猪人和钢鬃斥候占据着镇子西边的小屋；钢鬃传令兵和钢鬃卫兵占据着更西边的营地。",
		["Ridgeshade spiders"] = "脊影蜘蛛",
		["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}."] = "尘风暴徒和尘风雷巫盘踞在{npc:3293}东边的{area:370}。尘风雷巫会掉落{item:277661}。",
		["South-east shore"] = "东南海岸",
		["Spitelash naga"] = "恶鞭纳迦",
		["Talk to {npc:3191}"] = "与{npc:3191}交谈",
		["Tame it with the {item:15908}"] = "用{item:15908}驯服它",
		["The foreman stands at the lumber pile east of the Den."] = "工头塔兹利尔站在洞穴东边的木材堆旁。",
		["The gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin."] = "侏儒的工具箱在{area:362}东边和东南边沿岸的残骸里。沿海岸向南到森金村。",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "城堡位于{area:362}东南方的海岸上。袭击者的斧头、弓和盾牌在城堡外围。库尔提拉斯水手和库尔提拉斯水兵掉落{item:4870}。{npc:3192}在城堡顶层等候；他的钥匙能打开他旁边的箱子，里面有{item:4881}。",
		["The prickly pears grow among the quilboar huts just west of town."] = "仙人掌果生长在镇子西边的野猪人小屋之间。",
		["The spiders lurk in the hills along the road north toward {area:362}."] = "蜘蛛潜伏在通往{area:362}的道路北段沿途的山丘上。",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "被遗弃的训练武器散落在洞穴和训练场周围；{npc:3098}在整个山谷谷底游荡。",
		["The wreckage"] = "残骸",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595}在{area:817}，就在你刚才对付的祭司中间。",
		["The {quest:792} swarm the slope below the {area:365}, the cave on the valley's north side."] = "{quest:792}聚集在山谷北侧洞穴{area:365}下方的山坡上。",
		["Thunder Lizards and Lightning Hides graze on {area:369} across the bridge; any of them can drop a {item:6486}."] = "{npc:3130}和{npc:3131}在桥对面的{area:369}上吃草；任何一只都可能掉落{item:6486}。",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}."] = "{npc:3130}和{npc:3131}在{npc:3293}西边和西南边的{area:369}上吃草。",
		["Thunder lizards"] = "雷霆蜥蜴",
		["Thunder lizards across the river"] = "河对岸的雷霆蜥蜴",
		["Training weapons and boars"] = "训练武器和野猪",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there."] = "涉水到回音群岛北部的岛屿。血爪族母在那里的迅猛龙中间潜行。",
		["Wade back west to the shore south of Sen'jin. Durotar Tigers roam it and the Taillasher eggs sit in nests along the beach."] = "向西涉水回到森金村南边的海岸。{npc:3121}在那里游荡，鞭尾龙的蛋在沿海滩的巢里。",
		["Wake {quest:5441} with the {item:16114}"] = "用{item:16114}叫醒{quest:5441}",
		["the {object:654925} on the ground beside her"] = "她身旁地上的{object:654925}",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366}在森金村西边。三份进攻计划在半人马帐篷之间的地上。{npc:275811}也被关押在峭壁。",
		["{area:817}'s mouth"] = "{area:817}的入口",
		["{npc:10176}, where you start"] = "{npc:10176}，你的出发点",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears."] = "{npc:265809}在{area:362}南边不远处扎营。坐在他的营火旁（/sit），直到出现{spell:1229451}增益效果。",
		["{npc:265809}'s campfire"] = "{npc:265809}的营火",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}：仅限附魔师，残渣通过分解{item:275724}获得",
		["{npc:266940}, on the east side of town"] = "{npc:266940}，在镇子东侧",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657}站在{area:362}东边的岸上。三叉戟、旗帜和匕首在他周围的海滩上。",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}是一个年轻的海巨人，在纳迦海滩北边的{zone:1411}北部海岸游荡。{npc:275666}是精英：建议组队。",
		["{npc:3102} hooves"] = "{npc:3102}的蹄子",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}，回到{area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}：{npc:275666}，一个精英海巨人",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143}站在洞口内侧；{npc:3159}在他身后的洞穴深处。",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143}在{npc:10176}西边的建筑——试炼谷洞穴里等候。",
		["{npc:3147}, in the watchtower"] = "{npc:3147}，在瞭望塔里",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}，洞穴旁的战士训练师",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}，洞穴旁的猎人训练师",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}，洞穴里的潜行者训练师",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}，洞穴深处的术士训练师",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}，洞穴旁的萨满祭司训练师",
		["{npc:3159}, at the back of the cave"] = "{npc:3159}，在洞穴深处",
		["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171}：{zone:1454}的{npc:3352}教授{spell:5149}",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287}受伤躺在洞穴西北方的山脚下。",
		["{npc:3294}, by the inn"] = "{npc:3294}，在旅店旁",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}，交给{zone:1454}的{npc:6018}：先留着",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}，洞穴处的牧师训练师",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}，法师训练师，在洞穴入口",
		["{npc:5887} stands just outside the Den."] = "{npc:5887}就站在洞穴外。",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887}站在洞穴外。{area:639}是洞穴南边的小山：在那里喝下{item:6635}以看到{npc:5891}，然后把{item:6656}带回给{npc:5887}。",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}：{npc:5873}和你的{item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}，在{area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786}站在山谷东侧出口的路上。",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}，在烹饪火堆旁",
		["{quest:790}, a large scorpid, prowls the slope south of {npc:3287} among the Scorpid Workers; pick the Cactus Apples by the cactuses on the way."] = "{quest:790}是一只大蝎子，在{npc:3287}南边的山坡上与{npc:3124}一起游荡；沿途在仙人掌旁采摘{item:11583}。",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828}在纳迦海滩西边、{quest:827}南边的山丘上扎营。",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "{zone:1454}的正门就在{area:817}西边。{npc:5875}站在{object:172982}下方的峡谷{object:172960}里。",
} end)()
t.guides["forever/horde/orc-troll/02-the-barrens"] = (function() return {
		["Back to the pirate camp: the boots are in the crate marked {object:3767} at the camp's south end, the lens in the Fragile crate just east of it."] = "回到海盗营地：靴子在营地南端标着{object:3767}的箱子里，透镜在其东边的“易碎品”箱子里。",
		["Back to the {area:380}"] = "返回{area:380}",
		["Back to the {area:380}; the next guide starts here."] = "返回{area:380}；下一份指南从这里开始。",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}, by {area:370}; they drop the {item:6652}."] = "{npc:3199}占据着{zone:1411}北部{area:370}旁的{area:1898}；他们掉落{item:6652}。",
		["Follow the road north to the {area:1703}; {npc:9316} stands just south of it."] = "沿道路向北到{area:1703}；{npc:9316}就站在它南边。",
		["Follow the road south-east to {area:392} on the coast."] = "沿道路向东南到海岸边的{area:392}。",
		["Head east to the Venture Co. research site west of the {area:382}. Use the {object:4141}, close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471}."] = "向东到{area:382}西边的风险投资公司研究站。使用{object:4141}，关闭钻机周围的三个阀门，再次使用控制台，然后从{npc:3471}身上拿到{item:5089}。",
		["Kolkar camps and the {area:386}"] = "科卡尔营地和{area:386}",
		["Oasis Snapjaws crowd the water of {area:387}, south-west of the {area:380}."] = "{npc:3461}挤满了{area:380}西南方的{area:387}水域。",
		["On the way back to the {area:380}, the Razormane camp again: Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "返回{area:380}的路上，再次经过钢鬃营地：钢鬃地卜师和钢鬃防御者占据着营地东半部；{npc:3438}在他们中间巡逻。",
		["Plainstriders and Sunscale raptors roam the plains all around the {area:380}."] = "平原陆行鸟和赤鳞迅猛龙在{area:380}周围的平原上游荡。",
		["Plainstriders and raptors"] = "陆行鸟和迅猛龙",
		["Razormane camp"] = "钢鬃营地",
		["Southsea beach"] = "南海海滩",
		["The Kolkar camps spread north-west of {npc:3389}; every Kolkar can drop {quest:855}. {area:386} lie in their middle, with Laden Mushrooms around the water. Savannah Prowlers roam the same plains."] = "科卡尔营地分布在{npc:3389}的西北方；每个科卡尔半人马都可能掉落{quest:855}。{area:386}在营地中间，水边长着{object:3640}。{npc:3425}在同一片平原上游荡。",
		["The Slayers hold the western end of the {area:383}, past the harpies you fought before; they drop the rings."] = "巫翼杀戮者占据着{area:383}西端，在你之前对付过的鹰身人更远处；它们掉落戒指。",
		["The Tool Buckets sit around the Venture Co. camp in the {area:382}, east of {npc:9316}."] = "{object:161752}散落在{npc:9316}东边、{area:382}的风险投资公司营地周围。",
		["The harpies nest in the {area:383} north-west of the {area:386}; any of them can drop a talon."] = "鹰身人在{area:386}西北方的{area:383}筑巢；任何一只都可能掉落爪子。",
		["The oasis lies south-east of the {area:380}. Test the seeds at the bubbling fissure in the middle of the water."] = "绿洲在{area:380}东南方。在水中央冒泡的裂隙处测试种子。",
		["The pirates camp along the beach south of {area:392}. The piles of complicated parts lie in and around their camp."] = "海盗在{area:392}南边的海滩上扎营。一堆错综复杂的零件散落在营地内外。",
		["The {area:1697} lie south-west of the oasis. Sunscale Scytheclaws drop the feathers you use on the three nests."] = "{area:1697}在绿洲西南方。{npc:3256}掉落羽毛，用在三个巢穴上。",
		["Wade into the pools to explore them"] = "涉水进入水池探索",
		["Walk back up the road to the {area:380}. Savannah Prowlers hunt along it and on the plains west of town: finish the claws before you hand them in."] = "沿道路走回{area:380}。{npc:3425}在沿路和镇子西边的平原上捕猎：交任务前收集完爪子。",
		["Water Seekers, Thornweavers and Hunters hold the camp east of the {area:380}. The supply crates sit at its eastern end. Warriors: the {object:58369} stands in the camp. Shamans: the quilboar drop the {item:5026}. Kill Savannah Prowlers you pass for their claws."] = "钢鬃寻水者、钢鬃织棘者和钢鬃猎手占据着{area:380}东边的营地。补给箱在营地东端。战士：{object:58369}在营地里。萨满祭司：野猪人掉落{item:5026}。顺路击杀{npc:3425}获取爪子。",
		["Witchwing Slayers"] = "{npc:3278}",
		["Witchwing harpies"] = "巫翼鹰身人",
		["You arrive from {area:379}. {npc:3338} stands by the inn; {npc:3429} and {npc:3449} on the tower platform; Helbrim and {npc:3464} by the north gate; {npc:3448} at the south gate."] = "你从{area:379}来到这里。{npc:3338}站在旅店旁；{npc:3429}和{npc:3449}在塔楼平台上；药剂师赫布瑞姆和{npc:3464}在北门旁；{npc:3448}在南门。",
		["Zhevra Runners graze on the same plains; finish the raptor heads as you go."] = "{npc:3242}在同一片平原上吃草；顺路收集完迅猛龙的头。",
		["Zhevra and raptors"] = "斑马和迅猛龙",
		["grind on Witchwing Slayers at the {area:383}, {zone:1413}"] = "在{zone:1413}的{area:383}刷{npc:3278}",
		["{area:1898} cultists"] = "{area:1898}的祭司",
		["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389}站在{area:380}西边不远处的科卡尔哨所。",
		["{npc:3449}, on the tower platform: needs level 12"] = "{npc:3449}，在塔楼平台上：需要12级",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878}在向东通往{area:392}的路旁扎营。",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900}用焦油和袋子制作{item:6636}。在他旁边的火盆处使用它，让{npc:5893}现身，击杀它获得{item:6655}，然后把余烬放进火盆。",
		["{npc:5900} waits on the {zone:1411} bank of the {area:814}, east of the Razormane camp."] = "{npc:5900}在钢鬃营地东边、{area:814}的{zone:1411}一侧河岸等候。",
		["{npc:5907} stands on the ridge north of the Razormane camp, east of the {area:380}."] = "{npc:5907}站在{area:380}东边、钢鬃营地北边的山脊上。",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}：{npc:2523}、你的{item:5176}和{item:263412}",
		["{quest:1492}, on the dock"] = "{quest:1492}，在码头上",
		["{quest:881}'s lair lies south of the {area:382}, north-east of the {area:380}. Use the horn {npc:3338} gave you there to call the white lion out. Then hearth to {area:392}."] = "{quest:881}的巢穴在{area:382}南边、{area:380}东北方。在那里使用{npc:3338}给你的号角，把白狮引出来。然后用炉石返回{area:392}。",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "在{npc:263664}的营火旁/sit，直到获得{spell:1229451}",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "天空祭司安德斯和阵亡的卫兵就在塔的西南方。从尸体上取得拉尼的幸运羽毛和影歌家族徽记。",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "回到{quest:92529}：村里满是奥拉凯斯唤暴者和{npc:251662}，{object:576179}在房屋之间，{npc:251966}在村子东南端等候。",
		["Back to {area:16624} with what you found."] = "带着你找到的东西返回{area:16624}。",
		["Back to {area:16635}"] = "返回{area:16635}",
		["Back to {area:16638}"] = "返回{area:16638}",
		["Back to {npc:268592}, then west into the {area:16623}: {npc:268605}'s home is in the hills south of the Windsong Crawlers' lakes."] = "回到{npc:268592} Swiftburn处，然后向西进入{area:16623}：{npc:268605}的家在{npc:254588}所在湖泊南边的山丘里。",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "回到{npc:268592} Swiftburn处。等他点燃{npc:268762}，然后在计时结束前把火焰直接带到{area:16638}{npc:252382}旁边的{npc:268679}。",
		["Bandit Highwaymen"] = "强盗路霸",
		["Cast {spell:1259686} near the {object:460001}"] = "在{object:460001}附近施放{spell:1259686}",
		["Climb the watchtower in the village, jump off the top and use {spell:1259416} to float down."] = "爬上村里的瞭望塔，从塔顶跳下，使用{spell:1259416}缓缓飘落。",
		["Faladiel stands on the hill west of the falls, north of {area:16638}."] = "Skypriest Faladiel站在{area:16638}北边、瀑布西边的山丘上。",
		["Find {npc:258130}"] = "找到{npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle."] = "沿道路向南到岛屿中部的{area:16624}。",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "向北进入{area:16631}；{npc:257944} Thornpaw在森林南缘扎营。",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "向西南前往{area:17674}。{npc:252155}在塔顶；{item:254871}在他旁边。",
		["Heal the injured druids in the Nightfang Den"] = "治疗Nightfang Den里受伤的德鲁伊",
		["High Order Apprentices"] = "{npc:257521}",
		["Hippogryph nests"] = "角鹰兽巢穴",
		["Horde airship"] = "部落飞艇",
		["Leave {zone:1456} by a lift and follow the road south past {area:222} and through the eastern pass into the {zone:1413}; from the pass, take the {area:458} north to the {area:380}, the Horde town in the middle of the {zone:1413}."] = "乘升降梯离开{zone:1456}，沿道路向南经过{area:222}，穿过东边的山口进入{zone:1413}；从山口沿{area:458}向北到{area:380}，即{zone:1413}中部的部落城镇。",
		["Leaving {area:16635}"] = "离开{area:16635}",
		["Listen to {npc:252448}'s story"] = "听{npc:252448}讲述他的故事",
		["Listen to {npc:256083}"] = "听{npc:256083}说话",
		["Northern {zone:1412}"] = "{zone:1412}北部",
		["On the way north, back to {npc:255853} by the falls."] = "向北的路上，回到瀑布旁找{npc:255853}。",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "烦人的卷云蝇和{npc:250873}在村子东南方的林地里游荡。",
		["Prideclaws and Galestriders"] = "傲爪和疾风陆行鸟",
		["Prideclaws and Galestriders share the meadows south of the village. Keep the {item:5469} for {npc:251905}; the eggs come later from the hippogryphs."] = "傲爪和疾风陆行鸟分布在村子南边的草地上。把{item:5469}留给{npc:251905}；蛋稍后从角鹰兽身上获得。",
		["Raw Windstones"] = "原始风石",
		["Ride north-east to the {area:17675}. The Al'Aketh camp is just west of it, with {npc:252666} at its north end. Every cultist can drop a windstone charm."] = "向东北骑到{area:17675}。奥拉凯斯营地就在它西边，{npc:252666}在营地北端。每个教徒都可能掉落风石护符。",
		["Sit by {npc:263664}'s campfire (type /sit) until you get the {spell:1229451} buff, then find {npc:251905} at the cook fire."] = "坐在{npc:263664}的营火旁（输入/sit），直到获得{spell:1229451}增益效果，然后到烹饪火堆旁找{npc:251905}。",
		["Skyhoppers"] = "{npc:251727}",
		["Skyhoppers hop about the fields just west of Valennia."] = "{npc:251727}在瓦伦妮亚·风暴之拳西边的田野里蹦跳。",
		["Spread the {item:278078} off {area:1641}"] = "在{area:1641}散播{item:278078}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "成熟的风暴苹果和扑翼蝶鳞粉散落在果园各处；{npc:252802}在果园里抢劫。疾风陆行鸟在果园东边的田野里吃草。损坏的构造体漂浮在果园北缘。",
		["Take the Torch of Dormant Flame to {npc:268592} at the Shrine of Flames, south-west of {area:16638} in the {area:16626}."] = "把Torch of Dormant Flame带给{area:16626}中、{area:16638}西南方Shrine of Flames的{npc:268592}。",
		["Take the portal up to the {area:16630} and join {npc:252475} and {npc:251968} against the High Priestess."] = "乘传送门上到{area:16630}，与{npc:252475}和{npc:251968}一起对抗高阶女祭司洛苏娜。",
		["Take the road south-east to {area:16638}, the Skyborne town on the south coast. {npc:257006} and {npc:252448} stand at its western edge."] = "沿道路向东南到南部海岸的天裔城镇{area:16638}。{npc:257006}和{npc:252448}站在城镇西缘。",
		["Talk to {npc:251902}"] = "与{npc:251902}交谈",
		["Talk to {npc:251968}"] = "与{npc:251968}交谈",
		["Talk to {npc:252383}"] = "与{npc:252383}交谈",
		["Talk to {npc:252800}"] = "与{npc:252800}交谈",
		["Talk to {npc:253576}"] = "与{npc:253576}交谈",
		["Talk to {npc:254089}"] = "与{npc:254089}交谈",
		["Tell {npc:252800} you're ready"] = "告诉{npc:252800}你已准备就绪",
		["The Al'Aketh camp"] = "奥拉凯斯营地",
		["The Al'Aketh cultists in the camp beyond {npc:252095} carry the signet."] = "{npc:252095}身后营地里的奥拉凯斯教徒带着徽记。",
		["The Horde airship docks at the south-west edge of {area:16638}. Ride it to Kalimdor; it lands in northern {zone:1412}."] = "部落飞艇停靠在{area:16638}西南边缘。乘它前往卡利姆多；它会降落在{zone:1412}北部。",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "原始风石是村子周围山坡上的蓝色水晶。",
		["The Ursera den is west of the village. {npc:251115}, their matriarch, sits at its far end."] = "乌萨拉巢穴在村子西边。它们的族母{npc:251115}坐在巢穴尽头。",
		["The airship"] = "飞艇",
		["The apprentices practise north-east of the village."] = "学徒们在村子东北方练习。",
		["The bandit camps are north-east of the village; \"Badwind\" Bennic holds the top camp. Bandits carry the stolen windstones."] = "强盗营地在村子东北方；“恶风”本尼克占据着最高处的营地。强盗们带着被偷走的风石。",
		["The crawlers scuttle along the shore south-west of town."] = "这些爬行者在城镇西南方的海岸上爬行。",
		["The hermit lives at {area:16625}'s west shore. {item:257128} cones grow south of him; the Wind Hollows drift east of the lake."] = "隐士住在{area:16625}西岸。{item:257128}的球果生长在他南边；{npc:251676}在湖的东边飘荡。",
		["The highland bandits"] = "高地强盗",
		["The highwaymen hold the hills north-east of the orchard. More {object:616468} lie near the road to {area:16638}."] = "强盗路霸占据着果园东北方的山丘。更多{object:616468}在通往{area:16638}的道路附近。",
		["The hippogryph nests are north-west of the tower, west of {quest:92529}; the Matriarch sits at the western end. {item:263493} lies on the ground around them, and the hippogryphs drop the Small Eggs."] = "角鹰兽巢穴在塔的西北方、{quest:92529}西边；角鹰兽雌兽在最西端。{item:263493}散落在巢穴周围的地上，角鹰兽会掉落{item:6889}。",
		["The orchard"] = "果园",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "卷云蝇后在林地东南端盘旋，就在你从立石返回的路上。",
		["The refugees' belongings lie along the north shore of {area:16625}; {npc:259013} is at its north-west end."] = "难民的物品散落在{area:16625}北岸；{npc:259013}在湖的西北端。",
		["The standing stones"] = "立石",
		["The turncoat"] = "叛徒",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}. {npc:273017} waits nearby; his assassins lurk around the house."] = "叛徒的房子在{area:16638}西北方的{area:16626}。{npc:273017}在附近等候；他的刺客潜伏在房子周围。",
		["The watchtower"] = "瞭望塔",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629}在{area:16638}北边。一路击败卫兵，到其东侧找{npc:253576}。",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {object:148418}"] = "{object:148418}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "在{area:1641}朝南的悬崖上，于仪式垫和香炉处使用{item:278078}。",
		["Walk north to {area:16624}; finish the {item:5469} on the Galestriders along the way if you are short."] = "向北走到{area:16624}；如果{item:5469}还不够，就沿途从疾风陆行鸟身上收集完。",
		["Wind Hollows and {object:616467}"] = "{npc:251676}和{object:616467}",
		["Wind Hollows drift over the lowlands around {area:16638}. The first {object:616467} lie west of the orchard road."] = "{npc:251676}在{area:16638}周围的低地上空飘荡。第一批{object:616467}在果园道路的西边。",
		["Windsong Crawlers"] = "{npc:254588}",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "你将永远离开这座岛。{npc:259119}在飞艇降落处等候。",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "你在岛屿北部的{area:16635}醒来。{npc:251362}站在小路旁，{npc:251361}在村子中央。",
		["search the dead cultist in the house"] = "搜查房子里死去的教徒",
		["search the wardrobe"] = "搜查衣柜",
		["talk to {npc:251684}"] = "与{npc:251684}交谈",
		["talk to {npc:251902}"] = "与{npc:251902}交谈",
		["talk to {npc:251905}"] = "与{npc:251905}交谈",
		["talk to {npc:251968}"] = "与{npc:251968}交谈",
		["talk to {npc:252155}"] = "与{npc:252155}交谈",
		["talk to {npc:252383}"] = "与{npc:252383}交谈",
		["talk to {npc:252476}"] = "与{npc:252476}交谈",
		["talk to {npc:257554}"] = "与{npc:257554}交谈",
		["the bounty board"] = "悬赏布告板",
		["{area:1638} is beside the landing: ride up a lift and learn the flight path from {npc:2995}, the wind rider master."] = "{area:1638}就在降落处旁：乘升降梯上去，向双足飞龙管理员{npc:2995}学习飞行路线。",
		["{area:16624} turn-ins"] = "{area:16624}交任务",
		["{area:16624}, last time"] = "最后一次回到{area:16624}",
		["{area:16635} turn-ins"] = "{area:16635}交任务",
		["{area:16663} is west of {area:16638} along the coast road."] = "{area:16663}在{area:16638}西边，沿海岸道路前往。",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105}生长在{npc:257944} Thornpaw的营地周围，Shrieking在上空飞行。她东边的奥拉凯斯营地里有{item:265141}。",
		["{item:278079}, from {npc:3014}"] = "{item:278079}，来自{npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}，来自{npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}，来自{npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}，来自{npc:3027}",
		["{npc:249363} stands at the {area:17678}, east of the village. {npc:251143} and Al'Aketh Converts gather just north of her. The {object:460001} is just north-east of her: cast your {spell:1259686} racial ability next to it."] = "{npc:249363}站在村子东边的{area:17678}。{npc:251143}和{npc:251160}聚集在她北边不远处。{object:460001}就在她东北方：在它旁边施放你的种族技能{spell:1259686}。",
		["{npc:250926} prowl the slopes south-west of the village, on the way to {npc:252095}."] = "{npc:250926}在村子西南方的山坡上潜行，就在去找{npc:252095}的路上。",
		["{npc:251361}'s errands"] = "{npc:251361}的差事",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}：训练师给你的便条",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}：查看{item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}：阅读{item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}：{item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}，德鲁伊训练师，在{npc:251361}身后那棵树的底层",
		["{npc:251374} sends you to the {area:16988}, just east of the village: drink the {item:6635} there to see the {npc:251166}, then take the {item:6656} back to him."] = "{npc:251374}让你去村子东边不远处的{area:16988}：在那里喝下{item:6635}以看到{npc:251166}，然后把{item:6656}带回给他。",
		["{npc:251374} stands in the village."] = "{npc:251374}站在村子里。",
		["{npc:251374}, at the village centre"] = "{npc:251374}，在村子中央",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}：{npc:5873}和你的{item:5175}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}，在瞭望塔里",
		["{npc:251964}, in the watchtower"] = "{npc:251964}，在瞭望塔里",
		["{npc:252095} waits in {area:16622}, south-west of the village. The Al'Aketh camp is just beyond her; {npc:256935} leads it."] = "{npc:252095}在村子西南方的{area:16622}等候。奥拉凯斯营地就在她身后；{npc:256935}是营地首领。",
		["{npc:252359} stands on {area:16638}'s east side."] = "{npc:252359}站在{area:16638}东侧。",
		["{npc:252377} stands in the middle of {area:16638}."] = "{npc:252377}站在{area:16638}中央。",
		["{npc:252382} stands on {area:16638}'s west side."] = "{npc:252382}站在{area:16638}西侧。",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}：{npc:2523}、你的{item:5176}和{item:263412}",
		["{npc:252389} in {area:16638} hands you a {item:15908} three times: tame a {npc:254588} by the lakes north-west of town, an {npc:251707} in the fields west of town and a {npc:250874} at {area:16663}, returning to her after each. {npc:254411} stands beside her."] = "{area:16638}的{npc:252389}会三次交给你{item:15908}：在城镇西北方的湖边驯服一只{npc:254588}，在城镇西边的田野驯服一只{npc:251707}，在{area:16663}驯服一只{npc:250874}，每次驯服后都回到她那里。{npc:254411}站在她旁边。",
		["{npc:252448} and {npc:256083}"] = "{npc:252448}和{npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}、{npc:258130}和{npc:258134}在{npc:257944} Thornpaw东边的教派营地里。{npc:254151}站在营地边缘。Haalien还会掉落{quest:94490}：阅读它开始下一个任务。完成{quest:94489}：进入Nightfang Den，治疗7名受伤的德鲁伊并找到{npc:258130}。",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589}潜伏在村子南边的傲爪之间。{npc:254589}是精英：建议组队。",
		["{npc:255853} waits by the falls just north of the watchtower."] = "{npc:255853}在瞭望塔北边不远处的瀑布旁等候。",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083}站在城镇西北方的{area:16626}。",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247} Brightwish在{area:16638}北边、通往{area:16629}的路上等候。",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196}在神殿西侧守着{item:263993}。",
		["{npc:257944} again"] = "再次找{npc:257944} Thornpaw",
		["{npc:257944}, last time"] = "最后一次找{npc:257944}",
		["{npc:258443} roams the slopes just south of the turncoat's house."] = "{npc:258443}在叛徒房子南边不远处的山坡上游荡。",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "{npc:259118}，在降落处旁：交给{zone:1456}的{npc:3033}",
		["{npc:259119}: keep it, Thrall in {zone:1454} comes two guides later"] = "{npc:259119}：先留着，两份指南后到{zone:1454}交给萨尔",
		["{npc:263664}'s campfire"] = "{npc:263664}的营火",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068}想要牛头人熏香：从草药商{npc:3014}、附魔供应商{npc:3012}、制皮供应商{npc:3005}和烹饪供应商{npc:3027}处购买四种材料，然后合成{item:278078}。",
		["{npc:3033} trains druids on {area:1639}. He teaches you {spell:18960}; {npc:11802}'s welcome waits for your {spell:499} trip at about 23 (forever/horde/04-the-barrens)."] = "{npc:3033}在{area:1639}训练德鲁伊。他会教你{spell:18960}；{npc:11802}的问候要等到你约23级的{spell:499}之旅时再去（forever/horde/04-the-barrens）。",
		["{npc:3615}, the wind rider master"] = "{npc:3615}，双足飞龙管理员",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529}在申达尔村南边。{npc:257065}在村边与你会合；搜查他身后房子里的衣柜。",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["/sit by Kaga's campfire until you get {spell:1229451}"] = "在Kaga的营火旁/sit，直到获得{spell:1229451}",
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "向东返回{area:358}：{npc:2953}站在那里的野猪人中间。",
		["Back south-east to the {area:396}."] = "向东南返回{area:396}。",
		["Back to Bloodhoof"] = "返回血蹄村",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "回到营地找{npc:5888}。{npc:5891}在营地东边的台地上等候：在那里喝下{item:6635}以看到它，然后把{item:6656}带回给先知。",
		["Back west to the camp."] = "向西返回营地。",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "斗猪在神龛北边吃草；刺背野猪人占据着东北方的峡谷。{npc:8554}站在峡谷东端，{object:3076}在营地的地上。",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the north-western woods."] = "施放{spell:18960}。{npc:11802}在{area:2361}；{quest:5930}在西北方的树林里。",
		["Class turn-ins in {area:1638}"] = "在{area:1638}交职业任务",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "向西北经过{zone:1456}，到{zone:1412}最北边的{area:398}。",
		["Finish the wolf heart, cougar femur, plainstrider scale and swoop gizzard on the plains around the village."] = "在村子周围的平原上收集完狼心、美洲狮股骨、陆行鸟鳞片和猛鹫胃。",
		["Follow the path south out of camp to the Seer's tent at the foot of the hills."] = "沿小路向南离开营地，到山脚下灰舌先知的帐篷。",
		["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}."] = "沿道路向北离开{area:220}。{npc:265810}在{area:222}南边不远处的路上等候；在她的营火旁/sit，直到获得{spell:1229451}。",
		["Galak centaurs"] = "加拉克半人马",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "向北到{zone:1456}东边的{area:225}。{npc:3233}站在岩石脚下；{npc:3232}在墓地里挖掘，{npc:2994}在顶上等候。",
		["Hearth to {area:222} and ride north to {area:1639}."] = "用炉石返回{area:222}，然后向北骑到{area:1639}。",
		["Leave {zone:1412} by the south-eastern pass and follow the road to the {area:380}. {quest:860} stands by the inn, {npc:3448} at the south gate. {zone:1413} guide starts here."] = "从东南方的山口离开{zone:1412}，沿道路到{area:380}。{quest:860}站在旅店旁，{npc:3448}在南门。{zone:1413}指南从这里开始。",
		["Plainstriders roam the grass all around the camp."] = "平原陆行鸟在营地周围的草地上游荡。",
		["Prairie Wolf Alphas"] = "草原狼前锋",
		["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "草原狼前锋在{npc:275789}和东边加拉克营地周围的平原上，混在狼群中游荡。",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "草原狼和{npc:2956}在村子周围的平原上游荡。",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "乘升降梯上到台地。{npc:2995}在中央台地照看双足飞龙；{npc:3057}站在那里的大帐篷里。",
		["Ride down to {area:222} and tame with the {item:15908}: an {npc:2956} on the plains, a {npc:2959} north of the village, a Swoop to the north-west."] = "骑到{area:222}，用{item:15908}驯服：平原上的一只{npc:2956}，村子北边的一只{npc:2959}，西北方的一只猛鹫。",
		["Speak with {npc:3067}"] = "与{npc:3067}交谈",
		["Spread the {item:278078} off {area:1641}"] = "在{area:1641}散播{item:278078}",
		["Swoops glide over the plains all around Bloodhoof."] = "猛鹫在血蹄村周围的平原上空滑翔。",
		["Tame it with the {item:15908}"] = "用{item:15908}驯服它",
		["The Galak centaurs camp on the plains east of the well; {npc:275767} leads them."] = "加拉克半人马在水井东边的平原上扎营；{npc:275767}是他们的首领。",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "白鬃豺狼人占据着挖掘场南边、血蹄村西边的{area:818}。{npc:272203}被关在他们的营地里：带他出来。",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "风怒鹰身人占据着水井北边和西边的{area:819}。",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "{area:404}的矮人带着勘察员的锄头。在挖掘场里矮人的熔炉上砸碎它们。",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "地精在水井东北方的山丘里开矿。{quest:765}站在矿洞深处；他的{item:281031}开始{quest:98424}，其余几页在矿洞里。",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "熏香十分钟就会燃尽：沿南边的山丘一直向东跑到{object:660739}。",
		["The shrine of An'she and Mu'sha"] = "安瑟与Mu'sha的神龛",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "石头在离开{zone:1412}的山口里，就在你向东的路上。在那里使用{item:15710}并击败月爪枭兽。",
		["The well lies north of the village. Well Stones sit around the well, {object:2912} lies under the trees nearby. Kill wolves, cougars, plainstriders and swoops on the way for {quest:766} and {quest:761}."] = "水井在村子北边。水井石在水井周围，{object:2912}在附近的树下。沿途击杀狼、美洲狮、平原陆行鸟和猛鹫，完成{quest:766}和{quest:761}。",
		["The well lies south-east of the village."] = "水井在村子东南方。",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "被毁的商队在半人马西北方、通往{zone:1456}的道路东边。",
		["The {object:177525}"] = "{object:177525}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "在{area:1641}朝南的悬崖上，于仪式垫和香炉处使用{item:278078}。",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "你从{area:221}的台地上出发。{npc:2980}和鹰风酋长站在中央的大帐篷旁。",
		["{item:278079}, from {npc:3014}"] = "{item:278079}，来自{npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}，来自{npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}，来自{npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}，来自{npc:3027}",
		["{item:4703}, at the digsite forge"] = "{item:4703}，在挖掘场的熔炉旁",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203}：平原徘徊者在{area:225}周围的平原上游荡",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068}想要牛头人熏香：从草药商{npc:3014}、附魔供应商{npc:3012}、制皮供应商{npc:3005}和烹饪供应商{npc:3027}处购买四种材料，然后合成{item:278078}。",
		["{npc:275789} stands on the {area:821} a little east of the well."] = "漫行者{npc:275789}站在水井东边不远处的{area:821}上。",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182}站在村子北缘。Kyle想要平原陆行鸟身上的{item:287505}。",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}，在村子北端",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}，交给{zone:1456}的大德鲁伊哈缪尔·符文图腾",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984}站在水井南边的{area:404}边缘。",
		["{npc:2988} camps by the {area:396} south-east of Bloodhoof."] = "{npc:2988}在血蹄村东南方的{area:396}旁扎营。",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991}坐在营地东缘的帐篷旁；{object:2907}就在她旁边。",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}，交给{zone:1456}的{npc:3057}",
		["{npc:3059}, the warrior trainer"] = "{npc:3059}，战士训练师",
		["{npc:3060}, the druid trainer beside him"] = "{npc:3060}，他旁边的德鲁伊训练师",
		["{npc:3061}, the hunter trainer"] = "{npc:3061}，猎人训练师",
		["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}，营地里的萨满祭司训练师",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "{npc:3063}的任务：击败他旁边的三名{npc:10721}（或在决斗中击败玩家）。",
		["{npc:3209}, next to {npc:2980}"] = "{npc:3209}，在{npc:2980}旁边",
		["{npc:3441}: for {quest:860} at the {area:380}"] = "{npc:3441}：交给{area:380}的{quest:860}",
		["{npc:5769}: for {npc:3448} at the {area:380}"] = "{npc:5769}：交给{area:380}的{npc:3448}",
		["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888}站在{area:221}。{quest:1516}需要4级，交完这里的任务就能达到。",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}：{npc:5873}和你的{item:5175}",
		["{npc:6746} on the central rise sends you to {npc:3033} on {area:1639}."] = "中央台地的{npc:6746}让你去{area:1639}找{npc:3033}。",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "{npc:6775}站在营地西端，位于{npc:2961}出没的山丘西北角：接下他的任务，从那里向南和向东猎杀美洲狮，然后回到{npc:2980}处。",
		["{quest:96130} and {quest:756}"] = "{quest:96130}和{quest:756}",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "{quest:96130}是一只独狼，在村子西边的平原上潜行。{npc:2959}和{npc:3035}在村子北边和西边的平原上游荡。",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["/sit by her campfire until you get {spell:1229451}"] = "在她的营火旁/sit，直到获得{spell:1229451}",
		["Ask {npc:10666} for his report"] = "向{npc:10666}索取报告",
		["Ask {npc:1496} for his report"] = "向{npc:1496}索取报告",
		["Ask {npc:251001} for his report"] = "向{npc:251001}索取报告",
		["Back to the church"] = "返回教堂",
		["Back to {area:154}"] = "返回{area:154}",
		["Back to {area:159}."] = "返回{area:159}。",
		["Back up the road to {area:159}."] = "沿道路返回{area:159}。",
		["Balnir graves"] = "巴尼尔墓地",
		["Beat {npc:6784} in the duel"] = "在决斗中击败{npc:6784}",
		["Crusader's Outpost"] = "十字军前哨",
		["Dry Branches"] = "干枯的树枝",
		["Duskbats and Darkhounds roam all along the road back west; finish the wings and hides on the way."] = "夜行蝙蝠和黑暗犬在向西返回的道路沿线游荡；顺路收集完翅膀和皮。",
		["Eleanor camps just south-west of town."] = "埃莉诺·沙克尔顿在镇子西南方不远处扎营。",
		["Escort {npc:275954} out of the outpost"] = "护送{npc:275954}离开前哨",
		["Fields west of {area:159}"] = "{area:159}西边的田野",
		["Follow the path north into {area:154}; Sarvis stands in front of the church."] = "沿小路向北进入{area:154}；暗影牧师萨维斯站在教堂前。",
		["Follow the road east to {area:159}. {npc:10665} stands at the north-west edge of town; the {area:2119} is the big inn in the middle, with {npc:1515} in front of it."] = "沿道路向东到{area:159}。{npc:10665}站在镇子西北边缘；{area:2119}是镇中央的大旅店，{npc:1515}站在旅店前。",
		["Follow the road east. Bleeding Horrors and Wandering Spirits haunt the graves on the east side of the farmstead, where the {quest:99142} grows."] = "沿道路向东。{npc:1529}和{npc:1532}在农场东侧的墓地里出没，{quest:99142}也生长在那里。",
		["Follow the road north-east from {area:159} past {area:162}. {npc:1665} and his two Scarlet Bodyguards hold the Scarlet watchtower on the north-east coast, north of the {area:459}: pull the bodyguards first."] = "沿道路从{area:159}向东北经过{area:162}。{npc:1665}和他的两名{npc:1660}占据着{area:459}北边、东北海岸上的血色瞭望塔：先拉保镖。",
		["Follow the road north-west to {area:157}. {npc:1657} walks the graveyard south of the mills; Nissa, Gregor and {npc:1656} haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop {item:2839}. From here on, kill the Duskbats and Darkhounds you pass: {npc:3549} wants their wings and hides."] = "沿道路向西北到{area:157}。{npc:1657}在磨坊南边的墓地里游荡；妮萨·阿加曼德、格里高·阿加曼德和{npc:1656}在磨坊里出没。断骨士兵和{npc:1523}掉落肋骨，{npc:1522}掉落头骨，其中任何一个都可能掉落{item:2839}。从这里开始，击杀路过的夜行蝙蝠和黑暗犬：{npc:3549}需要它们的翅膀和皮。",
		["Follow the road south back to {area:159}."] = "沿道路向南返回{area:159}。",
		["Follow the road south-east from {area:159} past the zeppelin towers. Linnea, Kristof and {npc:3549} camp by the road."] = "沿道路从{area:159}向东南经过飞艇塔。亡灵卫兵林奈、亡灵卫兵克里斯托弗和{npc:3549}在路旁扎营。",
		["Follow the road south-west from {area:159} to the Scarlet Crusade camp. {npc:1662} stands at its south end; every Scarlet there can drop a ring."] = "沿道路从{area:159}向西南到血色十字军营地。{npc:1662}站在营地南端；那里的每个血色十字军都可能掉落戒指。",
		["Follow the road west past {area:157} to the {area:16616}. Leonid stands just north of {npc:246389}'s camp."] = "沿道路向西经过{area:157}到{area:16616}。莱尼德·巴萨罗梅站在{npc:246389}营地北边不远处。",
		["Free six Webbed Victims inside the cave for {npc:244808}"] = "为{npc:244808}解救洞内六名被网住的被遗忘者",
		["Greater Duskbats"] = "{npc:1553}",
		["Greater Duskbats fly over the fields around {area:159} and along the road north."] = "{npc:1553}在{area:159}周围的田野上空和北边的道路沿线飞行。",
		["Head west into the {area:16616}; {npc:246389} and {npc:259190} camp at its edge."] = "向西进入{area:16616}；{npc:246389}和{npc:259190}在森林边缘扎营。",
		["Head west to the cave. The Young Night Web Spiders sit outside; the Night Web Spiders and the Webbed Victims are inside."] = "向西前往洞穴。{npc:1504}在洞外；{npc:1505}和被网住的被遗忘者在洞内。",
		["Hearth to {area:159}"] = "用炉石返回{area:159}",
		["Leave {area:154} by the road north-east. {npc:6784} stands by the farmhouse at the {area:156}."] = "沿东北方的道路离开{area:154}。{npc:6784}站在{area:156}的农舍旁。",
		["Listen to Leonid and {npc:246378}, then talk to him again"] = "听莱尼德·巴萨罗梅和{npc:246378}说话，然后再次与他交谈",
		["Mindless Zombies"] = "{npc:1501}",
		["More Vile Fin murlocs walk the shore just north of the outpost."] = "前哨北边的海岸上还有更多邪鳍鱼人。",
		["Offer aid to the {npc:246143}"] = "向{npc:246143}提供帮助",
		["Only if the letter dropped"] = "仅当信件已掉落",
		["Paladin: {area:16616}"] = "圣骑士：{area:16616}",
		["Paladins: {quest:90902} is done once you have healed five {npc:259377} around the church with {spell:635}."] = "圣骑士：用{spell:635}治疗教堂周围的五名{npc:259377}后，{quest:90902}即完成。",
		["Rattlecage Skeletons wander the ruined houses in the north half of {area:154}. Young Scavengers and Duskbats roam all around the village; the Ragged Scavengers and Mangy Duskbats are on its east side."] = "{npc:1890}在{area:154}北半部的废弃房屋里游荡。{npc:1508}和夜行蝙蝠在村子周围游荡；{npc:1509}和{npc:1513}在村子东侧。",
		["Rattlecage skulls"] = "骷髅的头骨",
		["Rattlecages, scavengers and duskbats"] = "骷髅、食腐狼和夜行蝙蝠",
		["Rot Hide graveyards"] = "腐皮豺狼人墓地",
		["Scarlet Warriors guard the outpost just west of the pumpkin fields. {npc:275954} is held inside: talk to him and stay with him until he is out."] = "{npc:1535}守卫着南瓜田西边不远处的前哨。{npc:275954}被关在里面：和他交谈，一直跟着他直到他离开。",
		["Take the road south-east out of {area:159}; Terrence stands on it short of the zeppelin towers."] = "沿东南方的道路离开{area:159}；亡灵卫兵特伦斯站在飞艇塔之前的路上。",
		["Talk to {npc:265944}"] = "与{npc:265944}交谈",
		["The Dry Branches lie on the ground around the south-west edge of {area:159}."] = "干枯的树枝散落在{area:159}西南边缘的地上。",
		["The Rattlecage Skeletons in the ruined houses drop the skulls."] = "废弃房屋里的{npc:1890}掉落头骨。",
		["The Rot Hide Graverobbers dig through the graveyards north of {area:159}; all the Rot Hides drop the ichor."] = "{npc:1941}在{area:159}北边的墓地里挖掘；所有腐皮豺狼人都会掉落脓液。",
		["The Rot Hide Mongrels hold the hills further north. {npc:1753} (level 11) stands in their camp on the hill south of the shore: clear the gnolls around him first."] = "{npc:1675}占据着更北边的山丘。{npc:1753}（11级）站在海岸南边山丘上的营地里：先清理他周围的豺狼人。",
		["The Scarlet Converts and Initiates hold the farm east of {area:154}. {npc:1919} wanders between the farmhouses: his remains are for {quest:6395}."] = "{npc:1506}和血色新兵占据着{area:154}东边的农场。{npc:1919}在农舍之间游荡：他的遗骸用于{quest:6395}。",
		["The Scarlet Friars camp just north-east of the graves; {npc:1664} stands among them."] = "{npc:1538}在墓地东北方不远处扎营；{npc:1664}站在他们中间。",
		["The Scarlet camp"] = "血色营地",
		["The Scarlet farm"] = "血色农场",
		["The Vile Fin murlocs line the north shore."] = "邪鳍鱼人遍布北部海岸。",
		["The Wanted poster by the inn"] = "旅店旁的通缉布告",
		["The spiders lurk in the woods at the far east end of the glades."] = "蜘蛛潜伏在林地最东端的树林里。",
		["The zeppelin lands at the tower just north-east of {zone:1454}'s main gate. Follow the road south into {zone:1411}, cross the {area:815} bridge below {area:379} and follow the road west to the {area:380}."] = "飞艇停靠在{zone:1454}正门东北方的塔上。沿道路向南进入{zone:1411}，从{area:379}下方过{area:815}的桥，然后沿道路向西到{area:380}。",
		["The zombies shamble around the graveyard and the houses just east of the church."] = "僵尸在墓地和教堂东边的房屋周围蹒跚游荡。",
		["The {area:154} trainers stand around the church"] = "{area:154}的训练师站在教堂周围",
		["The {area:159} trainers are in and around the inn"] = "{area:159}的训练师在旅店内外",
		["The {npc:1931}, in the town hall basement"] = "{npc:1931}，在城镇大厅的地下室",
		["The {npc:2211}, in the town hall basement"] = "{npc:2211}，在城镇大厅的地下室",
		["The {npc:246143}"] = "{npc:246143}",
		["The {object:164662} lie beside the ruined houses in the north of {area:154}."] = "{object:164662}在{area:154}北部的废弃房屋旁。",
		["The {quest:5482} grows in the graveyard fields just north of {area:159}."] = "{quest:5482}生长在{area:159}北边的墓地田野里。",
		["Tirisfal Pumpkins"] = "{object:375}",
		["Use the {item:286176} on five idle Deathguards around town"] = "对镇子周围五名闲着的亡灵卫兵使用{item:286176}",
		["Vicious Night Web Spiders"] = "{npc:1555}",
		["Vile Fin murlocs"] = "邪鳍鱼人",
		["Vile Fin shore"] = "邪鳍海岸",
		["Walk on west to the {area:156}. {npc:1519} stands at the farm; {npc:6784}, by the farmhouse, wants a duel: talk to him."] = "继续向西走到{area:156}。{npc:1519}站在农场里；农舍旁的{npc:6784}想和你决斗：和他对话。",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:4568} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "从{area:159}向南走到{area:153}，再往下进入{zone:1458}。{npc:4568}站在{object:36082}。血色营地就在废墟西边。",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:5675} stands in the {object:36082}. The Scarlet camp is just west of the ruins."] = "从{area:159}向南走到{area:153}，再往下进入{zone:1458}。{npc:5675}站在{object:36082}。血色营地就在废墟西边。",
		["Walk south-east from {area:159} to the zeppelin towers outside the {area:153} and board the zeppelin to {zone:1454} (the other one goes to {object:3202})."] = "从{area:159}向东南走到{area:153}外的飞艇塔，登上前往{zone:1454}的飞艇（另一艘前往{object:3202}）。",
		["Walk south-west from the mills: the pumpkins grow in the Scarlet-held fields north-west of Solliden."] = "从磨坊向西南走：南瓜生长在索利丹农场西北方、血色十字军占据的田里。",
		["Webbed Victims"] = "被网住的被遗忘者",
		["You rise in the crypt at the south end of {area:154}. {npc:1568} waits just outside."] = "你在{area:154}南端的墓穴中苏醒。{npc:1568}就在外面等候。",
		["Zeppelin to {zone:1411}"] = "乘飞艇前往{zone:1411}",
		["Zeppelin tower"] = "飞艇塔",
		["in the inn: ask him about cooking"] = "在旅店里：向他询问烹饪",
		["{area:16881} is the hollow at the west edge of the glades. The Shadowvale Lurchers and Mystics drop the bones; the bottles lie on the ground among them, and the {item:286269} is at the south end."] = "{area:16881}是林地西缘的洼地。{npc:260428}和影谷秘法师掉落骨头；瓶子散落在它们中间的地上，{item:286269}在南端。",
		["{item:16333}, from {npc:1919}"] = "{item:16333}，来自{npc:1919}",
		["{item:2320} from {npc:2118}, for Gretchen"] = "从{npc:2118}处购买{item:2320}，交给格莉丝·戴玛",
