t.guides["forever/reputation/arathi-basin"] = (function() return {
		["Arathi Basin Reputation"] = "阿拉希盆地声望",
		["Exalted with the League of Arathor earns a Legacy Point."] = "阿拉索联军达到崇拜可获得1点传承点数。",
		["Exalted with {faction:510} earns a Legacy Point."] = "{faction:510}达到崇拜可获得1点传承点数。",
		["Keep playing {zone:1461}. On Call to Arms: {zone:1461} weekends the {npc:15350} in the capitals takes three Arathi Basin Marks of Honor for extra reputation."] = "继续打{zone:1461}。在{zone:1461}战斗召集周末，主城里的{npc:15350}收取三枚阿拉希盆地荣誉奖章以给予额外声望。",
		["Keep playing {zone:1461}. On Call to Arms: {zone:1461} weekends the {npc:15351} in the capitals takes three Arathi Basin Marks of Honor for extra reputation."] = "继续打{zone:1461}。在{zone:1461}战斗召集周末，主城里的{npc:15351}收取三枚阿拉希盆地荣誉奖章以给予额外声望。",
		["Keep playing {zone:1461}; wins with many bases held pay the most."] = "继续打{zone:1461}；占领许多基地的胜利给得最多。",
		["League of Arathor to Exalted"] = "阿拉索联军刷到崇拜",
		["League of Arathor to Friendly"] = "阿拉索联军刷到友善",
		["League of Arathor to Honored"] = "阿拉索联军刷到尊敬",
		["League of Arathor to Revered"] = "阿拉索联军刷到崇敬",
		["{faction:509} fights for {zone:1461} from {area:320}. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:509}从{area:320}出发争夺{zone:1461}。他们的声望来自战场：你的队伍收集的资源会给每个人声望，所以占领更多基地、坚守更久就给得更多。在任何战场军官处排队。Forever的传承外交官特权可提高声望获取。",
		["{faction:510} fight for {zone:1461} from {area:321}. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:510}从{area:321}出发争夺{zone:1461}。他们的声望来自战场：你的队伍收集的资源会给每个人声望，所以占领更多基地、坚守更久就给得更多。在任何战场军官处排队。Forever的传承外交官特权可提高声望获取。",
		["{faction:510} to Exalted"] = "{faction:510}刷到崇拜",
		["{faction:510} to Friendly"] = "{faction:510}刷到友善",
		["{faction:510} to Honored"] = "{faction:510}刷到尊敬",
		["{faction:510} to Revered"] = "{faction:510}刷到崇敬",
		["{npc:14983}'s The Battle for {zone:1461}! (assault every base) and Control Four Bases / Control Five Bases are one-time quests; {npc:14984} beside him takes Arathi Resource Crates."] = "{npc:14983}的“{zone:1461}之战！”（突袭每座基地）以及“控制四座基地”/“控制五座基地”是一次性任务；他旁边的{npc:14984}收取{item:19725}。",
		["{npc:15021}'s The Battle for {zone:1461}! (assault every base) and Take Four Bases / Take Five Bases are one-time quests; {npc:15022} beside him takes Arathi Resource Crates."] = "{npc:15021}的“{zone:1461}之战！”（突袭每座基地）以及“夺取四座基地”/“夺取五座基地”是一次性任务；他旁边的{npc:15022}收取{item:19725}。",
		["{npc:15126} hands out one Defiler's care package by level"] = "{npc:15126}按等级发放一个污染者补给包",
		["{npc:15127} hands out one Arathor care package by level"] = "{npc:15127}按等级发放一个阿拉索补给包",
} end)()
t.guides["forever/reputation/argent-dawn"] = (function() return {
		["Argent Dawn Reputation"] = "银色黎明声望",
		["Corruptor's Scourgestones and dungeons to Revered"] = "用堕落者的天灾石和地下城刷到崇敬",
		["Dark Adepts and Shadowmages (level 58-60) drop Invader's Scourgestones here, along with Minion's stones and {item:14047}. Hand Invader's in 10 at a time and Minion's 20 at a time to {npc:11039} at {area:2268}. In Classic both stop giving reputation at Honored."] = "这里的黑暗教徒和暗影法师（58-60级）掉落侵略者的天灾石，还有爪牙的天灾石和{item:14047}。把侵略者的天灾石每10个、爪牙的天灾石每20个交给{area:2268}的{npc:11039}。在经典版中，两者到尊敬后就不再给声望。",
		["From Honored on, Corruptor's Scourgestones (one per turn-in) and Scourge kills in {area:2279} and {area:2057} carry the reputation. Corruptor's stones drop from the Scourge bosses there ({npc:1853}, {npc:10433}, Vectus) and from {npc:1852} and Putridius in {zone:1422}. Many dungeon runs pay off faster than any open-world farm."] = "从尊敬开始，声望来自堕落者的天灾石（每次交还一个）和在{area:2279}、{area:2057}中击杀天灾军团。堕落者的天灾石由那里的天灾首领（{npc:1853}、{npc:10433}、维克图斯）以及{zone:1422}的{npc:1852}和普特迪乌斯掉落。多刷地下城比任何野外刷怪都快。",
		["Ghouls and skeletons all over {zone:1422} drop Minion's Scourgestones about half the time; this cluster is dense. Hand them in 20 at a time to any Argent Officer (Pureheart at {area:3197}, Garush at {area:152}, {npc:11039} at {area:2268}). Each turn-in also pays an {item:12844} for the Argent quartermasters."] = "{zone:1422}各处的食尸鬼和骷髅约有一半几率掉落爪牙的天灾石；这一片怪物密集。每20个交给任意一位银色黎明军官（{area:3197}的普尔哈特、{area:152}的加鲁什、{area:2268}的{npc:11039}）。每次交还还会得到一枚{item:12844}，可在银色黎明军需官处使用。",
		["Invader's Scourgestones to Honored"] = "用侵略者的天灾石刷到尊敬",
		["Keep running {area:2279} and {area:2057} and turning in every {item:12843} at {area:2268} until Exalted."] = "继续刷{area:2279}和{area:2057}，并在{area:2268}交还每一个{item:12843}，直到崇拜。",
		["Minion's Scourgestones to Friendly"] = "用爪牙的天灾石刷到友善",
		["Run {area:2279} (both wings) and {area:2057}, killing every Scourge you pass."] = "刷{area:2279}（两个区域）和{area:2057}，击杀沿途所有天灾军团。",
		["{faction:529} to Exalted"] = "{faction:529}刷到崇拜",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10839} at {area:152} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160}初始为中立。从{area:152}的{npc:10839}处领取委任徽章并装备：在经典版中，只有装备了{quest:5401}饰品时才会掉落天灾石。Forever的传承外交官特权可提高声望获取。",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10840} at {area:3197} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160}初始为中立。从{area:3197}的{npc:10840}处领取委任徽章并装备：在经典版中，只有装备了{quest:5401}饰品时才会掉落天灾石。Forever的传承外交官特权可提高声望获取。",
		["{quest:5401} (Alliance)"] = "{quest:5401}（联盟）",
		["{quest:5401} (Horde)"] = "{quest:5401}（部落）",
} end)()
t.guides["forever/reputation/cenarion-circle"] = (function() return {
		["Abyssal Crests, Abyssal Signets and Abyssal Scepters are repeatable at {npc:15306} once their opening quests are done."] = "完成初始任务后，{item:20513}、{item:20514}和{item:20515}都可以在{npc:15306}处重复上交。",
		["Back to {area:3425}"] = "回到{area:3425}",
		["Cenarion Circle Reputation"] = "塞纳里奥议会声望",
		["Encrypted Twilight Texts repeats: {npc:15306} takes more texts again and again. The cultist camps are the place to farm them."] = "“暮光密文信”可重复：{npc:15306}会一次又一次收取更多密文。信徒营地就是刷它们的地方。",
		["Encrypted Twilight Texts to Friendly"] = "用{item:20404}刷到友善",
		["From here on, the {area:3454} raid and the Abyssal Council turn-ins (crests, signets, scepters) carry most of the reputation."] = "从这里开始，{area:3454}团队副本和深渊议会的上交物品（纹章、徽记、节杖）提供大部分声望。",
		["Keep farming the Twilight camps. Wearing the Twilight Trappings (the Twilight cultist set plus a Medallion of Station, from {npc:15282}'s Medallion of Station quest) lets you summon Abyssal Templars at the Wind Stones; their Abyssal Crests go to {npc:15306}."] = "继续刷暮光营地。穿上暮光信徒套装并带上暮光信徒身份勋章（来自{npc:15282}的“身份勋章”任务），就能在{object:180461}召唤深渊圣殿骑士；它们的{item:20513}交给{npc:15306}。",
		["Keep running the {area:3454} and turning in Abyssal Council insignia until Exalted."] = "继续刷{area:3454}并上交深渊议会的徽章，直到崇拜。",
		["Twilight's Hammer cultists hold the camps in western {zone:1451}. {quest:8320} and Stonecallers mix here; any cultist can drop an {item:20404}. Every cultist kill also counts toward the {faction:609}. The Geolords count for {quest:8320} only if you are 60 and took it."] = "暮光之锤的信徒占据着{zone:1451}西部的营地。{quest:8320}和暮光唤石者混在这里；任何信徒都可能掉落{item:20404}。每次击杀信徒也会提升{faction:609}声望。只有你60级并接了{quest:8320}时，击杀暮光地王才算数。",
		["{area:3425} is the walled town in north-central {zone:1451}. Bor and {npc:15270} stand together inside. The {faction:609} starts out Neutral. Forever's Legacy Diplomat perk increases reputation gains."] = "{area:3425}是{zone:1451}中北部有城墙的城镇。博尔和{npc:15270}一起站在里面。{faction:609}初始为中立。Forever的传承外交官特权可提高声望获取。",
		["{faction:609} to Exalted"] = "{faction:609}刷到崇拜",
		["{faction:609} to Honored"] = "{faction:609}刷到尊敬",
		["{faction:609} to Revered"] = "{faction:609}刷到崇敬",
		["{npc:15306}: Encrypted Twilight Texts"] = "{npc:15306}：暮光密文信",
		["{quest:8320} needs level 60"] = "{quest:8320}需要60级",
} end)()
t.guides["forever/reputation/darkspear-trolls"] = (function() return {
